(function (C) {
  Object.assign(C.characters, { driver: { name: 'Ông Sato (tài xế)', zh: '佐藤先生', face: '🚌' } });
  var hk3 = null; C.semesters.forEach(function (s) { if (s.id === 'hk3') hk3 = s; });
  hk3.locked = false; hk3.stage = 'Đại học năm 2'; hk3.age = 19; hk3.face = '🧑‍🎓';
  hk3.book = '发展汉语 高级口语（3）· 高级读写（3）';
  hk3.intro = 'Em đã lên đại học. Mỗi bài là một buổi seminar với bài khóa gốc dài, câu hỏi đọc hiểu, phân tích ngữ pháp, thảo luận nói tự do bằng mic và viết câu theo cấu trúc.';
  hk3.lessons = [{"id": "hk3-l1", "no": 1, "day": "HK3 · Bài 1", "time": "09:00", "scene": "classroom", "room": "classroom", "cast": ["prof", "tianfang", "lee", "roland"], "vi": "Hội thảo: niềm vui có lây lan không?", "zh": "快乐会传染", "py": "Kuàilè huì chuánrǎn", "vocab": [["传染", "chuánrǎn", "lây nhiễm, truyền nhiễm", ""], ["说到", "shuō dào", "nói về, đề cập đến", ""], ["不禁", "bùjīn", "không khỏi, không nhịn được", ""], ["皱起眉头", "zhòu qǐ méitóu", "cau mày, nhíu mày", ""], ["病毒", "bìngdú", "vi-rút", ""], ["联系", "liánxì", "liên hệ, kết nối", ""], ["事物", "shìwù", "sự vật, sự việc", ""], ["近距离", "jìn jùlí", "khoảng cách gần", ""], ["比如", "bǐrú", "ví dụ như", ""], ["水痘", "shuǐdòu", "bệnh thủy đậu", ""], ["打哈欠", "dǎ hāqian", "ngáp", ""], ["幸福", "xìngfú", "hạnh phúc", ""], ["研究人员", "yánjiū rényuán", "nhà nghiên cứu", ""], ["发表", "fābiǎo", "công bố, đăng tải", ""], ["报告", "bàogào", "báo cáo", ""], ["称", "chēng", "cho rằng, gọi là", ""], ["情绪", "qíngxù", "tình cảm, cảm xúc", ""], ["感染", "gǎnrǎn", "lây nhiễm, cảm nhiễm", ""], ["调查", "diàochá", "điều tra, khảo sát", ""], ["数据", "shùjù", "số liệu, dữ liệu", ""], ["显示", "xiǎnshì", "hiển thị, thể hiện", ""], ["社会", "shèhuì", "xã hội", ""], ["广泛", "guǎngfàn", "rộng rãi, phổ biến", ""], ["配偶", "pèi'ǒu", "vợ/chồng, bạn đời", ""], ["邻居", "línjū", "hàng xóm", ""], ["亲戚", "qīnqi", "họ hàng, người thân", ""], ["密切", "mìqiè", "mật thiết, gần gũi", ""], ["身边", "shēnbiān", "bên cạnh, xung quanh", ""], ["份", "fèn", "phần (lượng từ)", ""], ["更易", "gèng yì", "dễ hơn (càng dễ)", ""], ["直接", "zhíjiē", "trực tiếp", ""], ["社交", "shèjiāo", "giao tiếp xã hội", ""], ["对象", "duìxiàng", "đối tượng", ""], ["几率", "jǐlǜ", "xác suất, tỷ lệ", ""], ["增加", "zēngjiā", "tăng lên", ""], ["兄弟姐妹", "xiōngdì jiěmèi", "anh chị em", ""], ["层", "céng", "tầng, lớp", ""], ["圈", "quān", "vòng tròn, phạm vi", ""], ["项", "xiàng", "hạng mục (lượng từ)", ""], ["公布", "gōngbù", "công bố", ""]], "story": [{"c": "panda", "vi": "HK3 · Hội thảo: niềm vui có lây lan không?. Lớp học đại học: mọi người lần lượt đọc bài khóa gốc, giáo sư đặt câu hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "tianfang", "zh": "说到“传染”，很多人不禁会皱起眉头，因为“传染”通常是和“病毒”联系在一起的。我们知道很多事物都会近距离传染，比如感冒、水痘、打哈欠。那么幸福、快乐也会传染吗？", "py": "Shuō dào “Chuánrǎn”, hěnduō rén bùjīn huì zhòuqǐ méitóu, yīnwèi “Chuánrǎn” tōngcháng shì hé “Bìngdú” liánxì zài yìqǐ de. Wǒmen zhīdao hěnduō shìwù dōu huì jìnjùlí chuánrǎn, bǐrú gǎnmào, shuǐdòu, dǎhāqiàn. Nàme xìngfú, kuàilè yě huì chuánrǎn ma?", "vi": "Nói đến \"lây lan\", rất nhiều người không khỏi cau mày, bởi vì \"lây lan\" thường được liên hệ với \"vi-rút\". Chúng ta biết rất nhiều sự vật đều có thể lây lan ở khoảng cách gần, ví dụ như cảm cúm, thủy đậu, ngáp. Vậy hạnh phúc, niềm vui cũng có thể lây lan ư?"}, {"c": "prof", "zh": "说到“传染”，人们为什么会皱起眉头？", "py": "Shuō dào “Chuánrǎn”, rénmen wèishénme huì zhòuqǐ méitóu?", "vi": "Nói đến “lây lan”, vì sao người ta cau mày?"}, {"me": "Vì “lây lan” thường gắn với vi-rút.", "opts": [["因为“传染”通常和“病毒”联系在一起。", "Yīnwèi “Chuánrǎn” tōngcháng hé “Bìngdú” liánxì zài yìqǐ.", "Vì “lây lan” thường gắn với vi-rút."], ["因为快乐不会传染。", "Yīnwèi kuàilè búhuì chuánrǎn.", "(chưa đúng với nội dung đoạn văn)"], ["因为打哈欠很不礼貌。", "Yīnwèi dǎhāqiàn hěn bùlǐmào.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "lee", "zh": "研究人员在《英国医学期刊》上发表的研究报告中称，与快乐的人在一起，你自己也会更快乐。你周围的人越快乐，你也会越快乐。专家说：“这是一个情绪感染的问题。”", "py": "Yánjiū rényuán zài «Yīngguó yīxuéqīkān» shàng fābiǎo de yánjiū bàogào zhōngchēng, yǔ kuàilè de rén zài yìqǐ, nǐ zìjǐ yě huì gèng kuàilè. Nǐ zhōuwéi de rén yuè kuàilè, nǐ yě huì yuè kuàilè. Zhuānjiā shuō: “Zhèshì yíge qíngxù gǎnrǎn de wèntí.”", "vi": "Các nhà nghiên cứu cho biết trong báo cáo đăng trên Tạp chí Y học Anh rằng, ở cùng với người vui vẻ, bản thân bạn cũng sẽ vui vẻ hơn. Những người xung quanh bạn càng vui vẻ, bạn cũng sẽ càng vui vẻ. Chuyên gia nói: \"Đây là vấn đề cảm xúc bị lây nhiễm.\""}, {"c": "prof", "zh": "根据研究报告，怎样你会更快乐？", "py": "Gēnjù yánjiū bàogào, zěnyàng nǐ huì gèng kuàilè?", "vi": "Theo báo cáo, làm thế nào bạn sẽ vui hơn?"}, {"me": "Ở cùng người vui vẻ.", "opts": [["和快乐的人在一起。", "Hé kuàilè de rén zài yìqǐ.", "Ở cùng người vui vẻ."], ["一个人安静地生活。", "Yíge rén ānjìng dì shēnghuó.", "(chưa đúng với nội dung đoạn văn)"], ["多看医学期刊。", "Duō kàn yīxuéqīkān.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "roland", "zh": "调查数据显示，社会关系最广泛的人同时也最快乐，这些人与朋友、配偶、邻居和亲戚的联系都较为密切。专家说：“你身边多一个快乐的人，你就多一份快乐。”", "py": "Diàochá shùjù xiǎnshì, shèhuìguānxì zuì guǎngfàn de rén tóngshí yě zuì kuàilè, zhèxiē rén yǔ péngyou, pèiǒu, línjū hé qīnqi de liánxì dōu jiàowéi mìqiè. Zhuānjiā shuō: “Nǐ shēnbiān duō yíge kuàilè de rén, nǐ jiù duōyífèn kuàilè.”", "vi": "Số liệu điều tra cho thấy, những người có quan hệ xã hội rộng rãi nhất đồng thời cũng là những người vui vẻ nhất, họ có mối liên hệ khá mật thiết với bạn bè, vợ/chồng, hàng xóm và họ hàng. Chuyên gia nói: \"Bên cạnh bạn có thêm một người vui vẻ, bạn sẽ có thêm một phần niềm vui.\""}, {"c": "prof", "zh": "什么样的人最快乐？", "py": "Shénmeyàng de rén zuì kuàilè?", "vi": "Người như thế nào vui nhất?"}, {"me": "Người có quan hệ xã hội rộng nhất.", "opts": [["社会关系最广泛的人。", "Shèhuìguānxì zuì guǎngfàn de rén.", "Người có quan hệ xã hội rộng nhất."], ["收入最高的人。", "Shōurù zuìgāo de rén.", "(chưa đúng với nội dung đoạn văn)"], ["朋友最少的人。", "Péngyou zuìshǎo de rén.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "tianfang", "zh": "研究人员还发现，快乐比不快乐更易“传染”。如果你的直接社交对象很快乐，你快乐的几率会增加15%。如果你配偶或兄弟姐妹的朋友很快乐，你快乐的几率就会增加10%。如果你的第三层社交圈，如朋友的朋友很快乐，那么你快乐的几率会增加6%。但每多一个不快乐的朋友，你不快乐的几率会增加7%。", "py": "Yánjiū rényuán hái fāxiàn, kuàilè bǐ bú kuàilè gèng yì “Chuánrǎn”. Rúguǒ nǐ de zhíjiē shèjiāo duìxiàng hěn kuàilè, nǐ kuàilè de jīlǜ huì zēngjiā15%. Rúguǒ nǐ pèiǒu huò xiōngdìjiěmèi de péngyou hěn kuàilè, nǐ kuàilè de jīlǜ jiù huì zēngjiā10%. Rúguǒ nǐ de dìsāncéng shèjiāoquān, rú péngyou de péngyou hěn kuàilè, nàme nǐ kuàilè de jīlǜ huì zēngjiā6%. Dàn měi duō yíge bú kuàilè de péngyou, nǐ bú kuàilè de jīlǜ huì zēngjiā7%.", "vi": "Các nhà nghiên cứu còn phát hiện, niềm vui dễ \"lây\" hơn sự không vui. Nếu đối tượng giao tiếp trực tiếp của bạn rất vui vẻ, khả năng bạn vui vẻ tăng 15%. Nếu bạn của vợ/chồng hoặc anh chị em bạn rất vui vẻ, khả năng ấy tăng 10%. Nếu vòng giao tiếp thứ ba, như bạn của bạn, rất vui vẻ, khả năng tăng 6%. Nhưng mỗi khi có thêm một người bạn không vui, khả năng bạn không vui tăng 7%."}, {"c": "prof", "zh": "如果你的直接社交对象很快乐，你快乐的几率会增加多少？", "py": "Rúguǒ nǐ de zhíjiē shèjiāo duìxiàng hěn kuàilè, nǐ kuàilè de jīlǜ huì zēngjiā duōshao?", "vi": "Nếu người giao tiếp trực tiếp vui vẻ, khả năng bạn vui tăng bao nhiêu?"}, {"me": "Tăng 15%.", "opts": [["增加15%。", "Zēngjiā15%.", "Tăng 15%."], ["增加10%。", "Zēngjiā10%.", "(chưa đúng với nội dung đoạn văn)"], ["增加6%。", "Zēngjiā6%.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "lee", "zh": "这项新公布的研究结果显示，幸福可能会通过社交网络扩散，你交往的人越幸福，你也会感到越快乐。如果你的社交网络，比如朋友、家庭和配偶，他们中有人变得快乐，那也会增加你快乐的可能性。", "py": "Zhèxiàng xīn gōngbù de yánjiū jiéguǒxiǎnshì, xìngfú kěnéng huì tōngguò shèjiāo wǎngluò kuòsàn, nǐ jiāowǎng de rén yuè xìngfú, nǐ yě huì gǎndào yuè kuàilè. Rúguǒ nǐ de shèjiāo wǎngluò, bǐrú péngyou, jiātíng hé pèiǒu, tāmen zhōng yǒurén biànde kuàilè, nà yě huì zēngjiā nǐ kuàilè de kěnéngxìng.", "vi": "Kết quả nghiên cứu mới công bố này cho thấy, hạnh phúc có thể lan tỏa qua mạng lưới xã hội; người bạn giao tiếp càng hạnh phúc, bạn càng cảm thấy vui vẻ. Nếu trong mạng lưới xã hội của bạn, như bạn bè, gia đình và vợ/chồng, có ai đó trở nên vui vẻ, điều đó cũng làm tăng khả năng bạn vui vẻ."}, {"c": "prof", "zh": "研究结果显示，幸福可能会通过什么扩散？", "py": "Yánjiū jiéguǒxiǎnshì, xìngfú kěnéng huì tōngguò shénme kuòsàn?", "vi": "Kết quả cho thấy hạnh phúc có thể lan qua đâu?"}, {"me": "Lan qua mạng lưới xã hội.", "opts": [["通过社交网络扩散。", "Tōngguò shèjiāo wǎngluò kuòsàn.", "Lan qua mạng lưới xã hội."], ["通过病毒扩散。", "Tōngguò bìngdú kuòsàn.", "(chưa đúng với nội dung đoạn văn)"], ["通过医学期刊扩散。", "Tōngguò yīxuéqīkān kuòsàn.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "越……越……", "d": "A 越 + tính từ, B 越 + tính từ: hai sự việc cùng tăng. Sau 越 không thêm 很.", "ex": [["你周围的人越快乐，你也会越快乐。", "Nǐ zhōuwéi de rén yuè kuàilè, nǐ yě huì yuè kuàilè.", "Người xung quanh bạn càng vui, bạn càng vui."]]}, {"t": "无论……还是……都……", "d": "Bất kể A hay B đều…; vế sau dùng 都 (không dùng 就).", "ex": [["无论面对的是快乐还是痛苦，都需要有人分享。", "Wúlùn miànduì de shì kuàilè háishì tòngkǔ, dōu xūyào yǒurén fēnxiǎng.", "Dù đối mặt niềm vui hay nỗi đau, đều cần có người chia sẻ."]]}, {"t": "居然", "d": "Không ngờ lại… (điều trái với dự đoán). Là phó từ, đứng trước động từ.", "ex": [["他居然在安息日出门打高尔夫球。", "Tā jūrán zài ānxīrì chūmén dǎ gāoěrfūqiú.", "Ông ấy vậy mà ra ngoài đánh gôn vào ngày Sabbath."]]}, {"t": "不是……吗？(câu hỏi tu từ)", "d": "Dùng để khẳng định mạnh: “chẳng phải… sao?”.", "ex": [["这不是最好的惩罚吗？", "Zhè búshì zuìhǎo de chéngfá ma?", "Đó chẳng phải là hình phạt tốt nhất sao?"]]}, {"t": "通过 + N", "d": "Thông qua cái gì để đạt kết quả.", "ex": [["幸福可能会通过社交网络扩散。", "Xìngfú kěnéng huì tōngguò shèjiāo wǎngluò kuòsàn.", "Hạnh phúc có thể lan qua mạng xã hội."]]}], "order": [], "u": {"gq": [{"s": "越……越……", "d": "A 越 + tính từ, B 越 + tính từ: hai sự việc cùng tăng. Sau 越 không thêm 很.", "ok": "你周围的人越快乐，你也会越快乐。", "vi": "Người xung quanh bạn càng vui, bạn càng vui.", "bad": ["你周围的人越快乐，你也会很越快乐。", "越你周围的人快乐，越你也会快乐。"]}, {"s": "无论……还是……都……", "d": "Bất kể A hay B đều…; vế sau dùng 都 (không dùng 就).", "ok": "无论面对的是快乐还是痛苦，都需要有人分享。", "vi": "Dù đối mặt niềm vui hay nỗi đau, đều cần có người chia sẻ.", "bad": ["无论面对的是快乐还是痛苦，就需要有人分享。", "虽然面对的是快乐还是痛苦，都需要有人分享。"]}, {"s": "居然", "d": "Không ngờ lại… (điều trái với dự đoán). Là phó từ, đứng trước động từ.", "ok": "他居然在安息日出门打高尔夫球。", "vi": "Ông ấy vậy mà ra ngoài đánh gôn vào ngày Sabbath.", "bad": ["他在安息日出门居然打高尔夫球了吗。", "居然他在安息日出门，打高尔夫球居然。"]}, {"s": "不是……吗？(câu hỏi tu từ)", "d": "Dùng để khẳng định mạnh: “chẳng phải… sao?”.", "ok": "这不是最好的惩罚吗？", "vi": "Đó chẳng phải là hình phạt tốt nhất sao?", "bad": ["这是不最好的惩罚吗？", "这不是最好的惩罚呢吗？"]}, {"s": "通过 + N", "d": "Thông qua cái gì để đạt kết quả.", "ok": "幸福可能会通过社交网络扩散。", "vi": "Hạnh phúc có thể lan qua mạng xã hội.", "bad": ["幸福可能会扩散通过社交网络。", "幸福通过可能会社交网络扩散。"]}], "disc": [{"q": "你同意“快乐会传染”这个说法吗？为什么？", "py": "Nǐ tóngyì “Kuàilè huì chuánrǎn” zhège shuōfǎ ma? Wèishénme?", "vi": "Bạn có đồng ý “niềm vui có thể lây lan” không? Vì sao?", "keys": ["越……越", "如果", "因为|比"], "sample": "我同意。我觉得情绪是会感染的。如果身边的朋友很快乐，我也会越来越快乐，因为快乐比不快乐更容易传染。", "spy": "Wǒ tóngyì. Wǒ juéde qíngxù shì huì gǎnrǎn de. Rúguǒ shēnbiān de péngyou hěn kuàilè, wǒ yě huì yuèláiyuè kuàilè, yīnwèi kuàilè bǐ bú kuàilè gèng róngyì chuánrǎn."}, {"q": "上帝为什么说这是“最好的惩罚”？你有过想分享却不能分享的经历吗？", "py": "Shàngdì wèishénme shuō zhè shì “Zuìhǎo de chéngfá”? Nǐ yǒu guò xiǎng fēnxiǎng què bùnéng fēnxiǎng de jīnglì ma?", "vi": "Vì sao Thượng đế nói đây là “hình phạt tốt nhất”? Bạn từng muốn chia sẻ mà không thể chưa?", "keys": ["分享", "无论……还是|无论……都", "不是……吗|却"], "sample": "因为快乐需要分享。长老打得那么好，却不能跟任何人说，这不是最好的惩罚吗？无论是快乐还是痛苦，我都想跟朋友分享。", "spy": "Yīnwèi kuàilè xūyào fēnxiǎng. Zhǎnglǎo dǎ de nàme hǎo, què bùnéng gēn rènhérén shuō, zhè búshì zuìhǎo de chéngfá ma? Wúlùnshì kuàilè háishì tòngkǔ, wǒ dōu xiǎng gēn péngyou fēnxiǎng."}], "comp": [{"vi": "Càng luyện nói nhiều, bạn nói tiếng Trung càng lưu loát. (dùng 越……越……)", "keys": ["越……越"], "model": "你练习得越多，汉语就说得越流利。", "mpy": "Nǐ liànxí de yuè duō, hànyǔ jiù shuō de yuè liúlì."}, {"vi": "Dù trời nắng hay mưa, anh ấy đều đi chạy bộ. (dùng 无论……还是……都……)", "keys": ["无论", "还是", "都"], "model": "无论晴天还是下雨，他都去跑步。", "mpy": "Wúlùn qíngtiān háishì xiàyǔ, tā dōu qù pǎobù."}, {"vi": "Không ngờ cậu ấy lại đạt điểm tối đa. (dùng 居然)", "keys": ["居然"], "model": "他居然考了满分。", "mpy": "Tā jūrán kǎole mǎnfēn."}], "ex": [{"q": "说到“传染”，人们为什么会皱起眉头？", "qvi": "Nói đến “lây lan”, vì sao người ta cau mày?", "a": "因为“传染”通常和“病毒”联系在一起。", "avi": "Vì “lây lan” thường gắn với vi-rút.", "bad": ["因为快乐不会传染。", "因为打哈欠很不礼貌。"], "p": 0}, {"q": "根据研究报告，怎样你会更快乐？", "qvi": "Theo báo cáo, làm thế nào bạn sẽ vui hơn?", "a": "和快乐的人在一起。", "avi": "Ở cùng người vui vẻ.", "bad": ["一个人安静地生活。", "多看医学期刊。"], "p": 1}, {"q": "什么样的人最快乐？", "qvi": "Người như thế nào vui nhất?", "a": "社会关系最广泛的人。", "avi": "Người có quan hệ xã hội rộng nhất.", "bad": ["收入最高的人。", "朋友最少的人。"], "p": 2}, {"q": "如果你的直接社交对象很快乐，你快乐的几率会增加多少？", "qvi": "Nếu người giao tiếp trực tiếp vui vẻ, khả năng bạn vui tăng bao nhiêu?", "a": "增加15%。", "avi": "Tăng 15%.", "bad": ["增加10%。", "增加6%。"], "p": 3}, {"q": "研究结果显示，幸福可能会通过什么扩散？", "qvi": "Kết quả cho thấy hạnh phúc có thể lan qua đâu?", "a": "通过社交网络扩散。", "avi": "Lan qua mạng lưới xã hội.", "bad": ["通过病毒扩散。", "通过医学期刊扩散。"], "p": 4}, {"q": "上帝对长老的惩罚是什么？", "qvi": "Hình phạt của Thượng đế với trưởng lão là gì?", "a": "让他打出惊人的成绩，却不能跟任何人说。", "avi": "Cho ông thành tích kinh người nhưng không thể kể với ai.", "bad": ["让他一个洞也打不进。", "不让他再打高尔夫球。"], "p": -1}]}}, {"id": "hk3-l2", "no": 2, "day": "HK3 · Bài 2", "time": "14:30", "scene": "library", "room": "library", "cast": ["prof", "zhangdong", "tianfang", "edward"], "vi": "Thư viện: bàn về giải trí và trò chơi", "zh": "休闲与游戏", "py": "Xiūxián yǔ yóuxì", "vocab": [["如今", "rújīn", "ngày nay, hiện nay", ""], ["休闲", "xiūxián", "nghỉ ngơi, thư giãn, giải trí", ""], ["成为", "chéngwéi", "trở thành", ""], ["内容", "nèiróng", "nội dung", ""], ["社会", "shèhuì", "xã hội", ""], ["发展", "fāzhǎn", "phát triển", ""], ["规律", "guīlǜ", "quy luật", ""], ["文明", "wénmíng", "văn minh", ""], ["程度", "chéngdù", "trình độ, mức độ", ""], ["价值", "jiàzhí", "giá trị", ""], ["不言而喻", "bùyán'éryù", "không cần nói cũng hiểu, hiển nhiên", ""], ["活动", "huódòng", "hoạt động", ""], ["自然", "zìrán", "tự nhiên", ""], ["成长", "chéngzhǎng", "trưởng thành, lớn lên", ""], ["出现", "chūxiàn", "xuất hiện", ""], ["问题", "wèntí", "vấn đề", ""], ["文化", "wénhuà", "văn hóa", ""], ["传统", "chuántǒng", "truyền thống", ""], ["强调", "qiángdiào", "nhấn mạnh", ""], ["心灵", "xīnlíng", "tâm hồn, tinh thần", ""], ["保持", "bǎochí", "duy trì, giữ gìn", ""], ["清净", "qīngjìng", "thanh tịnh, trong sạch", ""], ["承担", "chéngdān", "gánh vác, đảm nhận", ""], ["疲惫", "píbèi", "mệt mỏi", ""], ["头脑", "tóunǎo", "đầu óc", ""], ["清醒", "qīngxǐng", "tỉnh táo", ""], ["心情", "xīnqíng", "tâm trạng", ""], ["平和", "pínghé", "bình hòa, ôn hòa", ""], ["冷静", "lěngjìng", "bình tĩnh", ""], ["认真", "rènzhēn", "nghiêm túc", ""], ["思考", "sīkǎo", "suy nghĩ", ""], ["目光短浅", "mùguāng duǎnqiǎn", "tầm nhìn ngắn hạn, thiển cận", ""], ["高瞻远瞩", "gāozhānyuǎnzhǔ", "nhìn xa trông rộng", ""], ["尤其", "yóuqí", "đặc biệt là", ""], ["游戏", "yóuxì", "trò chơi", ""], ["成长过程", "chéngzhǎng guòchéng", "quá trình trưởng thành", ""], ["作用", "zuòyòng", "tác dụng, vai trò", ""], ["基础", "jīchǔ", "cơ sở, nền tảng", ""], ["课堂", "kètáng", "lớp học", ""], ["培养", "péiyǎng", "bồi dưỡng, đào tạo", ""]], "story": [{"c": "panda", "vi": "HK3 · Thư viện: bàn về giải trí và trò chơi. Lớp học đại học: mọi người lần lượt đọc bài khóa gốc, giáo sư đặt câu hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "zhangdong", "zh": "如今，“休闲”已成为我们每个人生活中的重要内容。从社会发展的规律看，社会文明程度越高，休闲时间就越多。休闲的价值不言而喻，没有休闲活动，人的自然成长都会出现问题。", "py": "Rújīn, “Xiūxián” yǐ chéngwéi wǒmen měige rén shēnghuó zhōng de zhòngyào nèiróng. Cóng shèhuì fāzhǎn de guīlǜ kàn, shèhuì wénmíng chéngdù yuègāo, xiūxián shíjiān jiù yuè duō. Xiūxián de jiàzhí bùyánéryù, méiyǒu xiūxiánhuódòng, rén de zìrán chéngzhǎng dōu huì chūxiàn wèntí.", "vi": "Ngày nay, \"nghỉ ngơi giải trí\" đã trở thành nội dung quan trọng trong cuộc sống của mỗi chúng ta. Xét theo quy luật phát triển xã hội, trình độ văn minh càng cao thì thời gian nhàn rỗi càng nhiều. Giá trị của giải trí là điều không cần nói cũng rõ; không có hoạt động giải trí, ngay cả sự trưởng thành tự nhiên của con người cũng sẽ gặp vấn đề."}, {"c": "prof", "zh": "作者认为社会文明程度和休闲时间有什么关系？", "py": "Zuòzhě rènwéi shèhuì wénmíng chéngdù hé xiūxián shíjiān yǒu shénme guānxi?", "vi": "Tác giả cho rằng văn minh xã hội và thời gian rảnh liên quan thế nào?"}, {"me": "Văn minh càng cao, thời gian rảnh càng nhiều.", "opts": [["社会文明程度越高，休闲时间就越多。", "Shèhuì wénmíng chéngdù yuègāo, xiūxián shíjiān jiù yuè duō.", "Văn minh càng cao, thời gian rảnh càng nhiều."], ["社会越发达，人越没有时间休闲。", "Shèhuì yuè fādá, rényuè méiyǒu shíjiān xiūxián.", "(chưa đúng với nội dung đoạn văn)"], ["两者没有关系。", "Liǎngzhě méiyǒu guānxi.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "tianfang", "zh": "中国的文化传统是强调休闲的，人的心灵要保持清净，如果承担的工作太多，心灵就会疲惫。因为人一忙就容易乱，头脑不清醒；心情不能平和，不能冷静认真地思考；人一忙就容易目光短浅，不能高瞻远瞩。对现代人来讲，休闲尤其重要。", "py": "Zhōngguó de wénhuà chuántǒng shì qiángdiào xiūxián de, rén de xīnlíng yào bǎochí qīngjìng, rúguǒ chéngdān de gōngzuò tài duō, xīnlíng jiù huì píbèi. Yīnwèi rényìmáng jiù róngyì luàn, tóunǎo bù qīngxǐng; xīnqíng bùnéng pínghé, bùnéng lěngjìng rènzhēn dì sīkǎo; rényìmáng jiù róngyì mùguāngduǎnqiǎn, bùnéng gāozhānyuǎnzhǔ. Duì xiàndàirén láijiǎng, xiūxián yóuqí zhòngyào.", "vi": "Truyền thống văn hóa Trung Quốc coi trọng sự thư nhàn: tâm hồn cần giữ thanh tịnh, nếu gánh vác quá nhiều việc, tâm hồn sẽ mệt mỏi. Vì người ta hễ bận là dễ rối, đầu óc không tỉnh táo; tâm trạng không bình hòa, không thể suy nghĩ bình tĩnh, nghiêm túc; hễ bận là dễ có tầm nhìn hạn hẹp, không thể nhìn xa trông rộng. Đối với người hiện đại, giải trí càng đặc biệt quan trọng."}, {"c": "prof", "zh": "为什么说人太忙不好？", "py": "Wèishénme shuō réntàimáng bùhǎo?", "vi": "Vì sao nói quá bận là không tốt?"}, {"me": "Hễ bận là dễ rối, tầm nhìn hạn hẹp.", "opts": [["人一忙就容易乱，目光短浅。", "Rényìmáng jiù róngyì luàn, mùguāngduǎnqiǎn.", "Hễ bận là dễ rối, tầm nhìn hạn hẹp."], ["人一忙就有更多休闲时间。", "Rényìmáng jiù yǒu gèng duō xiūxián shíjiān.", "(chưa đúng với nội dung đoạn văn)"], ["人一忙就更有智慧。", "Rényìmáng jiù gèng yǒu zhìhuì.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "edward", "zh": "游戏在人的成长过程中有着重要的作用：一是人的生活中不能没有游戏，二是游戏是创造的基础，三是游戏是人的学习课堂，四是游戏培养人的智慧，五是游戏可以锻炼人的勇气。可以说，玩是人生的根本需要之一。我这里的玩，指的是积极、健康、友好、多样性的游戏种类，包括静态的、动态的、益智的、健身的、简单的、复杂的，舒缓的、激烈的，户内的、户外的，等等。", "py": "Yóuxì zài rén de chéngzhǎng guòchéng zhōng yǒuzhe zhòngyào de zuòyòng: Yíshì rén de shēnghuó zhōng bùnéng méiyǒu yóuxì, èrshì yóuxì shì chuàngzào de jīchǔ, sānshì yóuxì shì rén de xuéxí kètáng, sìshì yóuxì péiyǎng rén de zhìhuì, wǔshì yóuxì kěyǐ duànliàn rén de yǒngqì. Kěyǐ shuō, wán shì rénshēng de gēnběn xūyào zhīyī. Wǒ zhèlǐ de wán, zhǐ de shì jījí, jiànkāng, yǒuhǎo, duōyàngxìng de yóuxì zhǒnglèi, bāokuò jìngtài de, dòngtài de, yìzhì de, jiànshēn de, jiǎndān de, fùzá de, shūhuǎn de, jīliè de, hùnèi de, hùwài de, děngděng.", "vi": "Trò chơi có vai trò quan trọng trong quá trình trưởng thành: một là đời sống không thể thiếu trò chơi, hai là trò chơi là nền tảng của sáng tạo, ba là trò chơi là lớp học của con người, bốn là trò chơi bồi dưỡng trí tuệ, năm là trò chơi rèn luyện lòng dũng cảm. Có thể nói, chơi là một trong những nhu cầu căn bản của đời người. \"Chơi\" ở đây là các loại trò chơi tích cực, lành mạnh, thân thiện, đa dạng: tĩnh và động, rèn trí và rèn thân, đơn giản và phức tạp, nhẹ nhàng và sôi nổi, trong nhà và ngoài trời…"}, {"c": "prof", "zh": "作者说的“玩”指的是什么？", "py": "Zuòzhě shuō de “Wán” zhǐ de shì shénme?", "vi": "“Chơi” mà tác giả nói là gì?"}, {"me": "Trò chơi tích cực, lành mạnh, thân thiện, đa dạng.", "opts": [["积极、健康、友好、多样性的游戏。", "Jījí, jiànkāng, yǒuhǎo, duōyàngxìng de yóuxì.", "Trò chơi tích cực, lành mạnh, thân thiện, đa dạng."], ["只是户外运动。", "Zhǐshì hùwàiyùndòng.", "(chưa đúng với nội dung đoạn văn)"], ["打麻将赌博。", "Dǎmájiāng dǔbó.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "zhangdong", "zh": "鲁迅曾说过：游戏是儿童最正当的行为。因为玩能教人许多道理，能展开他们想象的翅膀，激发他们的兴趣，发现他们的爱好，培养他们的专长。当然，有人会玩物丧志，那不是游戏的错，而是游戏者没有掌握好“度”。如果玩过了头，那是家长或学校没有指导好。", "py": "Lǔxùn céng shuō guò: Yóuxì shì értóng zuì zhèngdāng de xíngwéi. Yīnwèi wánnéng jiàorén xǔduō dàolǐ, néng zhǎnkāi tāmen xiǎngxiàng de chìbǎng, jīfā tāmen de xìngqù, fāxiàn tāmen de àihào, péiyǎng tāmen de zhuāncháng. Dāngrán, yǒurén huì wánwùsàngzhì, nà búshì yóuxì de cuò, érshì yóuxì zhě méiyǒu zhǎngwò hǎo “Dù”. Rúguǒ wánguò le tóu, nà shì jiāzhǎng huò xuéxiào méiyǒu zhǐdǎo hǎo.", "vi": "Lỗ Tấn từng nói: trò chơi là hành vi chính đáng nhất của trẻ em. Vì chơi dạy người ta nhiều đạo lý, chắp cánh trí tưởng tượng, khơi dậy hứng thú, giúp phát hiện sở thích và bồi dưỡng sở trường. Đương nhiên, có người ham chơi mà mất ý chí, nhưng đó không phải lỗi của trò chơi, mà là người chơi chưa nắm vững \"chừng mực\". Nếu chơi quá đà, đó là do phụ huynh hoặc nhà trường chưa hướng dẫn tốt."}, {"c": "prof", "zh": "有人玩物丧志，作者认为是谁的错？", "py": "Yǒurén wánwùsàngzhì, zuòzhě rènwéi shì shuí de cuò?", "vi": "Có người ham chơi mất ý chí, tác giả cho là lỗi của ai?"}, {"me": "Không phải lỗi trò chơi mà do người chơi không giữ chừng mực.", "opts": [["不是游戏的错，而是游戏者没掌握好“度”。", "Búshì yóuxì de cuò, érshì yóuxì zhě méi zhǎngwò hǎo “Dù”.", "Không phải lỗi trò chơi mà do người chơi không giữ chừng mực."], ["是游戏本身的错。", "Shì yóuxì běnshēn de cuò.", "(chưa đúng với nội dung đoạn văn)"], ["是鲁迅的错。", "Shì lǔxùn de cuò.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "tianfang", "zh": "休闲时间是人们用来放松、思考、欣赏、创造的。一些传统的游戏，比如麻将，在中国已流行了几百年，是人们喜闻乐见的游戏。但是，麻将在中国有“异化”的趋势，有些人把它变成了赌博工具。有人把赌博现象归罪于麻将，显然是人的智慧出了问题，是人在逃避责任。我们对这种文化产物，有责任爱护它，让它在人们休闲活动中健康地发挥效用。", "py": "Xiūxián shíjiān shì rénmen yònglái fàngsōng, sīkǎo, xīnshǎng, chuàngzào de. Yìxiē chuántǒng de yóuxì, bǐrú májiāng, zài zhōngguó yǐ liúxíng le jǐbǎinián, shì rénmen xǐwénlèjiàn de yóuxì. Dànshì, májiāng zài zhōngguó yǒu “Yìhuà” de qūshì, yǒuxiē rén bǎ tā biànchéng le dǔbó gōngjù. Yǒurén bǎ dǔbó xiànxiàng guīzuìyú májiāng, xiǎnrán shì rén de zhìhuì chū le wèntí, shì rén zài táobìzérèn. Wǒmen duì zhèzhǒng wénhuà chǎnwù, yǒu zérèn àihù tā, ràng tā zài rénmen xiūxiánhuódòng zhōng jiànkāng dì fāhuī xiàoyòng.", "vi": "Thời gian nhàn rỗi là để con người thư giãn, suy ngẫm, thưởng thức và sáng tạo. Một số trò chơi truyền thống như mạt chược đã thịnh hành ở Trung Quốc mấy trăm năm, được mọi người ưa chuộng. Thế nhưng mạt chược có xu hướng bị \"biến chất\", có người biến nó thành công cụ cờ bạc. Có người đổ tội cờ bạc cho mạt chược – rõ ràng là trí tuệ con người có vấn đề, là con người đang trốn tránh trách nhiệm. Với sản phẩm văn hóa này, chúng ta có trách nhiệm gìn giữ, để nó phát huy tác dụng lành mạnh trong đời sống giải trí."}, {"c": "prof", "zh": "作者怎么看把赌博归罪于麻将？", "py": "Zuòzhě zěnme kàn bǎ dǔbó guīzuìyú májiāng?", "vi": "Tác giả nghĩ gì về việc đổ tội cờ bạc cho mạt chược?"}, {"me": "Đó là con người trốn tránh trách nhiệm.", "opts": [["那是人在逃避责任。", "Nà shì rén zài táobìzérèn.", "Đó là con người trốn tránh trách nhiệm."], ["麻将应该被禁止。", "Májiāng yīnggāi bèi jìnzhǐ.", "(chưa đúng với nội dung đoạn văn)"], ["麻将本来就是赌博工具。", "Májiāng běnlái jiùshì dǔbó gōngjù.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "edward", "zh": "休闲，游戏使我们的生活丰富多彩。近些年来，人们越来越远离休闲和游戏，尤其是孩子们玩的时间太少，成年人和老年人可选择的玩种类也不多。我十几年前就关注这个问题，也多次谈到中国的大学应该有一门游戏理论课程。休闲时间越多，如何休闲的问题就越重要。从个人方面看，如何用好时间，使生活更愉快、更充实的问题；从社会方面看，如何帮助和引导人们支配好空闲时间的问题。", "py": "Xiūxián, yóuxì shǐ wǒmen de shēnghuó fēngfùduōcǎi. Jìnxiēniánlái, rénmen yuèláiyuè yuǎnlí xiūxián hé yóuxì, yóuqí shì háizi men wán de shíjiān tài shǎo, chéngniánrén hé lǎoniánrén kě xuǎnzé de wán zhǒnglèi yě bù duō. Wǒ shíjǐnián qián jiù guānzhù zhège wèntí, yě duōcì tándào zhōngguó de dàxué yīnggāi yǒu yìmén yóuxì lǐlùn kèchéng. Xiūxián shíjiān yuè duō, rúhé xiūxián de wèntí jiù yuè zhòngyào. Cóng gerén fāngmiàn kàn, rúhé yòng hǎo shíjiān, shǐ shēnghuó gèng yúkuài, gèng chōngshí de wèntí; cóng shèhuì fāngmiàn kàn, rúhé bāngzhù hé yǐndǎo rénmen zhīpèi hǎo kòngxián shíjiān de wèntí.", "vi": "Giải trí và trò chơi làm cuộc sống phong phú, nhiều màu sắc. Những năm gần đây, con người ngày càng xa rời giải trí và trò chơi, nhất là trẻ em có quá ít thời gian chơi, người lớn và người già cũng ít loại hình vui chơi để chọn. Từ mười mấy năm trước tôi đã quan tâm vấn đề này, nhiều lần nói các trường đại học Trung Quốc nên có môn lý luận trò chơi. Thời gian nhàn rỗi càng nhiều, vấn đề giải trí thế nào càng quan trọng: về cá nhân, là làm sao dùng tốt thời gian để sống vui và đầy đặn hơn; về xã hội, là làm sao giúp và hướng dẫn mọi người sắp xếp tốt thời gian rảnh."}, {"c": "prof", "zh": "作者建议中国的大学应该怎么做？", "py": "Zuòzhě jiànyì zhōngguó de dàxué yīnggāi zěnme zuò?", "vi": "Tác giả đề nghị đại học Trung Quốc nên làm gì?"}, {"me": "Mở một môn lý luận trò chơi.", "opts": [["开一门游戏理论课程。", "Kāi yìmén yóuxì lǐlùn kèchéng.", "Mở một môn lý luận trò chơi."], ["取消学生的休闲时间。", "Qǔxiāo xuéshēng de xiūxián shíjiān.", "(chưa đúng với nội dung đoạn văn)"], ["让学生多打麻将。", "Ràng xuéshēng duō dǎmájiāng.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "一……就……", "d": "Hễ… là…: điều kiện dẫn tới kết quả ngay.", "ex": [["人一忙就容易乱。", "Rényìmáng jiù róngyì luàn.", "Người ta hễ bận là dễ rối."]]}, {"t": "不是……而是……", "d": "Phủ định A, khẳng định B.", "ex": [["那不是游戏的错，而是游戏者没有掌握好“度”。", "Nà búshì yóuxì de cuò, érshì yóuxì zhě méiyǒu zhǎngwò hǎo “Dù”.", "Đó không phải lỗi của trò chơi mà là người chơi không giữ chừng mực."]]}, {"t": "对……来讲 / 来说", "d": "Đối với… mà nói.", "ex": [["对现代人来讲，休闲尤其重要。", "Duì xiàndàirén láijiǎng, xiūxián yóuqí zhòngyào.", "Đối với người hiện đại, giải trí đặc biệt quan trọng."]]}, {"t": "把 + A + 归罪于 + B", "d": "Đổ tội A cho B (câu 把).", "ex": [["有人把赌博现象归罪于麻将。", "Yǒurén bǎ dǔbó xiànxiàng guīzuìyú májiāng.", "Có người đổ tội hiện tượng cờ bạc cho mạt chược."]]}, {"t": "从……方面看", "d": "Xét từ phương diện….", "ex": [["从个人方面看，如何用好时间很重要。", "Cóng gerén fāngmiàn kàn, rúhé yòng hǎo shíjiān hěn zhòngyào.", "Xét về cá nhân, dùng tốt thời gian rất quan trọng."]]}], "order": [], "u": {"gq": [{"s": "一……就……", "d": "Hễ… là…: điều kiện dẫn tới kết quả ngay.", "ok": "人一忙就容易乱。", "vi": "Người ta hễ bận là dễ rối.", "bad": ["人一忙才容易乱。", "一人忙就容易乱。"]}, {"s": "不是……而是……", "d": "Phủ định A, khẳng định B.", "ok": "那不是游戏的错，而是游戏者没有掌握好“度”。", "vi": "Đó không phải lỗi của trò chơi mà là người chơi không giữ chừng mực.", "bad": ["那不是游戏的错，但是游戏者没有掌握好“度”。", "那是不游戏的错，而是游戏者没有掌握好“度”。"]}, {"s": "对……来讲 / 来说", "d": "Đối với… mà nói.", "ok": "对现代人来讲，休闲尤其重要。", "vi": "Đối với người hiện đại, giải trí đặc biệt quan trọng.", "bad": ["对现代人讲来，休闲尤其重要。", "对于现代人来说的，休闲尤其重要。"]}, {"s": "把 + A + 归罪于 + B", "d": "Đổ tội A cho B (câu 把).", "ok": "有人把赌博现象归罪于麻将。", "vi": "Có người đổ tội hiện tượng cờ bạc cho mạt chược.", "bad": ["有人归罪于麻将把赌博现象。", "有人把赌博现象归罪麻将于。"]}, {"s": "从……方面看", "d": "Xét từ phương diện….", "ok": "从个人方面看，如何用好时间很重要。", "vi": "Xét về cá nhân, dùng tốt thời gian rất quan trọng.", "bad": ["从个人看方面，如何用好时间很重要。", "个人方面从看，如何用好时间很重要。"]}], "disc": [{"q": "你平时怎么休闲？你觉得休闲对大学生重要吗？", "py": "Nǐ píngshí zěnme xiūxián? Nǐ juéde xiūxián duì dàxuéshēng zhòngyào ma?", "vi": "Bạn thường giải trí thế nào? Giải trí có quan trọng với sinh viên không?", "keys": ["对……来说|对……来讲", "一……就", "越……越"], "sample": "对大学生来说，休闲非常重要。我一忙就容易紧张，所以周末我常常去爬山。休闲得越好，学习效率就越高。", "spy": "Duì dàxuéshēng láishuō, xiūxián fēicháng zhòngyào. Wǒ yìmáng jiù róngyì jǐnzhāng, suǒyǐ zhōumò wǒ chángcháng qù páshān. Xiūxián de yuè hǎo, xuéxí xiàolǜ jiù yuè gāo."}, {"q": "有人说玩游戏是浪费时间，你同意吗？", "py": "Yǒurén shuō wányóuxì shì làngfèishíjiān, nǐ tóngyì ma?", "vi": "Có người nói chơi game là phí thời gian, bạn đồng ý không?", "keys": ["不是……而是", "如果", "度"], "sample": "我不同意。玩游戏不是浪费时间，而是一种学习。如果掌握好“度”，游戏可以培养人的智慧和勇气。", "spy": "Wǒ bù tóngyì. Wányóuxì búshì làngfèishíjiān, érshì yìzhǒng xuéxí. Rúguǒ zhǎngwò hǎo “Dù”, yóuxì kěyǐ péiyǎng rén de zhìhuì hé yǒngqì."}], "comp": [{"vi": "Vấn đề không phải ở điện thoại, mà ở cách người ta dùng nó. (不是……而是……)", "keys": ["不是", "而是"], "model": "问题不是手机，而是人们怎么使用它。", "mpy": "Wèntí búshì shǒujī, érshì rénmen zěnme shǐyòng tā."}, {"vi": "Đối với sinh viên, thời gian rất quý. (对……来说)", "keys": ["对", "来说|来讲"], "model": "对大学生来说，时间非常宝贵。", "mpy": "Duì dàxuéshēng láishuō, shíjiān fēicháng bǎoguì."}, {"vi": "Cậu ấy hễ rảnh là đi chơi bóng rổ. (一……就……)", "keys": ["一", "就"], "model": "他一有空就去打篮球。", "mpy": "Tā yì yǒukòng jiù qù dǎlánqiú."}], "ex": [{"q": "作者认为社会文明程度和休闲时间有什么关系？", "qvi": "Tác giả cho rằng văn minh xã hội và thời gian rảnh liên quan thế nào?", "a": "社会文明程度越高，休闲时间就越多。", "avi": "Văn minh càng cao, thời gian rảnh càng nhiều.", "bad": ["社会越发达，人越没有时间休闲。", "两者没有关系。"], "p": 0}, {"q": "为什么说人太忙不好？", "qvi": "Vì sao nói quá bận là không tốt?", "a": "人一忙就容易乱，目光短浅。", "avi": "Hễ bận là dễ rối, tầm nhìn hạn hẹp.", "bad": ["人一忙就有更多休闲时间。", "人一忙就更有智慧。"], "p": 1}, {"q": "作者说的“玩”指的是什么？", "qvi": "“Chơi” mà tác giả nói là gì?", "a": "积极、健康、友好、多样性的游戏。", "avi": "Trò chơi tích cực, lành mạnh, thân thiện, đa dạng.", "bad": ["只是户外运动。", "打麻将赌博。"], "p": 2}, {"q": "有人玩物丧志，作者认为是谁的错？", "qvi": "Có người ham chơi mất ý chí, tác giả cho là lỗi của ai?", "a": "不是游戏的错，而是游戏者没掌握好“度”。", "avi": "Không phải lỗi trò chơi mà do người chơi không giữ chừng mực.", "bad": ["是游戏本身的错。", "是鲁迅的错。"], "p": 3}, {"q": "作者怎么看把赌博归罪于麻将？", "qvi": "Tác giả nghĩ gì về việc đổ tội cờ bạc cho mạt chược?", "a": "那是人在逃避责任。", "avi": "Đó là con người trốn tránh trách nhiệm.", "bad": ["麻将应该被禁止。", "麻将本来就是赌博工具。"], "p": 4}, {"q": "作者建议中国的大学应该怎么做？", "qvi": "Tác giả đề nghị đại học Trung Quốc nên làm gì?", "a": "开一门游戏理论课程。", "avi": "Mở một môn lý luận trò chơi.", "bad": ["取消学生的休闲时间。", "让学生多打麻将。"], "p": 5}]}}, {"id": "hk3-l3", "no": 3, "day": "HK3 · Bài 3", "time": "10:00", "scene": "office", "room": "office", "cast": ["manager", "zhangdong", "auntie", "lee"], "vi": "Cửa hàng xe: lời từ chối của Tôn Minh", "zh": "孙明的拒绝", "py": "Sūn Míng de jùjué", "vocab": [["车行", "chēháng", "cửa hàng bán xe", ""], ["销售", "xiāoshòu", "bán hàng, tiêu thụ", ""], ["业务", "yèwù", "công việc kinh doanh, nghiệp vụ", ""], ["接待", "jiēdài", "tiếp đón", ""], ["顾客", "gùkè", "khách hàng", ""], ["根据", "gēnjù", "căn cứ vào, theo", ""], ["经验", "jīngyàn", "kinh nghiệm", ""], ["推断", "tuīduàn", "suy đoán", ""], ["推销员", "tuīxiāoyuán", "nhân viên tiếp thị, chào hàng", ""], ["热心", "rèxīn", "nhiệt tình", ""], ["迎", "yíng", "đón, nghênh đón", ""], ["适合", "shìhé", "thích hợp", ""], ["解释", "jiěshì", "giải thích", ""], ["两厢车", "liǎngxiāng chē", "xe hai khoang (xe hatchback)", ""], ["操作", "cāozuò", "thao tác, vận hành", ""], ["省油", "shěngyóu", "tiết kiệm xăng", ""], ["经济实惠", "jīngjì shíhuì", "kinh tế, thiết thực (rẻ mà tốt)", ""], ["从事", "cóngshì", "theo đuổi, làm (công việc)", ""], ["商务", "shāngwù", "thương vụ, kinh doanh", ""], ["设计", "shèjì", "thiết kế", ""], ["平稳", "píngwěn", "ổn định, bằng phẳng", ""], ["宽敞", "kuānchang", "rộng rãi", ""], ["舒适", "shūfu", "thoải mái", ""], ["道谢", "dàoxiè", "cảm ơn", ""], ["不解", "bùjiě", "không hiểu, thắc mắc", ""], ["劝说", "quànshuō", "khuyên bảo, thuyết phục", ""], ["实诚", "shíchéng", "thật thà, thành thực", ""], ["创办", "chuàngbàn", "sáng lập, thành lập", ""], ["特地", "tèdì", "đặc biệt, cố ý", ""], ["犹豫", "yóuyù", "do dự, lưỡng lự", ""], ["合同", "hétóng", "hợp đồng", ""], ["恍然大悟", "huǎngrándàwù", "bỗng nhiên hiểu ra, đại ngộ", ""], ["虚伪", "xūwěi", "giả dối", ""], ["诚信", "chéngxìn", "thành tín, chữ tín", ""], ["信任", "xìnrèn", "tin tưởng", ""]], "story": [{"c": "panda", "vi": "HK3 · Cửa hàng xe: lời từ chối của Tôn Minh. Lớp học đại học: mọi người lần lượt đọc bài khóa gốc, giáo sư đặt câu hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "manager", "zh": "我在一家车行找到一份汽车销售的工作。但几天下来，还没卖出一部车，而那个小个子的孙明却做成了好几笔业务。我开始观察他，看他是怎样接待顾客的。", "py": "Wǒ zài yìjiā chēháng zhǎodào yífèn qìchē xiāoshòu de gōngzuò. Dàn jǐtiān xiàlái, hái méi màichū yíbù chē, ér nàge xiǎogezi de Sūn Míng què zuòchéng le hǎo jǐbǐ yèwù. Wǒ kāishǐ guānchá tā, kàn tā shì zěnyàng jiēdài gùkè de.", "vi": "Đoạn 1: Tôi tìm được công việc bán ô tô tại một cửa hàng xe. Mấy ngày trời trôi qua, vẫn chưa bán được chiếc nào, vậy mà anh Tôn Minh người nhỏ con lại làm được mấy vụ. Tôi bắt đầu quan sát anh ấy, xem anh ấy tiếp khách thế nào."}, {"c": "prof", "zh": "“我”为什么开始观察孙明？", "py": "“Wǒ” wèishénme kāishǐ guānchá Sūn Míng?", "vi": "Vì sao “tôi” bắt đầu quan sát Tôn Minh?"}, {"me": "Vì “tôi” chưa bán được xe nào mà Tôn Minh đã làm được mấy vụ.", "opts": [["因为“我”一部车也没卖出，孙明却做成了好几笔业务。", "Yīnwèi “Wǒ” yíbù chē yě méi màichū, Sūn Míng què zuòchéng le hǎo jǐbǐ yèwù.", "Vì “tôi” chưa bán được xe nào mà Tôn Minh đã làm được mấy vụ."], ["因为孙明是“我”的老板。", "Yīnwèi Sūn Míng shì “Wǒ” de lǎobǎn.", "(chưa đúng với nội dung đoạn văn)"], ["因为孙明想辞职。", "Yīnwèi Sūn Míng xiǎng cízhí.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "zhangdong", "zh": "一天，有两个顾客推门进来了。走在前面的是一个50来岁的妇女，后面跟着一个矮胖男人，应该是她的丈夫吧。根据经验推断，这两个人像是随便看看的，不像是来买车的，推销员们就显得不太热心。", "py": "Yìtiān, yǒu liǎngge gùkè tuī mén jìnlái le. Zǒu zài qiánmiàn de shì yíge50 lái suì de fùnǚ, hòumiàn gēnzhe yíge ǎipàng nánrén, yīnggāi shì tā de zhàngfu ba. Gēnjù jīngyàn tuīduàn, zhè liǎngge rén xiàngshì suíbiàn kànkan de, bú xiàngshì lái mǎichē de, tuīxiāoyuán men jiù xiǎnde bútài rèxīn.", "vi": "Đoạn 2: Một hôm, có hai khách hàng đẩy cửa bước vào. Người đi trước là một phụ nữ khoảng 50 tuổi, phía sau là một người đàn ông thấp béo, chắc là chồng bà. Theo kinh nghiệm suy đoán, hai người này có vẻ chỉ xem qua thôi, không có vẻ là mua xe, nên mấy nhân viên bán hàng tỏ ra không mấy nhiệt tình."}, {"c": "prof", "zh": "推销员们为什么不太热心？", "py": "Tuīxiāoyuán men wèishénme bútài rèxīn?", "vi": "Vì sao nhân viên bán hàng không nhiệt tình?"}, {"me": "Họ thấy hai người không giống đến mua xe.", "opts": [["他们觉得这两个人不像是来买车的。", "Tāmen juéde zhè liǎngge rén bú xiàngshì lái mǎichē de.", "Họ thấy hai người không giống đến mua xe."], ["他们太累了。", "Tāmen tàilèi le.", "(chưa đúng với nội dung đoạn văn)"], ["他们不认识这两个人。", "Tāmen bú rènshi zhè liǎngge rén.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "auntie", "zh": "这时，孙明迎了上去，热情地问：“看车呀？”女顾客点点头。孙明对她说：“这车不适合您。”女顾客没想到会听到这样的话，就问为什么。孙明带着他们一边往车前走，一边解释：“您要是开车呀，最好是选择两厢车，操作更容易些，也更省油，经济实惠。”而这种车是为从事商务的人士设计的，为了跑远路平稳，就稍微重一点儿，比开两厢车累，也更费油。我们旁边的车行里新来了一种两厢车，挺适合您的，您不妨去看看。”", "py": "Zhèshí, Sūn Míng yíng le shàngqù, rèqíng dìwèn: “Kànchē ya?” nǚ gùkè diǎndiǎntóu. Sūn Míng duì tā shuō: “Zhèchē bú shìhé nín.” nǚ gùkè méixiǎngdào huì tīngdào zhèyàngdehuà, jiù wèn wèishénme. Sūn Míng dài zhe tāmen yìbiān wǎngchē qián zǒu, yìbiān jiěshì: “Nín yàoshì kāichē ya, zuìhǎo shì xuǎnzé liǎngxiāngchē, cāozuò gèng róngyì xiē, yě gèng shěngyóu, jīngjì shíhuì.” ér zhèzhǒng chēshì wèi cóngshì shāngwù de rénshì shèjì de, wèile pǎo yuǎnlù píngwěn, jiù shāowēi zhòng yìdiǎnr, bǐkāi liǎngxiāngchē lèi, yě gèngfèiyóu. Wǒmen pángbiān de chēháng lǐ xīnlái le yìzhǒng liǎngxiāngchē, tǐng shìhé nín de, nín bùfáng qù kànkan.”", "vi": "Đoạn 3: Lúc đó, Tôn Minh đón lên, nhiệt tình hỏi: \"Xem xe ạ?\" Nữ khách gật đầu. Tôn Minh nói với bà: \"Xe này không hợp với bà đâu.\" Nữ khách không ngờ lại nghe câu nói như vậy, liền hỏi tại sao. Tôn Minh vừa dẫn họ đi về phía chiếc xe vừa giải thích: \"Bà lái xe thì tốt nhất nên chọn loại xe hai khoang, thao tác dễ hơn một chút, cũng đỡ tốn xăng hơn, kinh tế và thiết thực.\" Còn loại xe này được thiết kế cho người làm công việc thương vụ, để chạy đường dài cho vững nên hơi nặng hơn một chút, lái mệt hơn xe hai khoang và cũng tốn xăng hơn. Bên cạnh cửa hàng chúng tôi mới có loại xe hai khoang mới, rất hợp với bà, bà có thể sang xem thử.\""}, {"c": "prof", "zh": "孙明为什么说“这车不适合您”？", "py": "Sūn Míng wèishénme shuō “Zhèchē bú shìhé nín”?", "vi": "Vì sao Tôn Minh nói “xe này không hợp với bà”?"}, {"me": "Xe thiết kế cho doanh nhân, nặng và tốn xăng, không hợp với bà.", "opts": [["这车是为商务人士设计的，比较重、费油，不适合她开。", "Zhèchē shì wèi shāngwùrénshì shèjì de, bǐjiào zhòng, fèiyóu, bú shìhé tā kāi.", "Xe thiết kế cho doanh nhân, nặng và tốn xăng, không hợp với bà."], ["这车太便宜了。", "Zhèchē tài piányi le.", "(chưa đúng với nội dung đoạn văn)"], ["这车已经卖完了。", "Zhè chē yǐjīng màiwán le.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "lee", "zh": "那位女顾客却说：“我觉得这车挺好的。”孙明接着解释：“这车空间比较宽敞，比一般家用的车宽一点儿，长一点儿，您要是开吧，不一定会觉得舒服。”女顾客坐进去试了试，果然觉得操作起来不舒服。她点了点头，下了车，一边道谢，一边跟着她的丈夫走了。", "py": "Nàwèi nǚ gùkè quèshuō: “Wǒ juéde zhèchē tǐng hǎo de.” Sūn Míng jiēzhe jiěshì: “Zhè chē kōngjiān bǐjiào kuānchǎng, bǐ yìbān jiāyòng de chē kuān yìdiǎnr, zhǎng yìdiǎnr, nín yàoshì kāi ba, bù yídìng huì juéde shūfu.” nǚ gùkè zuò jìnqù shìleshì, guǒrán juéde cāozuò qǐlái bù shūfu. Tā diǎn le diǎntóu, xià le chē, yìbiān dàoxiè, yìbiān gēnzhe tā de zhàngfu zǒu le.", "vi": "Đoạn 4: Nhưng nữ khách lại nói: \"Tôi thấy xe này rất đẹp mà.\" Tôn Minh tiếp tục giải thích: \"Xe này không gian khá rộng rãi, rộng hơn xe gia đình thông thường một chút, dài hơn một chút, nếu bà lái thì chưa chắc đã thấy thoải mái.\" Nữ khách ngồi thử, quả nhiên thấy thao tác không thoải mái. Bà gật đầu, xuống xe, vừa cảm ơn vừa đi theo chồng ra về."}, {"c": "manager", "zh": "我不解地看着孙明。那位女顾客明明喜欢这辆车，只要再劝说一番，她就会掏钱买下来了，可这个孙明，却把到手的生意推出去了。", "py": "Wǒ bùjiě dì kànzhe Sūn Míng. Nàwèi nǚ gùkè míngmíng xǐhuan zhèliàng chē, zhǐyào zài quànshuō yìfān, tā jiù huì tāoqián mǎixiàlái le, kě zhège Sūn Míng, què bǎ dàoshǒu de shēngyi tuīchū qù le.", "vi": "Đoạn 5: Tôi nhìn Tôn Minh với vẻ khó hiểu. Nữ khách rõ ràng thích chiếc xe này, chỉ cần khuyên thêm một chút nữa là bà sẽ móc tiền mua ngay, vậy mà Tôn Minh lại đẩy mối làm ăn đã cầm chắc ra đi."}, {"c": "prof", "zh": "“我”为什么不理解孙明？", "py": "“Wǒ” wèishénme bù lǐjiě Sūn Míng?", "vi": "Vì sao “tôi” không hiểu Tôn Minh?"}, {"me": "Bà khách rõ ràng thích xe mà Tôn Minh lại đẩy mối làm ăn đi.", "opts": [["女顾客明明喜欢这辆车，孙明却把生意推出去了。", "Nǚ gùkè míngmíng xǐhuan zhèliàng chē, Sūn Míng què bǎ shēngyi tuīchū qù le.", "Bà khách rõ ràng thích xe mà Tôn Minh lại đẩy mối làm ăn đi."], ["孙明骂了顾客。", "Sūn Míng mà le gùkè.", "(chưa đúng với nội dung đoạn văn)"], ["孙明下班太早了。", "Sūn Míng xiàbān tàizǎo le.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "zhangdong", "zh": "快下班的时候，那位女顾客又进了车行。这次她的身后不仅跟着她的丈夫，还跟着一个高高大大的小伙子。女顾客一进车行就招呼孙明，并对一起来的小伙子说：“这个小孙可实诚了，从他手里买车，准没错。”她又对孙明说，她儿子刚刚创办了一家公司，需要买几部商用车，给公司用来跑业务。她这次是特地陪儿子来选车的。", "py": "Kuàixiàbān de shíhou, nàwèi nǚ gùkè yòu jìn le chēháng. Zhècì tā de shēnhòu bùjǐn gēnzhe tā de zhàngfu, háigēnzhe yíge gāogāodàdà de xiǎohuǒzi. Nǚ gùkè yíjìn chēháng jiù zhāohū Sūn Míng, bìng duì yì qǐlái de xiǎohuǒzi shuō: “Zhège xiǎosūn kě shíchéng le, cóng tā shǒulǐ mǎichē, zhǔn méicuò.” tā yòu duì Sūn Míng shuō, tā érzi gānggāng chuàngbàn le yìjiā gōngsī, xūyào mǎi jǐbù shāngyòngchē, gěi gōngsī yònglái pǎo yèwù. Tā zhècì shì tèdì péi érzi lái xuǎnchē de.", "vi": "Đoạn 6: Gần giờ tan ca, vị nữ khách lại bước vào cửa hàng. Lần này sau lưng bà không chỉ có chồng mà còn có một chàng trai cao lớn. Vừa vào cửa, bà đã gọi Tôn Minh và nói với chàng trai đi cùng: \"Anh Tôn này thật thà lắm, mua xe từ tay anh ấy thì chắc chắn không sai.\" Bà lại nói với Tôn Minh rằng con trai bà vừa thành lập một công ty, cần mua vài chiếc xe thương mại để công ty chạy việc. Lần này bà đặc biệt đi cùng con trai để chọn xe."}, {"c": "auntie", "zh": "那个小伙子也对孙明说，他本来已经看好了其他车行的几种车，但听母亲讲了在这里的经历后，他也想请孙明给他推荐车。孙明给他介绍了几种车，小伙子毫不犹豫地跟孙明签了合同，一下子就订了五部车。", "py": "Nàge xiǎohuǒzi yě duì Sūn Míng shuō, tā běnlái yǐjīng kànhǎo le qítā chēháng de jǐzhǒng chē, dàn tīng mǔqīn jiǎng le zài zhèlǐ de jīnglì hòu, tā yě xiǎng qǐng Sūn Míng gěi tā tuījiàn chē. Sūn Míng gěi tā jièshào le jǐzhǒng chē, xiǎohuǒzi háobùyóuyù dì gēn Sūn Míng qiānle hétóng, yíxiàzi jiùdìng le wǔbù chē.", "vi": "Đoạn 7: Anh chàng đó cũng nói với Tôn Minh rằng vốn anh đã xem mấy loại xe ở các cửa hàng khác, nhưng nghe mẹ kể trải nghiệm ở đây thì cũng muốn nhờ Tôn Minh tư vấn. Tôn Minh giới thiệu cho anh vài loại xe, anh chàng không do dự ký hợp đồng với Tôn Minh, đặt mua năm chiếc một lúc."}, {"c": "prof", "zh": "后来那个小伙子一次订了几辆车？", "py": "Hòulái nàge xiǎohuǒzi yícì dìng le jǐliàngchē?", "vi": "Sau đó chàng trai đặt mua mấy chiếc?"}, {"me": "Năm chiếc.", "opts": [["五辆。", "Wǔliàng.", "Năm chiếc."], ["一辆。", "Yíliàng.", "(chưa đúng với nội dung đoạn văn)"], ["两辆。", "Liǎngliàng.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "lee", "zh": "我这时才恍然大悟，明白了销售人员都应该懂得的道理：孙明的拒绝，其实是拒绝虚伪。做生意就是要讲诚信，真正为客户着想，才能赢得客户的信任。", "py": "Wǒ zhèshí cái huǎngrándàwù, míngbái le xiāoshòu rényuán dōu yīnggāi dǒngde de dàolǐ: Sūn Míng de jùjué, qíshí shì jùjué xūwěi. Zuòshēngyì jiùshì yào jiǎng chéngxìn, zhēnzhèng wèi kèhù zhuóxiǎng, cáinéng yíngdé kèhù de xìnrèn.", "vi": "Đoạn 8: Lúc ấy tôi mới bỗng nhiên hiểu ra và thấu rõ cái đạo lý mà nhân viên bán hàng nào cũng nên hiểu: Sự từ chối của Tôn Minh kỳ thực là từ chối sự giả dối. Làm ăn là phải giữ chữ tín, thực sự nghĩ cho khách hàng thì mới giành được lòng tin của họ."}, {"c": "prof", "zh": "孙明的拒绝，其实是拒绝什么？", "py": "Sūn Míng de jùjué, qíshí shì jùjué shénme?", "vi": "Sự từ chối của Tôn Minh thực ra là từ chối điều gì?"}, {"me": "Từ chối sự giả dối.", "opts": [["拒绝虚伪。", "Jùjué xūwěi.", "Từ chối sự giả dối."], ["拒绝顾客。", "Jùjué gùkè.", "(chưa đúng với nội dung đoạn văn)"], ["拒绝工作。", "Jùjué gōngzuò.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "却", "d": "Nhưng, lại (trái với mong đợi). Phó từ đứng sau chủ ngữ, trước động từ.", "ex": [["大家都没卖出车，孙明却做成了好几笔业务。", "Dàjiā dōu méi màichū chē, Sūn Míng què zuòchéng le hǎo jǐbǐ yèwù.", "Mọi người chưa bán được xe, Tôn Minh lại làm được mấy vụ."]]}, {"t": "只要……就……", "d": "Chỉ cần… là…. Không trộn với 只有……才…….", "ex": [["只要再劝说一番，她就会掏钱买下来。", "Zhǐyào zài quànshuō yìfān, tā jiù huì tāoqián mǎixiàlái.", "Chỉ cần khuyên thêm chút nữa là bà sẽ móc tiền mua."]]}, {"t": "不仅……还……", "d": "Không những… mà còn….", "ex": [["她的身后不仅跟着她的丈夫，还跟着一个小伙子。", "Tā de shēnhòu bùjǐn gēnzhe tā de zhàngfu, háigēnzhe yíge xiǎohuǒzi.", "Sau lưng bà không chỉ có chồng mà còn có một chàng trai."]]}, {"t": "本来……但……", "d": "Vốn dĩ… nhưng… (dự định ban đầu thay đổi).", "ex": [["他本来已经看好了其他车行的车，但听了母亲的话，也想请孙明推荐。", "Tā běnlái yǐjīng kànhǎo le qítā chēháng de chē, dàn tīng le mǔqīn dehuà, yě xiǎng qǐng Sūn Míng tuījiàn.", "Anh vốn đã chọn xe ở hãng khác, nhưng nghe mẹ kể thì cũng muốn nhờ Tôn Minh."]]}, {"t": "一边……一边……", "d": "Vừa… vừa… (hai hành động cùng lúc).", "ex": [["孙明一边带他们往车前走，一边解释。", "Sūn Míng yìbiān dài tāmen wǎngchē qián zǒu, yìbiān jiěshì.", "Tôn Minh vừa dẫn họ ra xe vừa giải thích."]]}], "order": [], "u": {"gq": [{"s": "却", "d": "Nhưng, lại (trái với mong đợi). Phó từ đứng sau chủ ngữ, trước động từ.", "ok": "大家都没卖出车，孙明却做成了好几笔业务。", "vi": "Mọi người chưa bán được xe, Tôn Minh lại làm được mấy vụ.", "bad": ["大家都没卖出车，却孙明做成了好几笔业务。", "大家都没卖出车，孙明做成却了好几笔业务。"]}, {"s": "只要……就……", "d": "Chỉ cần… là…. Không trộn với 只有……才…….", "ok": "只要再劝说一番，她就会掏钱买下来。", "vi": "Chỉ cần khuyên thêm chút nữa là bà sẽ móc tiền mua.", "bad": ["只要再劝说一番，她才会掏钱买下来。", "只有再劝说一番，她就会掏钱买下来。"]}, {"s": "不仅……还……", "d": "Không những… mà còn….", "ok": "她的身后不仅跟着她的丈夫，还跟着一个小伙子。", "vi": "Sau lưng bà không chỉ có chồng mà còn có một chàng trai.", "bad": ["她的身后不仅跟着她的丈夫，但是跟着一个小伙子。", "她的身后跟着不仅她的丈夫，还一个小伙子。"]}, {"s": "本来……但……", "d": "Vốn dĩ… nhưng… (dự định ban đầu thay đổi).", "ok": "他本来已经看好了其他车行的车，但听了母亲的话，也想请孙明推荐。", "vi": "Anh vốn đã chọn xe ở hãng khác, nhưng nghe mẹ kể thì cũng muốn nhờ Tôn Minh.", "bad": ["他已经本来看好了其他车行的车，但听了母亲的话，也想请孙明推荐。", "他本来已经看好了其他车行的车，所以听了母亲的话，也想请孙明推荐。"]}, {"s": "一边……一边……", "d": "Vừa… vừa… (hai hành động cùng lúc).", "ok": "孙明一边带他们往车前走，一边解释。", "vi": "Tôn Minh vừa dẫn họ ra xe vừa giải thích.", "bad": ["孙明一边带他们往车前走，还一边解释了吗。", "一边孙明带他们往车前走，解释一边。"]}], "disc": [{"q": "如果你是孙明，你会怎么做？为什么？", "py": "Rúguǒ nǐ shì Sūn Míng, nǐ huì zěnme zuò? Wèishénme?", "vi": "Nếu bạn là Tôn Minh, bạn sẽ làm gì? Vì sao?", "keys": ["如果", "虽然……但是|虽然……但", "诚信|着想"], "sample": "如果我是孙明，我也会说实话。虽然可能少卖一辆车，但是做生意要讲诚信，真正为顾客着想才能赢得信任。", "spy": "Rúguǒ wǒ shì Sūn Míng, wǒ yě huì shuōshíhuà. Suīrán kěnéng shǎomài yíliàngchē, dànshì zuòshēngyì yào jiǎng chéngxìn, zhēnzhèng wèi gùkè zhuóxiǎng cáinéng yíngdé xìnrèn."}, {"q": "你觉得“拒绝”有魅力吗？在生活中你拒绝过别人吗？", "py": "Nǐ juéde “Jùjué” yǒu mèilì ma? Zàishēnghuózhōng nǐ jùjué guò biérén ma?", "vi": "Bạn thấy “từ chối” có sức hút không? Bạn từng từ chối ai chưa?", "keys": ["其实", "拒绝", "不仅……还|不仅……而且"], "sample": "我觉得拒绝其实也是一种诚实。我拒绝过朋友的要求，这样不仅对自己好，还对朋友好。", "spy": "Wǒ juéde jùjué qíshí yě shì yìzhǒng chéngshí. Wǒ jùjué guò péngyou de yāoqiú, zhèyàng bùjǐn duì zìjǐ hǎo, hái duì péngyou hǎo."}], "comp": [{"vi": "Chỉ cần bạn thật lòng nghĩ cho khách, khách sẽ tin bạn. (只要……就……)", "keys": ["只要", "就"], "model": "只要你真心为顾客着想，顾客就会信任你。", "mpy": "Zhǐyào nǐ zhēnxīn wèi gùkè zhuóxiǎng, gùkè jiù huì xìnrèn nǐ."}, {"vi": "Anh ấy không chỉ bán xe mà còn giúp khách chọn xe phù hợp. (不仅……还……)", "keys": ["不仅", "还|而且"], "model": "他不仅卖车，还帮顾客选合适的车。", "mpy": "Tā bùjǐn màichē, hái bāng gùkè xuǎn héshì de chē."}, {"vi": "Tôi vốn định đi du lịch, nhưng trời mưa nên ở nhà. (本来……但……)", "keys": ["本来", "但|可是"], "model": "我本来想去旅行，但是下雨了，只好在家。", "mpy": "Wǒ běnlái xiǎng qù lǚxíng, dànshì xiàyǔ le, zhǐhǎo zàijiā."}], "ex": [{"q": "“我”为什么开始观察孙明？", "qvi": "Vì sao “tôi” bắt đầu quan sát Tôn Minh?", "a": "因为“我”一部车也没卖出，孙明却做成了好几笔业务。", "avi": "Vì “tôi” chưa bán được xe nào mà Tôn Minh đã làm được mấy vụ.", "bad": ["因为孙明是“我”的老板。", "因为孙明想辞职。"], "p": 0}, {"q": "推销员们为什么不太热心？", "qvi": "Vì sao nhân viên bán hàng không nhiệt tình?", "a": "他们觉得这两个人不像是来买车的。", "avi": "Họ thấy hai người không giống đến mua xe.", "bad": ["他们太累了。", "他们不认识这两个人。"], "p": 1}, {"q": "孙明为什么说“这车不适合您”？", "qvi": "Vì sao Tôn Minh nói “xe này không hợp với bà”?", "a": "这车是为商务人士设计的，比较重、费油，不适合她开。", "avi": "Xe thiết kế cho doanh nhân, nặng và tốn xăng, không hợp với bà.", "bad": ["这车太便宜了。", "这车已经卖完了。"], "p": 2}, {"q": "“我”为什么不理解孙明？", "qvi": "Vì sao “tôi” không hiểu Tôn Minh?", "a": "女顾客明明喜欢这辆车，孙明却把生意推出去了。", "avi": "Bà khách rõ ràng thích xe mà Tôn Minh lại đẩy mối làm ăn đi.", "bad": ["孙明骂了顾客。", "孙明下班太早了。"], "p": 4}, {"q": "后来那个小伙子一次订了几辆车？", "qvi": "Sau đó chàng trai đặt mua mấy chiếc?", "a": "五辆。", "avi": "Năm chiếc.", "bad": ["一辆。", "两辆。"], "p": 6}, {"q": "孙明的拒绝，其实是拒绝什么？", "qvi": "Sự từ chối của Tôn Minh thực ra là từ chối điều gì?", "a": "拒绝虚伪。", "avi": "Từ chối sự giả dối.", "bad": ["拒绝顾客。", "拒绝工作。"], "p": 7}]}}, {"id": "hk3-l4", "no": 4, "day": "HK3 · Bài 4", "time": "19:30", "scene": "living", "room": "living", "cast": ["prof", "mom", "dad", "tianfang"], "vi": "Phòng khách: vợ nên gọi chồng thế nào?", "zh": "妻子怎么叫丈夫呢", "py": "Qīzǐ zěnme jiào zhàngfu ne", "vocab": [["新婚", "xīn hūn", "mới cưới", ""], ["夫妻", "fū qī", "vợ chồng", ""], ["确立", "què lì", "xác lập, thiết lập", ""], ["陷入", "xiàn rù", "rơi vào (trạng thái)", ""], ["称呼", "chēng hu", "xưng hô, cách gọi", ""], ["烦恼", "fán nǎo", "phiền não, lo lắng", ""], ["别扭", "biè niu", "gượng gạo, không tự nhiên", ""], ["家里的", "jiā lǐ de", "“người trong nhà” (chỉ vợ)", ""], ["老婆", "lǎo po", "vợ (thân mật)", ""], ["庄重", "zhuāng zhòng", "trang trọng", ""], ["太太", "tài tai", "bà, phu nhân", ""], ["媳妇儿", "xí fùr", "vợ (phương ngữ, thân mật)", ""], ["文气", "wén qì", "có vẻ văn hóa, trang trọng (hơi sách vở)", ""], ["当面", "dāng miàn", "trực diện, đối mặt", ""], ["爱人", "ài ren", "người yêu, vợ/chồng (cũ)", ""], ["通行", "tōng xíng", "thông dụng, phổ biến", ""], ["浪漫", "làng màn", "lãng mạn", ""], ["磨损", "mósǔn", "mài mòn, hao mòn", ""], ["过时", "guò shí", "lỗi thời", ""], ["先生", "xiān sheng", "tiên sinh, ông (kính ngữ)", ""], ["尊称", "zūn chēng", "danh xưng kính trọng", ""], ["严肃", "yán sù", "nghiêm túc", ""], ["有余", "yǒu yú", "thừa, dư thừa", ""], ["不足", "bù zú", "không đủ, thiếu", ""], ["宴会厅", "yàn huì tīng", "sảnh tiệc", ""], ["会议室", "huì yì shì", "phòng họp", ""], ["高雅", "gāo yǎ", "cao nhã, thanh lịch", ""], ["具备", "jù bèi", "có đủ, trang bị", ""], ["西服革履", "xī fú gé lǚ", "âu phục giày da (trang phục chỉnh tề)", ""], ["背心", "bèi xīn", "áo ba lỗ, áo lót", ""], ["短裤", "duǎn kù", "quần đùi", ""], ["唤", "huàn", "gọi, xưng hô", ""], ["男人", "nán rén", "đàn ông (trong văn cảnh = chồng)", ""], ["极端", "jí duān", "cực đoan, hai thái cực", ""], ["随便", "suí biàn", "tùy tiện, thoải mái", ""], ["俗气", "sú qì", "tục tĩu, kém sang", ""], ["文化人", "wén huà rén", "người có văn hóa, trí thức", ""], ["他称", "tā chēng", "cách gọi ngôi thứ ba", ""], ["亲热感", "qīn rè gǎn", "cảm giác thân mật, ấm áp", ""], ["时代感", "shí dài gǎn", "cảm giác hiện đại, thời đại", ""]], "story": [{"c": "panda", "vi": "HK3 · Phòng khách: vợ nên gọi chồng thế nào?. Lớp học đại học: mọi người lần lượt đọc bài khóa gốc, giáo sư đặt câu hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "mom", "zh": "新婚后，夫妻关系确立了，妻子常常会陷入如何称呼丈夫的烦恼中，好像什么都别扭。丈夫称呼妻子似乎没问题，轻松一点儿的叫“家里的”，随便一点儿的叫“老婆”，庄重一点儿的叫“太太”，老家来了客人叫“媳妇儿”……可以选用的真不少，所以丈夫从不为称呼的事烦恼。", "py": "Xīnhūn hòu, fūqīguānxì quèlì le, qīzǐ chángcháng huì xiànrù rúhé chēnghū zhàngfu de fánnǎo zhōng, hǎoxiàng shénme dōu bièniu. Zhàngfu chēnghū qīzǐ sìhū méi wèntí, qīngsōng yìdiǎnr de jiào “Jiālǐ de”, suíbiàn yìdiǎnr de jiào “Lǎopo”, zhuāngzhòng yìdiǎnr de jiào “Tàitài”, lǎojiā lái le kèren jiào “Xífur” …… kěyǐ xuǎnyòng de zhēnbùshǎo, suǒyǐ zhàngfu cóngbú wèi chēnghū de shì fánnǎo.", "vi": "Sau khi cưới, quan hệ vợ chồng đã xác lập, người vợ thường rơi vào nỗi phiền não không biết gọi chồng thế nào, dường như gọi gì cũng ngượng. Chồng gọi vợ thì có vẻ không vấn đề gì: thoải mái thì gọi \"家里的\", tùy tiện thì gọi \"老婆\", trang trọng thì gọi \"太太\", quê có khách lên thì gọi \"媳妇儿\"… có thể chọn dùng thật không ít, nên chồng chưa bao giờ phiền não chuyện xưng hô."}, {"c": "prof", "zh": "为什么丈夫从不为称呼的事烦恼？", "py": "Wèishénme zhàngfu cóngbú wèi chēnghū de shì fánnǎo?", "vi": "Vì sao chồng chưa bao giờ phiền não chuyện xưng hô?"}, {"me": "Vì có rất nhiều từ để gọi vợ.", "opts": [["因为称呼妻子可以选用的词很多。", "Yīnwèi chēnghū qīzǐ kěyǐ xuǎnyòng de cí hěnduō.", "Vì có rất nhiều từ để gọi vợ."], ["因为丈夫不需要称呼妻子。", "Yīnwèi zhàngfu bù xūyào chēnghū qīzǐ.", "(chưa đúng với nội dung đoạn văn)"], ["因为丈夫只叫妻子“太太”。", "Yīnwèi zhàngfu zhǐ jiào qīzǐ “Tàitài”.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "dad", "zh": "可妻子怎么叫丈夫呢？“丈夫”是最普通的。可是显得太文气了点儿，再说，它只能在向人介绍时使用，不能当面称呼。", "py": "Kě qīzǐ zěnme jiào zhàngfu ne? “Zhàngfu” shì zuì pǔtōng de. Kěshì xiǎnde tài wénqì le diǎnr, zàishuō, tā zhǐnéng zài xiàng rén jièshào shí shǐyòng, bùnéng dāngmiàn chēnghū.", "vi": "Nhưng vợ gọi chồng thế nào đây? \"丈夫\" là phổ thông nhất, nhưng có vẻ hơi sách vở; hơn nữa nó chỉ dùng khi giới thiệu với người khác, không gọi trực tiếp được."}, {"c": "prof", "zh": "“丈夫”这个称呼有什么问题？", "py": "“Zhàngfu” zhège chēnghū yǒu shénme wèntí?", "vi": "Cách gọi “丈夫” có vấn đề gì?"}, {"me": "Quá sách vở, chỉ dùng khi giới thiệu, không gọi trực tiếp.", "opts": [["太文气，只能在介绍时用，不能当面称呼。", "Tài wénqì, zhǐnéng zài jièshào shíyòng, bùnéng dāngmiàn chēnghū.", "Quá sách vở, chỉ dùng khi giới thiệu, không gọi trực tiếp."], ["太俗气了。", "Tài súqì le.", "(chưa đúng với nội dung đoạn văn)"], ["只能当面称呼。", "Zhǐnéng dāngmiàn chēnghū.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "tianfang", "zh": "“爱人”曾经是通行的说法，字面的意思是“我所爱的人”，不管男女都可以用，本来挺有浪漫色彩的，可是在过去的年代使用久了，这层浪漫色彩早已磨损，变成了一种过时的称呼。跟丈夫一样，“爱人”也不适合当面称呼。", "py": "“Àiren” céngjīng shì tōngxíng de shuōfǎ, zìmiàn de yìsi shì “Wǒ suǒ ài de rén”, bùguǎn nánnǚ dōu kěyǐ yòng, běnlái tǐng yǒu làngmàn sècǎi de, kěshì zài guòqù de niándài shǐyòng jiǔ le, zhècéng làngmàn sècǎi zǎoyǐ mósǔn, biànchéng le yìzhǒng guòshí de chēnghū. Gēn zhàngfu yíyàng, “Àiren” yě bú shìhé dāngmiàn chēnghū.", "vi": "\"爱人\" từng là cách nói thông dụng, nghĩa đen là \"người tôi yêu\", nam nữ đều dùng được, vốn rất lãng mạn, nhưng dùng lâu trong những năm tháng trước, lớp màu lãng mạn ấy đã mòn đi, thành cách gọi lỗi thời. Giống \"丈夫\", \"爱人\" cũng không hợp để gọi trực tiếp."}, {"c": "mom", "zh": "“先生”是从对成年男性的尊称发展来的，严肃有余，亲热不足。这个称呼在宴会厅、会议室等比较高雅的场所用才合适，而这位“先生”应具备一定的条件：西服革履，最好是一个文化人。我们很难想象，把穿着背心短裤的丈夫唤做“先生”。另外，“先生”也不适合用来当面称呼丈夫。", "py": "“Xiānsheng” shìcóng duì chéngnián nánxìng de zūnchēng fāzhǎn lái de, yánsù yǒuyú, qīnrè bùzú. Zhège chēnghū zài yànhuìtīng, huìyìshì děng bǐjiào gāoyǎ de chǎngsuǒ yòng cái héshì, ér zhèwèi “Xiānsheng” yīng jùbèi yídìng de tiáojiàn: Xīfúgélǚ, zuìhǎo shì yíge wénhuà rén. Wǒmen hěnnán xiǎngxiàng, bǎ chuānzhe bèixīn duǎnkù de zhàngfu huàn zuò “Xiānsheng”. Lìngwài, “Xiānsheng” yě bú shìhé yònglái dāngmiàn chēnghū zhàngfu.", "vi": "\"先生\" phát triển từ cách gọi tôn kính nam giới trưởng thành, nghiêm túc thì thừa, thân mật thì thiếu. Nó chỉ hợp ở nơi trang nhã như phòng tiệc, phòng họp, và vị \"先生\" ấy phải có điều kiện: com-lê giày da, tốt nhất là người có học. Khó mà tưởng tượng gọi ông chồng mặc áo ba lỗ quần đùi là \"先生\". Ngoài ra, \"先生\" cũng không hợp để gọi chồng trực tiếp."}, {"c": "prof", "zh": "“先生”适合在什么场合用？", "py": "“Xiānsheng” shìhé zài shénme chǎnghé yòng?", "vi": "“先生” hợp dùng ở đâu?"}, {"me": "Phòng tiệc, phòng họp – nơi trang nhã.", "opts": [["宴会厅、会议室等比较高雅的场所。", "Yànhuìtīng, huìyìshì děng bǐjiào gāoyǎ de chǎngsuǒ.", "Phòng tiệc, phòng họp – nơi trang nhã."], ["在家里穿背心短裤的时候。", "Zài jiālǐ chuān bèixīn duǎnkù de shíhou.", "(chưa đúng với nội dung đoạn văn)"], ["在菜市场买菜的时候。", "Zài càishìchǎng mǎicài de shíhou.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "dad", "zh": "“男人”本来可以用来指所有的男性，不知怎么被用来专门称自己丈夫。它和“先生”正好处于两个极端，显得随便，甚至有些俗气。这个称呼不被文化人接受。还有一点，“男人”也和“丈夫”、“爱人”一样，不适合作为称呼。", "py": "“Nánrén” běnlái kěyǐ yònglái zhǐ suǒyǒu de nánxìng, bùzhī zěnme bèi yònglái zhuānmén chēng zìjǐ zhàngfu. Tā hé “Xiānsheng” zhènghǎo chǔyú liǎngge jíduān, xiǎnde suíbiàn, shènzhì yǒuxiē súqì. Zhège chēnghū bú bèi wénhuà rén jiēshòu. Háiyǒu yìdiǎn, “Nánrén” yě hé “Zhàngfu”, “Àiren” yíyàng, bú shìhé zuòwéi chēnghū.", "vi": "\"男人\" vốn chỉ mọi nam giới, chẳng hiểu sao lại dùng riêng để gọi chồng mình. Nó và \"先生\" ở hai thái cực: có vẻ tùy tiện, thậm chí hơi thô tục, không được người có học chấp nhận. Thêm nữa, \"男人\" cũng như \"丈夫\", \"爱人\", không hợp làm lời gọi."}, {"c": "prof", "zh": "为什么文化人不接受“男人”这个称呼？", "py": "Wèishénme wénhuà rén bù jiēshòu “Nánrén” zhège chēnghū?", "vi": "Vì sao người có học không nhận cách gọi “男人”?"}, {"me": "Nó có vẻ tùy tiện, thậm chí hơi thô tục.", "opts": [["它显得随便，甚至有些俗气。", "Tā xiǎnde suíbiàn, shènzhì yǒuxiē súqì.", "Nó có vẻ tùy tiện, thậm chí hơi thô tục."], ["它太严肃了。", "Tā tài yánsù le.", "(chưa đúng với nội dung đoạn văn)"], ["它太浪漫了。", "Tā tài làngmàn le.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "tianfang", "zh": "看来，要给丈夫找一个适合于各种场合，可以作为他称，又可以当面称呼，既有亲热感，又有时代感的称呼还真不容易。于是，“老公”这个词就开始兴起来了。", "py": "Kànlái, yào gěi zhàngfu zhǎo yíge shìhé yú gèzhǒng chǎnghé, kěyǐ zuòwéi tāchēng, yòu kěyǐ dāngmiàn chēnghū, jìyǒu qīnrè gǎn, yòu yǒu shídàigǎn de chēnghū hái zhēnbùróngyì. Yúshì, “Lǎogōng” zhège cí jiù kāishǐ xīngqǐ lái le.", "vi": "Xem ra, muốn tìm cho chồng một cách gọi hợp mọi hoàn cảnh, vừa dùng để nhắc đến, vừa gọi trực tiếp được, vừa thân mật vừa hợp thời thì thật không dễ. Thế là từ \"老公\" bắt đầu thịnh hành."}, {"c": "mom", "zh": "“老公”本来是一个方言词。随着大量的港台电视剧的播放，这个称呼也逐渐流行起来了。“老公”这一词的结构应是和“老婆”相对的，应该也是口语化的称呼；但是港台电视剧的流行，消除了这个词语的俗气。在电视剧中，年轻小姐叫丈夫为“老公”，中老年女士也叫丈夫为“老公”；不管有没有文化的女性，都可以称丈夫为“老公”，“老公”逐渐成了一个家喻户晓、人人皆用的称呼。", "py": "“Lǎogōng” běnlái shì yíge fāngyáncí. Suízhe dàliàng de gǎngtái diànshìjù de bōfàng, zhège chēnghū yě zhújiàn liúxíngqǐlái le. “Lǎogōng” zhèyìcí de jiégòu yīngshì hé “Lǎopo” xiāngduì de, yīnggāi yě shì kǒuyǔhuà de chēnghū; dànshì gǎngtái diànshìjù de liúxíng, xiāochú le zhège cíyǔ de súqì. Zài diànshìjù zhōng, niánqīng xiǎojiě jiào zhàngfu wèi “Lǎogōng”, zhōnglǎonián nǚshì yě jiào zhàngfu wèi “Lǎogōng” ; bùguǎn yǒuméiyǒu wénhuà de nǚxìng, dōu kěyǐ chēng zhàngfu wèi “Lǎogōng”, “Lǎogōng” zhújiàn chéng le yíge jiāyùhùxiǎo, rénrén jiē yòng de chēnghū.", "vi": "\"老公\" vốn là từ phương ngữ. Theo đà phát sóng nhiều phim Hồng Kông, Đài Loan, cách gọi này dần phổ biến. Về cấu trúc nó đối ứng với \"老婆\", lẽ ra cũng là cách gọi khẩu ngữ; nhưng phim Hồng Kông, Đài Loan đã xóa đi vẻ thô tục của nó. Trong phim, cô gái trẻ hay phụ nữ trung niên đều gọi chồng là \"老公\"; dù có học hay không, phụ nữ đều có thể gọi như vậy, \"老公\" dần thành cách gọi nhà nhà đều biết."}, {"c": "prof", "zh": "“老公”是怎么流行起来的？", "py": "“Lǎogōng” shì zěnme liúxíngqǐlái de?", "vi": "“老公” đã phổ biến như thế nào?"}, {"me": "Dần phổ biến theo phim Hồng Kông, Đài Loan.", "opts": [["随着港台电视剧的播放逐渐流行起来。", "Suízhe gǎngtái diànshìjù de bōfàng zhújiàn liúxíngqǐlái.", "Dần phổ biến theo phim Hồng Kông, Đài Loan."], ["是政府规定的。", "Shì zhèngfǔ guīdìng de.", "(chưa đúng với nội dung đoạn văn)"], ["是从京味普通话来的。", "Shìcóng jīngwèi pǔtōnghuà lái de.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "dad", "zh": "不过，还是有些人对“老公”这个称呼不以为然，原因之一是觉得“老公”来自南方，使人想起港台腔的普通话，不如京味普通话那么正宗。另一个原因，“老公”总是出现在港台电视剧中，使人想到某些表演做作的感情戏。看来，“老公”也不是一个人人满意的称呼。", "py": "Búguò, háishì yǒuxiē rén duì “Lǎogōng” zhège chēnghū bùyǐwéirán, yuányīn zhīyí shì juéde “Lǎogōng” láizì nánfāng, shǐrén xiǎngqǐ gǎngtáiqiāng de pǔtōnghuà, bùrú jīngwèi pǔtōnghuà nàme zhèngzōng. Lìng yíge yuányīn, “Lǎogōng” zǒngshì chūxiàn zài gǎngtái diànshìjù zhōng, shǐrén xiǎngdào mǒuxiē biǎoyǎn zuòzuò de gǎnqíng xì. Kànlái, “Lǎogōng” yě búshì yíge rénrén mǎnyì de chēnghū.", "vi": "Tuy vậy, vẫn có người không đồng tình với \"老公\". Một lý do là họ thấy nó đến từ phương Nam, gợi nhớ tiếng phổ thông giọng Hồng Kông – Đài Loan, không chính gốc bằng giọng Bắc Kinh. Lý do khác là \"老公\" luôn xuất hiện trong phim Hồng Kông, Đài Loan, khiến người ta nghĩ tới những màn tình cảm diễn giả tạo. Xem ra, \"老公\" cũng không làm ai cũng hài lòng."}, {"c": "tianfang", "zh": "其实对此有不同的观点很自然。语言的魅力本来就在于它千变万化，重要的是，使用称呼和运用语言一样，要根据场合，根据不同的对象进行选择。", "py": "Qíshí duìcǐ yǒu bùtóng de guāndiǎn hěn zìrán. Yǔyán de mèilì běnlái jiù zàiyú tā qiānbiànwànhuà, zhòngyào de shì, shǐyòng chēnghū hé yùnyòng yǔyán yíyàng, yào gēnjù chǎnghé, gēnjù bùtóng de duìxiàng jìnxíng xuǎnzé.", "vi": "Thật ra có quan điểm khác nhau về chuyện này là rất tự nhiên. Sức hấp dẫn của ngôn ngữ vốn nằm ở sự biến hóa khôn lường; điều quan trọng là dùng xưng hô cũng như dùng ngôn ngữ, phải lựa chọn theo hoàn cảnh và theo từng đối tượng."}, {"c": "prof", "zh": "作者认为使用称呼最重要的是什么？", "py": "Zuòzhě rènwéi shǐyòng chēnghū zuì zhòngyào de shì shénme?", "vi": "Tác giả cho rằng điều quan trọng nhất khi xưng hô là gì?"}, {"me": "Chọn theo hoàn cảnh và từng đối tượng.", "opts": [["要根据场合和不同的对象进行选择。", "Yào gēnjù chǎnghé hé bùtóng de duìxiàng jìnxíng xuǎnzé.", "Chọn theo hoàn cảnh và từng đối tượng."], ["一定要用“老公”。", "Yídìng yào yòng “Lǎogōng”.", "(chưa đúng với nội dung đoạn văn)"], ["只能用“丈夫”。", "Zhǐnéng yòng “Zhàngfu”.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "既……又……", "d": "Vừa… vừa… (hai tính chất cùng có).", "ex": [["这个称呼既有亲热感，又有时代感。", "Zhège chēnghū jìyǒu qīnrè gǎn, yòu yǒu shídàigǎn.", "Cách gọi này vừa thân mật vừa hợp thời."]]}, {"t": "随着……", "d": "Cùng với sự…, theo đà… (không dùng 所以 ở vế sau).", "ex": [["随着港台电视剧的播放，这个称呼逐渐流行起来了。", "Suízhe gǎngtái diànshìjù de bōfàng, zhège chēnghū zhújiàn liúxíngqǐlái le.", "Theo đà phát sóng phim Hồng Kông, Đài Loan, cách gọi này dần phổ biến."]]}, {"t": "不管……都……", "d": "Bất kể… đều….", "ex": [["不管有没有文化的女性，都可以称丈夫为“老公”。", "Bùguǎn yǒuméiyǒu wénhuà de nǚxìng, dōu kěyǐ chēng zhàngfu wèi “Lǎogōng”.", "Phụ nữ dù có học hay không đều có thể gọi chồng là “老公”."]]}, {"t": "对……不以为然", "d": "Không đồng tình với….", "ex": [["有些人对“老公”这个称呼不以为然。", "Yǒuxiē rén duì “Lǎogōng” zhège chēnghū bùyǐwéirán.", "Có người không đồng tình với cách gọi “老公”."]]}, {"t": "……在于……", "d": "… nằm ở…, cốt ở….", "ex": [["语言的魅力本来就在于它千变万化。", "Yǔyán de mèilì běnlái jiù zàiyú tā qiānbiànwànhuà.", "Sức hút của ngôn ngữ vốn nằm ở sự biến hóa khôn lường."]]}], "order": [], "u": {"gq": [{"s": "既……又……", "d": "Vừa… vừa… (hai tính chất cùng có).", "ok": "这个称呼既有亲热感，又有时代感。", "vi": "Cách gọi này vừa thân mật vừa hợp thời.", "bad": ["这个称呼既有亲热感，也又有时代感。", "这个称呼又有亲热感，既有时代感。"]}, {"s": "随着……", "d": "Cùng với sự…, theo đà… (không dùng 所以 ở vế sau).", "ok": "随着港台电视剧的播放，这个称呼逐渐流行起来了。", "vi": "Theo đà phát sóng phim Hồng Kông, Đài Loan, cách gọi này dần phổ biến.", "bad": ["随着港台电视剧播放，所以这个称呼流行起来了。", "这个称呼随着逐渐流行起来了港台电视剧的播放。"]}, {"s": "不管……都……", "d": "Bất kể… đều….", "ok": "不管有没有文化的女性，都可以称丈夫为“老公”。", "vi": "Phụ nữ dù có học hay không đều có thể gọi chồng là “老公”.", "bad": ["不管有没有文化的女性，就可以称丈夫为“老公”。", "虽然有没有文化的女性，都可以称丈夫为“老公”。"]}, {"s": "对……不以为然", "d": "Không đồng tình với….", "ok": "有些人对“老公”这个称呼不以为然。", "vi": "Có người không đồng tình với cách gọi “老公”.", "bad": ["有些人不以为然对“老公”这个称呼。", "有些人对“老公”这个称呼不以为。"]}, {"s": "……在于……", "d": "… nằm ở…, cốt ở….", "ok": "语言的魅力本来就在于它千变万化。", "vi": "Sức hút của ngôn ngữ vốn nằm ở sự biến hóa khôn lường.", "bad": ["语言的魅力本来就在它于千变万化。", "语言的魅力在于是千变万化。"]}], "disc": [{"q": "在越南语里，妻子怎么称呼丈夫？和汉语有什么不同？", "py": "Zài yuènányǔ lǐ, qīzǐ zěnme chēnghū zhàngfu? Hé hànyǔ yǒu shénme bùtóng?", "vi": "Trong tiếng Việt, vợ gọi chồng thế nào? Khác tiếng Trung ra sao?", "keys": ["既……又", "根据", "比如"], "sample": "在越南语里，妻子常叫丈夫“anh”，既亲热又自然。和汉语不同，越南语的称呼要根据年龄和关系来选择，比如对长辈和对朋友就不一样。", "spy": "Zài yuènányǔ lǐ, qīzǐ chángjiào zhàngfu “Anh”, jì qīnrè yòu zìrán. Hé hànyǔ bùtóng, yuènányǔ de chēnghū yào gēnjù niánlíng hé guānxi lái xuǎnzé, bǐrú duì zhǎngbèi hé duì péngyou jiù bù yíyàng."}, {"q": "你觉得“老公”这个称呼好不好？为什么？", "py": "Nǐ juéde “Lǎogōng” zhège chēnghū hǎobùhǎo? Wèishénme?", "vi": "Bạn thấy cách gọi “老公” có hay không? Vì sao?", "keys": ["我觉得", "随着", "不以为然|在于"], "sample": "我觉得“老公”挺好的。随着电视剧的流行，大家都习惯了。虽然有人对它不以为然，但是重要的在于根据场合来选择。", "spy": "Wǒ juéde “Lǎogōng” tǐng hǎo de. Suízhe diànshìjù de liúxíng, dàjiā dōu xíguàn le. Suīrán yǒurén duì tā bùyǐwéirán, dànshì zhòngyào de zàiyú gēnjù chǎnghé lái xuǎnzé."}], "comp": [{"vi": "Cách gọi này vừa thân mật vừa lịch sự. (既……又……)", "keys": ["既", "又"], "model": "这个称呼既亲热又礼貌。", "mpy": "Zhège chēnghū jì qīnrè yòu lǐmào."}, {"vi": "Cùng với sự phát triển của Internet, nhiều từ mới trở nên phổ biến. (随着)", "keys": ["随着"], "model": "随着网络的发展，很多新词流行起来了。", "mpy": "Suízhe wǎngluò de fāzhǎn, hěnduō xīncí liúxíngqǐlái le."}, {"vi": "Bất kể ai cũng đều có thể tham gia. (不管……都……)", "keys": ["不管", "都"], "model": "不管是谁，都可以参加。", "mpy": "Bùguǎnshìshuí, dōu kěyǐ cānjiā."}], "ex": [{"q": "为什么丈夫从不为称呼的事烦恼？", "qvi": "Vì sao chồng chưa bao giờ phiền não chuyện xưng hô?", "a": "因为称呼妻子可以选用的词很多。", "avi": "Vì có rất nhiều từ để gọi vợ.", "bad": ["因为丈夫不需要称呼妻子。", "因为丈夫只叫妻子“太太”。"], "p": 0}, {"q": "“丈夫”这个称呼有什么问题？", "qvi": "Cách gọi “丈夫” có vấn đề gì?", "a": "太文气，只能在介绍时用，不能当面称呼。", "avi": "Quá sách vở, chỉ dùng khi giới thiệu, không gọi trực tiếp.", "bad": ["太俗气了。", "只能当面称呼。"], "p": 1}, {"q": "“先生”适合在什么场合用？", "qvi": "“先生” hợp dùng ở đâu?", "a": "宴会厅、会议室等比较高雅的场所。", "avi": "Phòng tiệc, phòng họp – nơi trang nhã.", "bad": ["在家里穿背心短裤的时候。", "在菜市场买菜的时候。"], "p": 3}, {"q": "为什么文化人不接受“男人”这个称呼？", "qvi": "Vì sao người có học không nhận cách gọi “男人”?", "a": "它显得随便，甚至有些俗气。", "avi": "Nó có vẻ tùy tiện, thậm chí hơi thô tục.", "bad": ["它太严肃了。", "它太浪漫了。"], "p": 4}, {"q": "“老公”是怎么流行起来的？", "qvi": "“老公” đã phổ biến như thế nào?", "a": "随着港台电视剧的播放逐渐流行起来。", "avi": "Dần phổ biến theo phim Hồng Kông, Đài Loan.", "bad": ["是政府规定的。", "是从京味普通话来的。"], "p": 6}, {"q": "作者认为使用称呼最重要的是什么？", "qvi": "Tác giả cho rằng điều quan trọng nhất khi xưng hô là gì?", "a": "要根据场合和不同的对象进行选择。", "avi": "Chọn theo hoàn cảnh và từng đối tượng.", "bad": ["一定要用“老公”。", "只能用“丈夫”。"], "p": 8}]}}, {"id": "hk3-l5", "no": 5, "day": "HK3 · Bài 5", "time": "15:00", "scene": "hall", "room": "hall", "cast": ["prof", "edward", "roland", "zhangdong"], "vi": "Hội trường: kể về thành cổ Tây An", "zh": "说不尽的西安古城", "py": "Shuō bújìn de xīān gǔchéng", "vocab": [["游览", "yóulǎn", "tham quan", ""], ["高楼林立", "gāolóu línlì", "nhà cao tầng san sát", ""], ["现代化", "xiàndàihuà", "hiện đại hóa", ""], ["程度", "chéngdù", "mức độ", ""], ["城镇", "chéngzhèn", "thị trấn", ""], ["发达", "fādá", "phát triển", ""], ["吸引", "xīyǐn", "thu hút", ""], ["古城", "gǔchéng", "thành cổ", ""], ["想象", "xiǎngxiàng", "tưởng tượng", ""], ["白胡子老人", "báihúzi lǎorén", "ông già râu trắng", ""], ["千年", "qiānnián", "nghìn năm", ""], ["灰尘", "huīchén", "bụi", ""], ["打动", "dǎdòng", "làm cảm động", ""], ["相比", "xiāngbǐ", "so với", ""], ["历史遗迹", "lìshǐ yíjì", "di tích lịch sử", ""], ["古迹", "gǔjì", "di tích cổ", ""], ["岁月", "suìyuè", "năm tháng", ""], ["游客", "yóukè", "du khách", ""], ["诉说", "sùshuō", "kể lại", ""], ["文明", "wénmíng", "văn minh", ""], ["辉煌", "huīhuáng", "huy hoàng", ""], ["曾经", "céngjīng", "từng", ""], ["政治", "zhèngzhì", "chính trị", ""], ["经济", "jīngjì", "kinh tế", ""], ["朝代", "cháodài", "triều đại", ""], ["建都", "jiàndū", "đặt kinh đô", ""], ["兵马俑", "Bīngmǎyǒng", "Binh Mã Dũng", ""], ["耳闻", "ěrwén", "nghe danh", ""], ["宏大", "hóngdà", "hùng vĩ", ""], ["规模", "guīmó", "quy mô", ""], ["惊呆", "jīngdāi", "kinh ngạc", ""], ["排列", "páiliè", "xếp hàng", ""], ["成阵", "chéngzhèn", "thành trận", ""], ["整装待发", "zhěngzhuāng dàifā", "chỉnh trang chờ xuất phát", ""], ["军队", "jūnduì", "quân đội", ""], ["统一", "tǒngyī", "thống nhất", ""]], "story": [{"c": "panda", "vi": "HK3 · Hội trường: kể về thành cổ Tây An. Lớp học đại học: mọi người lần lượt đọc bài khóa gốc, giáo sư đặt câu hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "edward", "zh": "在中国，我游览过许多地方。在我去过的地方中，有高楼林立、现代化程度很高的城市，比如上海；有美丽而不太发达的城镇，比如丽江。在这些城市中，最吸引我的是古城西安。", "py": "Zài zhōngguó, wǒ yóulǎn guò xǔduō dìfāng. Zài wǒ qùguò de dìfāng zhōng, yǒu gāolóu línlì, xiàndàihuà chéngdù hěn gāo de chéngshì, bǐrú shànghǎi; yǒu měilì ér bú tài fādá de chéngzhèn, bǐrú lìjiāng. Zài zhèxiē chéngshì zhōng, zuì xīyǐn wǒ de shì gǔchéng xīān.", "vi": "Ở Trung Quốc, tôi đã tham quan nhiều nơi. Trong đó có thành phố nhà cao tầng san sát, hiện đại hóa rất cao như Thượng Hải; có thị trấn xinh đẹp nhưng chưa phát triển lắm như Lệ Giang. Trong những thành phố ấy, thu hút tôi nhất là thành cổ Tây An."}, {"c": "prof", "zh": "作者去过的地方中，最吸引他的是哪儿？", "py": "Zuòzhě qùguò de dìfāng zhōng, zuì xīyǐn tā de shì nǎr?", "vi": "Trong những nơi đã đến, nơi nào thu hút tác giả nhất?"}, {"me": "Thành cổ Tây An.", "opts": [["古城西安。", "Gǔchéng xīān.", "Thành cổ Tây An."], ["上海。", "Shànghǎi.", "(chưa đúng với nội dung đoạn văn)"], ["丽江。", "Lìjiāng.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "roland", "zh": "没到西安前，我想象中的西安是一个“白胡子老人”——他走过了千年历史，身上盖满了灰尘。可是，当我走进西安时，还是被打动了。与我去过的其他城市相比，西安的历史遗迹简直是太多了，这些古迹透过岁月的灰土，向游客们解释着历史，诉说着古代文明的辉煌。", "py": "Méi dào xīān qián, wǒ xiǎngxiàng zhōng de xīān shì yíge “Báihúzi lǎorén” —— tā zǒuguò le qiānnián lìshǐ, shēnshàng gàimǎn le huīchén. Kěshì, dāng wǒ zǒujìn xīān shí, háishì bèi dǎdòng le. Yǔ wǒ qùguò de qítā chéngshì xiāngbǐ, xīān de lìshǐ yíjì jiǎnzhí shì tài duō le, zhèxiē gǔjì tòuguò suìyuè de huītǔ, xiàng yóukè men jiěshì zhe lìshǐ, sùshuōzhe gǔdàiwénmíng de huīhuáng.", "vi": "Trước khi đến, Tây An trong tưởng tượng của tôi là một \"ông già râu trắng\" – đã đi qua nghìn năm lịch sử, người phủ đầy bụi. Thế nhưng khi bước vào Tây An, tôi vẫn bị lay động. So với những thành phố khác tôi từng đến, di tích lịch sử ở Tây An thật quá nhiều; những cổ tích ấy xuyên qua lớp bụi năm tháng, giải thích lịch sử cho du khách, kể lại sự huy hoàng của văn minh cổ đại."}, {"c": "prof", "zh": "没到西安前，作者想象中的西安是什么样的？", "py": "Méi dào xīān qián, zuòzhě xiǎngxiàng zhōng de xīān shì shénmeyàng de?", "vi": "Trước khi đến, Tây An trong tưởng tượng thế nào?"}, {"me": "Một “ông già râu trắng” phủ đầy bụi.", "opts": [["一个身上盖满灰尘的“白胡子老人”。", "Yíge shēnshàng gài mǎnhuīchén de “Báihúzi lǎorén”.", "Một “ông già râu trắng” phủ đầy bụi."], ["一个高楼林立的现代化城市。", "Yíge gāolóu línlì de xiàndàihuà chéngshì.", "(chưa đúng với nội dung đoạn văn)"], ["一个美丽而不太发达的小镇。", "Yíge měilì ér bú tài fādá de xiǎozhèn.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "prof", "zh": "与其他城市相比，西安有什么特点？", "py": "Yǔ qítā chéngshì xiāngbǐ, xīān yǒu shénme tèdiǎn?", "vi": "So với thành phố khác, Tây An có gì đặc biệt?"}, {"me": "Di tích lịch sử rất nhiều.", "opts": [["历史遗迹特别多。", "Lìshǐ yíjì tèbié duō.", "Di tích lịch sử rất nhiều."], ["高楼特别多。", "Gāolóu tèbié duō.", "(chưa đúng với nội dung đoạn văn)"], ["游客特别少。", "Yóukè tèbié shǎo.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "zhangdong", "zh": "西安曾经是中国古代的政治、经济中心，历史上许多朝代都建都于此。去西安当然首先要看兵马俑。虽然对兵马俑我早有耳闻，但来到它跟前时，我还是被它宏大的规模惊呆了：一千多个与真人大小相同的兵马俑排列成阵，好像一支整装待发的军队。我一下子明白了，为什么当年是秦始皇，而不是别人统一了中国——因为秦始皇有这样一支军队。", "py": "Xīān céngjīng shì zhōngguó gǔdài de zhèngzhì, jīngjì zhōngxīn, lìshǐ shàng xǔduō cháodài dōu jiàndūyú cǐ. Qù xīān dāngrán shǒuxiān yào kàn bīngmǎyǒng. Suīrán duì bīngmǎyǒng wǒ zǎo yǒu ěrwén, dàn láidào tā gēnqián shí, wǒ háishì bèi tā hóngdà de guīmó jīngdāi le: Yìqiānduōge yǔ zhēnrén dàxiǎo xiāngtóng de bīngmǎyǒng páilièchéng zhèn, hǎoxiàng yìzhī zhěngzhuāngdàifā de jūnduì. Wǒ yíxiàzi míngbái le, wèishénme dāngnián shì qínshǐhuáng, ér búshì biérén tǒngyī le zhōngguó—— yīnwèi qínshǐhuáng yǒu zhèyàng yìzhī jūnduì.", "vi": "Tây An từng là trung tâm chính trị, kinh tế của Trung Quốc cổ đại, nhiều triều đại đóng đô ở đây. Đến Tây An đương nhiên trước hết phải xem tượng Binh Mã. Tuy đã nghe danh từ lâu, nhưng khi đến trước mặt, tôi vẫn sững sờ trước quy mô hùng vĩ: hơn một nghìn tượng binh mã to bằng người thật xếp thành trận, như một đội quân chỉnh tề chờ xuất phát. Tôi bỗng hiểu vì sao năm xưa là Tần Thủy Hoàng chứ không phải ai khác thống nhất Trung Quốc – vì ông có một đội quân như thế."}, {"c": "prof", "zh": "作者认为秦始皇为什么能统一中国？", "py": "Zuòzhě rènwéi qínshǐhuáng wèishénme néng tǒngyì zhōngguó?", "vi": "Vì sao tác giả cho rằng Tần Thủy Hoàng thống nhất được Trung Quốc?"}, {"me": "Vì Tần Thủy Hoàng có đội quân như tượng Binh Mã.", "opts": [["因为秦始皇有像兵马俑这样的军队。", "Yīnwèi qínshǐhuáng yǒu xiàng bīngmǎyǒng zhèyàng de jūnduì.", "Vì Tần Thủy Hoàng có đội quân như tượng Binh Mã."], ["因为秦始皇建了很多高楼。", "Yīnwèi qínshǐhuáng jiànle hěnduō gāolóu.", "(chưa đúng với nội dung đoạn văn)"], ["因为西安离上海很近。", "Yīnwèi xīān lí shànghǎi hěnjìn.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "与……相比", "d": "So với….", "ex": [["与我去过的其他城市相比，西安的历史遗迹太多了。", "Yǔ wǒ qùguò de qítā chéngshì xiāngbǐ, xīān de lìshǐ yíjì tàiduō le.", "So với các thành phố khác, di tích ở Tây An nhiều quá."]]}, {"t": "虽然……但……还是……", "d": "Tuy… nhưng vẫn….", "ex": [["虽然对兵马俑我早有耳闻，但来到它跟前时，我还是被惊呆了。", "Suīrán duì bīngmǎyǒng wǒ zǎo yǒu ěrwén, dàn láidào tā gēnqián shí, wǒ háishì bèi jīngdāi le.", "Tuy đã nghe danh từ lâu, nhưng đến trước mặt tôi vẫn sững sờ."]]}, {"t": "被 + (tác nhân) + V + bổ ngữ", "d": "Câu bị động: chủ ngữ chịu tác động.", "ex": [["我还是被它宏大的规模惊呆了。", "Wǒ háishì bèi tā hóngdà de guīmó jīngdāi le.", "Tôi vẫn sững sờ trước quy mô hùng vĩ của nó."]]}, {"t": "是 A，而不是 B", "d": "Là A chứ không phải B (nhấn mạnh).", "ex": [["当年是秦始皇，而不是别人统一了中国。", "Dāngnián shì qínshǐhuáng, ér búshì biérén tǒngyī le zhōngguó.", "Năm xưa là Tần Thủy Hoàng chứ không phải ai khác đã thống nhất Trung Quốc."]]}], "order": [], "u": {"gq": [{"s": "与……相比", "d": "So với….", "ok": "与我去过的其他城市相比，西安的历史遗迹太多了。", "vi": "So với các thành phố khác, di tích ở Tây An nhiều quá.", "bad": ["与我去过的其他城市比较起，西安的历史遗迹太多了。", "相比与我去过的其他城市，西安的历史遗迹太多了。"]}, {"s": "虽然……但……还是……", "d": "Tuy… nhưng vẫn….", "ok": "虽然对兵马俑我早有耳闻，但来到它跟前时，我还是被惊呆了。", "vi": "Tuy đã nghe danh từ lâu, nhưng đến trước mặt tôi vẫn sững sờ.", "bad": ["虽然对兵马俑我早有耳闻，所以来到它跟前时，我还是被惊呆了。", "对兵马俑我虽然早有耳闻，而且来到它跟前时，我还是被惊呆了。"]}, {"s": "被 + (tác nhân) + V + bổ ngữ", "d": "Câu bị động: chủ ngữ chịu tác động.", "ok": "我还是被它宏大的规模惊呆了。", "vi": "Tôi vẫn sững sờ trước quy mô hùng vĩ của nó.", "bad": ["我还是被惊呆了它宏大的规模。", "我还是被它宏大的规模惊呆。了"]}, {"s": "是 A，而不是 B", "d": "Là A chứ không phải B (nhấn mạnh).", "ok": "当年是秦始皇，而不是别人统一了中国。", "vi": "Năm xưa là Tần Thủy Hoàng chứ không phải ai khác đã thống nhất Trung Quốc.", "bad": ["当年是秦始皇，而是不别人统一了中国。", "当年是秦始皇，不而是别人统一了中国。"]}], "disc": [{"q": "介绍一个你去过的城市，和西安比一比。", "py": "Jièshào yíge nǐ qùguò de chéngshì, hé xīān bǐyìbǐ.", "vi": "Giới thiệu một thành phố bạn từng đến, so sánh với Tây An.", "keys": ["与……相比", "虽然……但|虽然……还是", "被"], "sample": "我去过顺化。与西安相比，顺化没有那么大，但是也有很多古迹。虽然我早就听说过顺化皇城，但是走进去的时候，我还是被它的美打动了。", "spy": "Wǒ qùguò shùnhuà. Yǔ xīān xiāngbǐ, shùnhuà méiyǒu nàme dà, dànshì yě yǒu hěnduō gǔjì. Suīrán wǒ zǎojiù tīngshuō guò shùnhuà huángchéng, dànshì zǒujìn qù de shíhou, wǒ háishì bèi tā de měi dǎdòng le."}], "comp": [{"vi": "So với Thượng Hải, Tây An có nhiều di tích hơn. (与……相比)", "keys": ["与", "相比"], "model": "与上海相比，西安的古迹更多。", "mpy": "Yǔ shànghǎi xiāngbǐ, xīān de gǔjì gèng duō."}, {"vi": "Tôi bị quy mô của tượng Binh Mã làm cho sững sờ. (被)", "keys": ["被"], "model": "我被兵马俑的规模惊呆了。", "mpy": "Wǒ bèi bīngmǎyǒng de guīmó jīngdāi le."}], "ex": [{"q": "作者去过的地方中，最吸引他的是哪儿？", "qvi": "Trong những nơi đã đến, nơi nào thu hút tác giả nhất?", "a": "古城西安。", "avi": "Thành cổ Tây An.", "bad": ["上海。", "丽江。"], "p": 0}, {"q": "没到西安前，作者想象中的西安是什么样的？", "qvi": "Trước khi đến, Tây An trong tưởng tượng thế nào?", "a": "一个身上盖满灰尘的“白胡子老人”。", "avi": "Một “ông già râu trắng” phủ đầy bụi.", "bad": ["一个高楼林立的现代化城市。", "一个美丽而不太发达的小镇。"], "p": 1}, {"q": "与其他城市相比，西安有什么特点？", "qvi": "So với thành phố khác, Tây An có gì đặc biệt?", "a": "历史遗迹特别多。", "avi": "Di tích lịch sử rất nhiều.", "bad": ["高楼特别多。", "游客特别少。"], "p": 1}, {"q": "作者认为秦始皇为什么能统一中国？", "qvi": "Vì sao tác giả cho rằng Tần Thủy Hoàng thống nhất được Trung Quốc?", "a": "因为秦始皇有像兵马俑这样的军队。", "avi": "Vì Tần Thủy Hoàng có đội quân như tượng Binh Mã.", "bad": ["因为秦始皇建了很多高楼。", "因为西安离上海很近。"], "p": 2}]}}, {"id": "hk3-l6", "no": 6, "day": "HK3 · Bài 6", "time": "15:45", "scene": "street", "room": "street", "cast": ["prof", "driver", "lee", "meimei"], "vi": "Xe buýt: hồi ức tuổi thơ", "zh": "童年的回忆", "py": "Tóngnián de huíyì", "vocab": [["往事", "wǎngshì", "Việc quá khứ, chuyện cũ", ""], ["的确", "díquè", "Quả thực, đích thị", ""], ["出神", "chūshén", "Ngẩn ngơ, thẫn thờ, xuất thần", ""], ["浩荡", "hàodàng", "Mênh mông, cuồn cuộn (nước)", ""], ["清亮", "qīngliàng", "Trong suốt, trong vắt", ""], ["绿油油", "lùyóuyóu", "Xanh mướt, xanh rì", ""], ["柏油路", "bǎyóulù", "Đường nhựa", ""], ["地区", "dìqū", "Khu vực, vùng", ""], ["仿佛", "fǎngfú", "Giống như, dường như", ""], ["新鲜", "xīnxiān", "Mới mẻ, tươi mới", ""], ["看不够", "kàn bù gòu", "Xem mãi không chán", ""], ["迷上", "mí shàng", "Mê mẩn, say mê cái gì", ""], ["免费", "miǎnfèi", "Miễn phí", ""], ["错过", "cuòguò", "Bỏ lỡ", ""], ["制服", "zhìfú", "Đồng phục", ""], ["熨", "yùn", "Là, ủi (quần áo)", ""], ["笔直", "bǐzhí", "Thẳng tắp", ""], ["骄傲", "jiāo'ào", "Kiêu hãnh, tự hào", ""], ["秩序井井有条", "zhìxù jǐngjǐngyǒutiáo", "Trật tự ngăn nắp, đâu ra đấy", ""], ["服从", "fúcóng", "Phục tùng", ""], ["崇拜", "chóngbài", "Sùng bái", ""], ["诧异", "chàyì", "Ngạc nhiên, sửng sốt", ""], ["老老实实", "lǎolǎoshíshí", "Thật thà, ngoan ngoãn", ""], ["详细", "xiángxì", "Chi tiết, tỉ mỉ", ""], ["盘问", "pánwèn", "Gặng hỏi, tra hỏi", ""], ["管闲事", "guǎn xiánshì", "Bao đồng, lo chuyện bao đồ (chuyện thiên hạ)", ""], ["注视", "zhùshì", "Chú ý nhìn, nhìn chăm chú", ""], ["背影", "bèiyǐng", "Bóng lưng", ""], ["能干", "nénggàn", "Tháo vát, năng lực", ""], ["辩护", "biànhù", "Biện hộ", ""], ["摆脱", "bǎituō", "Thoát khỏi, rũ bỏ", ""], ["宇航员", "yǔhángyuán", "Nhà du hành vũ trụ", ""], ["竟然", "jìngrán", "Lại có thể, bất ngờ là (biểu thị sự ngạc nhiên)", ""], ["走向社会", "zǒu xiàng shèhuì", "Bước vào xã hội", ""], ["佩服", "pèifú", "Khâm phục, thán phục", ""], ["普普通通", "pǔpǔtōngtōng", "Bình thường, tầm thường", ""]], "story": [{"c": "panda", "vi": "HK3 · Xe buýt: hồi ức tuổi thơ. Lớp học đại học: mọi người lần lượt đọc bài khóa gốc, giáo sư đặt câu hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "driver", "zh": "人们都说，孩子眼睛里的东西总是美好的。回想我童年的一些往事，我觉得的确是这样。", "py": "Rénmen dōu shuō, háizi yǎnjīng lǐ de dōngxi zǒngshì měihǎo de. Huíxiǎng wǒ tóngnián de yìxiē wǎngshì, wǒ juéde díquè shì zhèyàng.", "vi": "Người ta đều nói, những gì trong mắt trẻ con luôn đẹp đẽ. Nhớ lại vài chuyện cũ thời thơ ấu, tôi thấy quả đúng như vậy."}, {"c": "lee", "zh": "还记得，我六岁那一年的春天，有一天我跟母亲去买东西，回家的路上，我坐在公共汽车上出神地看着农村的景色。外边下着细细的雨，路的左边是一条河，因为那两天下雨，河水浩荡，平常清亮透明的河水也变黄了。河的对岸是一片绿油油的山野，河的右边是农村住宅，一条柏油路从中间穿过，路边成百上千只奶牛好奇地看着我坐的“大铁箱”。我就住在这个地区，虽然很熟悉这里的东南西北，可是从公共汽车里看到的村子仿佛和平时看到的完全不一样了，觉得很新鲜。绿树、小河、奶牛，我睁着眼睛看也看不够……", "py": "Hái jìde, wǒ liùsuì nà yìnián de chūntiān, yǒu yìtiān wǒ gēn mǔqīn qù mǎi dōngxi, huíjiā de lùshàng, wǒ zuòzài gōnggòngqìchē shàng chūshén dì kànzhe nóngcūn de jǐngsè. Wàibiān xià zhe xìxìde yǔ, lù de zuǒbian shì yìtiáo hé, yīnwèi nà liǎngtiān xiàyǔ, héshuǐ hàodàng, píngcháng qīngliàng tòumíng de héshuǐ yě biàn huáng le. Hé de duìàn shì yípiàn lǜyóuyóu de shānyě, hé de yòubian shì nóngcūn zhùzhái, yìtiáo bǎiyóulù cóng zhōngjiān chuānguò, lùbiān chéngbǎishàngqiān zhǐ nǎiniú hàoqí dì kànzhe wǒ zuò de “Dà tiěxiāng”. Wǒ jiù zhù zài zhège dìqū, suīrán hěn shúxī zhèlǐ de dōngnánxīběi, kěshì cóng gōnggòngqìchē lǐ kàndào de cūnzi fǎngfú hé píngshí kàndào de wánquán bù yíyàng le, juéde hěn xīnxiān. Lǜshù, xiǎohé, nǎiniú, wǒ zhēng zhe yǎnjīng kàn yě kàn búgòu……", "vi": "Tôi vẫn nhớ, mùa xuân năm sáu tuổi, một hôm tôi theo mẹ đi mua đồ; trên đường về, tôi ngồi trên xe buýt ngẩn người ngắm cảnh nông thôn. Ngoài trời mưa lất phất, bên trái đường là con sông; vì mưa mấy hôm nên nước cuồn cuộn, dòng nước vốn trong vắt cũng ngả vàng. Bờ bên kia là đồi núi xanh mướt, bên phải là nhà cửa nông thôn, con đường nhựa chạy xuyên qua giữa, bên đường hàng trăm hàng nghìn con bò sữa tò mò nhìn chiếc \"hộp sắt lớn\" tôi ngồi. Tôi sống ngay ở vùng này, rất quen đông tây nam bắc, nhưng ngôi làng nhìn từ trong xe buýt dường như khác hẳn ngày thường, rất mới mẻ. Cây xanh, sông nhỏ, bò sữa – tôi mở to mắt nhìn mãi không chán…"}, {"c": "prof", "zh": "六岁那年，作者在公共汽车上看到了什么？", "py": "Liùsuì nànián, zuòzhě zài gōnggòngqìchē shàng kàndào le shénme?", "vi": "Năm sáu tuổi, tác giả thấy gì trên xe buýt?"}, {"me": "Sông, đồi núi xanh mướt và hàng trăm hàng nghìn con bò sữa.", "opts": [["河、绿油油的山野和成百上千只奶牛。", "Hé, lǜyóuyóu de shānyě hé chéngbǎishàngqiān zhǐ nǎiniú.", "Sông, đồi núi xanh mướt và hàng trăm hàng nghìn con bò sữa."], ["高楼和地铁。", "Gāolóu hé dìtiě.", "(chưa đúng với nội dung đoạn văn)"], ["大海和沙滩。", "Dàhǎi hé shātān.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "meimei", "zh": "于是，我迷上了坐公共汽车，成了个坐车迷。在日本，6岁以下的儿童坐公共汽车都免费，作为一个坐车迷怎么能错过这个机会？因此，我每天从幼儿园回来后，马上就去汽车站坐公共汽车。", "py": "Yúshì, wǒmí shàng le zuò gōnggòngqìchē, chéng le ge zuòchē mí. Zài rìběn, 6 suì yǐxià de értóng zuò gōnggòngqìchē dōu miǎnfèi, zuòwéi yíge zuòchē mí zěnme néng cuòguò zhège jīhuì? Yīncǐ, wǒ měitiān cóng yòuéryuán huílái hòu, mǎshàng jiù qù qìchēzhàn zuò gōnggòngqìchē.", "vi": "Thế là tôi mê đi xe buýt, thành một \"fan\" đi xe. Ở Nhật, trẻ dưới 6 tuổi đi xe buýt miễn phí, là fan đi xe sao có thể bỏ lỡ cơ hội này? Vì vậy ngày nào từ nhà trẻ về, tôi cũng lập tức ra bến đi xe buýt."}, {"c": "prof", "zh": "作者为什么每天去坐公共汽车？", "py": "Zuòzhě wèishénme měitiān qù zuò gōnggòngqìchē?", "vi": "Vì sao ngày nào tác giả cũng đi xe buýt?"}, {"me": "Cậu mê đi xe và trẻ dưới 6 tuổi được miễn phí.", "opts": [["他迷上了坐车，而且6岁以下坐车免费。", "Tā míshàng le zuòchē, érqiě6 suì yǐxià zuòchē miǎnfèi.", "Cậu mê đi xe và trẻ dưới 6 tuổi được miễn phí."], ["他要去幼儿园上课。", "Tā yào qù yòuéryuán shàngkè.", "(chưa đúng với nội dung đoạn văn)"], ["妈妈让他去买东西。", "Māma ràng tā qù mǎi dōngxi.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "driver", "zh": "我乘坐的公共汽车是3点45分出发，开这班车的司机是佐藤先生。他穿着整齐的制服，裤线熨得笔直，像用裁纸刀裁出来的一样；他戴着的黑亮的司机帽显示着他对自己工作的骄傲。他是这班车的唯一的工作人员，乘客从后门上车，在前门给他交车费下车，秩序井井有条。在这辆车里，他是国王，大家都服从他，按他的要求去做。我觉得他比任何人都强。小男孩儿一般都崇拜强壮的英雄。除了父亲以外，佐藤是我遇见的第一个英雄。", "py": "Wǒ chéngzuò de gōnggòngqìchē shì3 diǎn45 fēn chūfā, kāi zhè bānchē de sījī shì Zuǒténg xiānsheng. Tā chuānzhe zhěngqí de zhìfú, kùxiàn yùndé bǐzhí, xiàng yòng cáizhǐdāo cái chūlái de yíyàng; tā dài zhe de hēiliàng de sījī mào xiǎnshì zhe tā duì zìjǐ gōngzuò de jiāoào. Tā shì zhè bānchē de wéiyī de gōngzuòrényuán, chéngkè cóng hòumén shàngchē, zài qiánmén gěi tā jiāo chēfèi xiàchē, zhìxù jǐngjǐngyǒutiáo. Zài zhèliàng chēlǐ, tā shì guówáng, dàjiā dōu fúcóng tā, àn tā de yāoqiú qù zuò. Wǒ juéde tā bǐ rènhérén dōu qiáng. Xiǎo nánháir yìbān dōu chóngbài qiángzhuàng de yīngxióng. Chúle fùqīn yǐwài, Zuǒténg shì wǒ yùjiàn de dìyīge yīngxióng.", "vi": "Chuyến xe tôi đi khởi hành lúc 3 giờ 45, tài xế là ông Sato. Ông mặc đồng phục chỉnh tề, nếp quần là thẳng tắp như cắt bằng dao rọc giấy; chiếc mũ tài xế đen bóng cho thấy ông tự hào về công việc của mình. Ông là nhân viên duy nhất trên xe; hành khách lên cửa sau, xuống cửa trước và trả tiền cho ông, trật tự đâu ra đấy. Trong chiếc xe này ông là vua, mọi người đều nghe theo ông. Tôi thấy ông giỏi hơn bất cứ ai. Con trai nhỏ thường sùng bái người hùng mạnh mẽ. Ngoài bố ra, ông Sato là người hùng đầu tiên tôi gặp."}, {"c": "prof", "zh": "佐藤先生是一个什么样的司机？", "py": "Zuǒténg xiānsheng shì yíge shénmeyàng de sījī?", "vi": "Ông Sato là tài xế như thế nào?"}, {"me": "Ăn mặc chỉnh tề, tự hào về công việc.", "opts": [["穿着整齐，对自己的工作很骄傲。", "Chuānzhe zhěngqí, duì zìjǐ de gōngzuò hěn jiāoào.", "Ăn mặc chỉnh tề, tự hào về công việc."], ["很爱跟乘客聊天。", "Hěn ài gēn chéngkè liáotiān.", "(chưa đúng với nội dung đoạn văn)"], ["常常迟到。", "Chángcháng chídào.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "lee", "zh": "那时候，大人看见小孩儿一个人坐车，就会觉得奇怪。于是常有人诧异地问我：“到哪儿去啊？”“你妈妈呢？”我每次遇到这种情况都老老实实地回答：“我喜欢坐车。”其实，要详细回答这个问题，必须是这样：“我只是喜欢坐车，我可以免费乘坐，而且这班车的乘客不多，不影响别人；我只坐一站就下车回家，不用担心。”可是我当时的脑子不够用，没有能力说这样的话。我以为简单地说我喜欢坐车就解释得很清楚了，可是大人们却觉得很奇怪，他们的盘问越来越厉害了。我心里想：大人真喜欢管闲事，他们想把事情弄复杂。正在这时候，佐藤先生大声说话了：“不用担心，”他一直注视着前面的路，没有回头，“我认识他的父母，终点站那儿有他母亲的单位，家长在那儿接他。”这句话当然是真的，可是听起来，连我也觉得我的母亲会在终点站等着我。佐藤先生跟平时一样，像什么事都没发生过一样，头也没回，认认真真地驾驶着这个“大铁箱”。我们只能看到他高大的背影，他那严肃的背影仍然显示着他对工作的自豪。", "py": "Nà shíhou, dàrén kànjiàn xiǎoháir yíge rén zuòchē, jiù huì juéde qíguài. Yúshì chángyǒu rén chàyì dìwèn wǒ: “Dào nǎr qù a?” “Nǐ māma ne?” wǒ měicì yùdào zhèzhǒng qíngkuàng dōu lǎolǎoshíshí dì huídá: “Wǒ xǐhuan zuòchē.” qíshí, yào xiángxì huídá zhège wèntí, bìxū shì zhèyàng: “Wǒ zhǐshì xǐhuan zuòchē, wǒ kěyǐ miǎnfèi chéngzuò, érqiě zhè bānchē de chéngkè bù duō, bù yǐngxiǎng biérén; wǒ zhǐ zuò yízhàn jiù xiàchē huíjiā, búyòng dānxīn.” kěshì wǒ dāngshí de nǎozi búgòu yòng, méiyǒu nénglì shuō zhèyàngdehuà. Wǒ yǐwéi jiǎndān dì shuō wǒ xǐhuan zuòchē jiù jiěshì de hěn qīngchǔ le, kěshì dà rénmen què juéde hěn qíguài, tāmen de pánwèn yuèláiyuè lìhài le. Wǒ xīnlǐ xiǎng: Dàrén zhēn xǐhuan guǎnxiánshì, tāmen xiǎng bǎ shìqing nòng fùzá. Zhèngzài zhèshíhòu, Zuǒténg xiānsheng dàshēng shuōhuà le: “Búyòng dānxīn,” tā yìzhí zhùshì zhe qiánmiàn de lù, méiyǒu huítóu, “Wǒ rènshi tā de fùmǔ, zhōngdiǎnzhàn nàr yǒu tā mǔqīn de dānwèi, jiāzhǎng zài nàr jiē tā.” zhèjù huà dāngrán shì zhēnde, kěshì tīng qǐlái, lián wǒ yě juéde wǒ de mǔqīn huì zài zhōngdiǎnzhàn děng zhe wǒ. Zuǒténg xiānsheng gēn píngshí yíyàng, xiàng shénme shì dōu méi fāshēng guò yíyàng, tóu yě méihuí, rènrènzhēnzhēn dì jiàshǐ zhe zhège “Dà tiěxiāng”. Wǒmen zhǐnéng kàndào tā gāodà de bèiyǐng, tā nà yánsù de bèiyǐng réngrán xiǎnshì zhe tā duì gōngzuò de zìháo.", "vi": "Hồi ấy, người lớn thấy trẻ con đi xe một mình thì thấy lạ, nên thường có người ngạc nhiên hỏi: \"Đi đâu đấy?\" \"Mẹ cháu đâu?\" Lần nào tôi cũng thật thà đáp: \"Cháu thích đi xe.\" Thật ra muốn trả lời đầy đủ phải nói: \"Cháu chỉ thích đi xe, cháu được đi miễn phí, chuyến này ít khách, không ảnh hưởng ai; cháu chỉ đi một bến rồi xuống về nhà, không cần lo.\" Nhưng khi đó đầu óc tôi chưa đủ để nói như thế. Tôi tưởng nói thích đi xe là đã rõ, nhưng người lớn lại thấy lạ, tra hỏi ngày càng gắt. Tôi nghĩ: người lớn thật thích lo chuyện bao đồng. Đúng lúc ấy ông Sato lên tiếng: \"Không cần lo,\" mắt vẫn nhìn đường, không quay lại, \"tôi quen bố mẹ cháu, ở bến cuối có cơ quan của mẹ cháu, phụ huynh đón cháu ở đó.\" Nghe xong, đến tôi cũng thấy như mẹ đang đợi ở bến cuối. Ông Sato vẫn như thường, như chưa có chuyện gì, chăm chú lái chiếc \"hộp sắt lớn\". Chúng tôi chỉ thấy bóng lưng cao lớn, nghiêm nghị của ông, vẫn toát lên niềm tự hào với công việc."}, {"c": "prof", "zh": "大人们盘问作者时，佐藤先生怎么做？", "py": "Dà rénmen pánwèn zuòzhě shí, Zuǒténg xiānsheng zěnme zuò?", "vi": "Khi người lớn tra hỏi, ông Sato làm gì?"}, {"me": "Ông nói quen bố mẹ cậu, mẹ đón ở bến cuối.", "opts": [["他说认识作者的父母，母亲在终点站接他。", "Tā shuō rènshi zuòzhě de fùmǔ, mǔqīn zài zhōngdiǎnzhàn jiē tā.", "Ông nói quen bố mẹ cậu, mẹ đón ở bến cuối."], ["他让作者马上下车。", "Tā ràng zuòzhě mǎshàng xiàchē.", "(chưa đúng với nội dung đoạn văn)"], ["他给作者的妈妈打电话。", "Tā gěi zuòzhě de māma dǎdiànhuà.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "meimei", "zh": "就这样，佐藤先生这时成了我心中的英雄。他就像能干的律师一样为我巧妙地辩护，使我摆脱了人们的好奇，我更喜欢他了。可是我从来没有跟他聊过天儿，我很想跟他说话，可是我怕他因为认真工作而不理我，所以只能坐在他的后面，看着他高大的背影。后来，我由于崇拜佐藤先生，想当宇航员的梦想竟然变成了当公共汽车司机！", "py": "Jiù zhèyàng, Zuǒténg xiānsheng zhèshí chéng le wǒ xīnzhōng de yīngxióng. Tā jiù xiàng nénggàn de lǜshī yíyàng wèi wǒ qiǎomiào dì biànhù, shǐ wǒ bǎituō le rénmen de hàoqí, wǒ gèng xǐhuan tā le. Kěshì wǒ cónglái méiyǒu gēn tā liáoguò tiānr, wǒ hěn xiǎng gēn tā shuōhuà, kěshì wǒpà tā yīnwèi rènzhēn gōngzuò ér bùlǐ wǒ, suǒyǐ zhǐnéng zuòzài tā de hòumiàn, kànzhe tā gāodà de bèiyǐng. Hòulái, wǒ yóuyú chóngbài Zuǒténg xiānsheng, xiǎngdāng yǔhángyuán de mèngxiǎng jìngrán biànchéng le dāng gōnggòngqìchē sījī!", "vi": "Cứ thế, ông Sato trở thành người hùng trong lòng tôi. Ông như một luật sư giỏi khéo léo bào chữa cho tôi, giúp tôi thoát khỏi sự tò mò của mọi người, tôi càng quý ông. Nhưng tôi chưa từng trò chuyện với ông; tôi rất muốn, nhưng sợ ông vì chăm chú làm việc mà không để ý tới tôi, nên chỉ ngồi phía sau nhìn bóng lưng ấy. Về sau, vì sùng bái ông Sato, ước mơ làm phi hành gia của tôi lại biến thành làm tài xế xe buýt!"}, {"c": "prof", "zh": "作者后来的梦想变成了什么？", "py": "Zuòzhě hòulái de mèngxiǎng biànchéng le shénme?", "vi": "Ước mơ sau này của tác giả là gì?"}, {"me": "Làm tài xế xe buýt.", "opts": [["当公共汽车司机。", "Dāng gōnggòngqìchē sījī.", "Làm tài xế xe buýt."], ["当宇航员。", "Dāng yǔhángyuán.", "(chưa đúng với nội dung đoạn văn)"], ["当律师。", "Dāng lǜshī.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "driver", "zh": "现在，作为一个开始走向社会的青年，我回忆起佐藤先生，仍然很佩服他对工作认真的态度。虽然他只是一个普普通通的司机，可是他是我童年时眼中的英雄。", "py": "Xiànzài, zuòwéi yíge kāishǐ zǒuxiàng shèhuì de qīngnián, wǒ huíyìqǐ Zuǒténg xiānsheng, réngrán hěn pèifú tā duì gōngzuò rènzhēn de tàidù. Suīrán tā zhǐshì yíge pǔpǔtōngtōng de sījī, kěshì tā shì wǒ tóngnián shí yǎnzhōng de yīngxióng.", "vi": "Giờ đây, là một thanh niên bắt đầu bước vào xã hội, nhớ lại ông Sato, tôi vẫn rất khâm phục thái độ làm việc nghiêm túc của ông. Tuy chỉ là một tài xế bình thường, ông là người hùng trong mắt tôi thời thơ ấu."}, {"c": "prof", "zh": "现在作者最佩服佐藤先生什么？", "py": "Xiànzài zuòzhě zuì pèifú Zuǒténg xiānsheng shénme?", "vi": "Giờ tác giả khâm phục ông Sato điều gì nhất?"}, {"me": "Thái độ làm việc nghiêm túc.", "opts": [["他对工作认真的态度。", "Tā duì gōngzuò rènzhēn de tàidù.", "Thái độ làm việc nghiêm túc."], ["他的司机帽。", "Tā de sījī mào.", "(chưa đúng với nội dung đoạn văn)"], ["他开车开得很快。", "Tā kāichē kāi de hěnkuài.", "(chưa đúng với nội dung đoạn văn)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "除了……以外", "d": "Ngoài… ra.", "ex": [["除了父亲以外，佐藤是我遇见的第一个英雄。", "Chúle fùqīn yǐwài, Zuǒténg shì wǒ yùjiàn de dìyīge yīngxióng.", "Ngoài bố ra, Sato là người hùng đầu tiên tôi gặp."]]}, {"t": "由于", "d": "Do, vì (văn viết), đứng đầu vế nguyên nhân.", "ex": [["由于崇拜佐藤先生，我想当公共汽车司机。", "Yóuyú chóngbài Zuǒténg xiānsheng, wǒ xiǎng dāng gōnggòngqìchē sījī.", "Vì sùng bái ông Sato, tôi muốn làm tài xế xe buýt."]]}, {"t": "连……也……", "d": "Ngay cả… cũng….", "ex": [["连我也觉得我的母亲会在终点站等着我。", "Lián wǒ yě juéde wǒ de mǔqīn huì zài zhōngdiǎnzhàn děng zhe wǒ.", "Ngay cả tôi cũng thấy như mẹ đang đợi ở bến cuối."]]}, {"t": "越来越", "d": "Ngày càng…; không thêm 很 phía sau.", "ex": [["他们的盘问越来越厉害了。", "Tāmen de pánwèn yuèláiyuè lìhài le.", "Họ tra hỏi ngày càng gắt."]]}, {"t": "V + 着", "d": "Trạng thái đang tiếp diễn.", "ex": [["外边下着细细的雨。", "Wàibiān xià zhe xìxìde yǔ.", "Ngoài trời đang mưa lất phất."]]}], "order": [], "u": {"gq": [{"s": "除了……以外", "d": "Ngoài… ra.", "ok": "除了父亲以外，佐藤是我遇见的第一个英雄。", "vi": "Ngoài bố ra, Sato là người hùng đầu tiên tôi gặp.", "bad": ["除了以外父亲，佐藤是我遇见的第一个英雄。", "除了父亲，以外佐藤是我遇见的第一个英雄。"]}, {"s": "由于", "d": "Do, vì (văn viết), đứng đầu vế nguyên nhân.", "ok": "由于崇拜佐藤先生，我想当公共汽车司机。", "vi": "Vì sùng bái ông Sato, tôi muốn làm tài xế xe buýt.", "bad": ["由于崇拜佐藤先生，但是我想当公共汽车司机。", "我想当公共汽车司机由于崇拜。"]}, {"s": "连……也……", "d": "Ngay cả… cũng….", "ok": "连我也觉得我的母亲会在终点站等着我。", "vi": "Ngay cả tôi cũng thấy như mẹ đang đợi ở bến cuối.", "bad": ["连我觉得也我的母亲会在终点站等着我。", "我连也觉得我的母亲会在终点站等着我。"]}, {"s": "越来越", "d": "Ngày càng…; không thêm 很 phía sau.", "ok": "他们的盘问越来越厉害了。", "vi": "Họ tra hỏi ngày càng gắt.", "bad": ["他们的盘问越来越很厉害了。", "他们的盘问越越来厉害了。"]}, {"s": "V + 着", "d": "Trạng thái đang tiếp diễn.", "ok": "外边下着细细的雨。", "vi": "Ngoài trời đang mưa lất phất.", "bad": ["外边下细细的着雨。", "外边着下细细的雨。"]}], "disc": [{"q": "你童年时心中的英雄是谁？为什么？", "py": "Nǐ tóngnián shí xīnzhōng de yīngxióng shì shuí? Wèishénme?", "vi": "Người hùng thời thơ ấu của bạn là ai? Vì sao?", "keys": ["除了……以外", "由于|因为", "仍然|还是"], "sample": "除了父母以外，我童年时心中的英雄是我的小学老师。由于她对学生非常认真，我小时候想当老师。现在我仍然很佩服她。", "spy": "Chúle fùmǔ yǐwài, wǒ tóngnián shí xīnzhōng de yīngxióng shì wǒ de xiǎoxuélǎoshī. Yóuyú tā duì xuéshēng fēicháng rènzhēn, wǒ xiǎoshíhòu xiǎngdāng lǎoshī. Xiànzài wǒ réngrán hěn pèifú tā."}], "comp": [{"vi": "Ngay cả tôi cũng không tin. (连……也……)", "keys": ["连", "也|都"], "model": "连我也不相信。", "mpy": "Lián wǒ yě bù xiāngxìn."}, {"vi": "Vì trời mưa, trận đấu bị hoãn. (由于)", "keys": ["由于"], "model": "由于下雨，比赛推迟了。", "mpy": "Yóuyú xiàyǔ, bǐsài tuīchí le."}, {"vi": "Ngoài tiếng Anh ra, tôi còn học tiếng Trung. (除了……以外)", "keys": ["除了", "以外|之外"], "model": "除了英语以外，我还学汉语。", "mpy": "Chúle yīngyǔ yǐwài, wǒ háixué hànyǔ."}], "ex": [{"q": "六岁那年，作者在公共汽车上看到了什么？", "qvi": "Năm sáu tuổi, tác giả thấy gì trên xe buýt?", "a": "河、绿油油的山野和成百上千只奶牛。", "avi": "Sông, đồi núi xanh mướt và hàng trăm hàng nghìn con bò sữa.", "bad": ["高楼和地铁。", "大海和沙滩。"], "p": 1}, {"q": "作者为什么每天去坐公共汽车？", "qvi": "Vì sao ngày nào tác giả cũng đi xe buýt?", "a": "他迷上了坐车，而且6岁以下坐车免费。", "avi": "Cậu mê đi xe và trẻ dưới 6 tuổi được miễn phí.", "bad": ["他要去幼儿园上课。", "妈妈让他去买东西。"], "p": 2}, {"q": "佐藤先生是一个什么样的司机？", "qvi": "Ông Sato là tài xế như thế nào?", "a": "穿着整齐，对自己的工作很骄傲。", "avi": "Ăn mặc chỉnh tề, tự hào về công việc.", "bad": ["很爱跟乘客聊天。", "常常迟到。"], "p": 3}, {"q": "大人们盘问作者时，佐藤先生怎么做？", "qvi": "Khi người lớn tra hỏi, ông Sato làm gì?", "a": "他说认识作者的父母，母亲在终点站接他。", "avi": "Ông nói quen bố mẹ cậu, mẹ đón ở bến cuối.", "bad": ["他让作者马上下车。", "他给作者的妈妈打电话。"], "p": 4}, {"q": "作者后来的梦想变成了什么？", "qvi": "Ước mơ sau này của tác giả là gì?", "a": "当公共汽车司机。", "avi": "Làm tài xế xe buýt.", "bad": ["当宇航员。", "当律师。"], "p": 5}, {"q": "现在作者最佩服佐藤先生什么？", "qvi": "Giờ tác giả khâm phục ông Sato điều gì nhất?", "a": "他对工作认真的态度。", "avi": "Thái độ làm việc nghiêm túc.", "bad": ["他的司机帽。", "他开车开得很快。"], "p": 6}]}}];
  Object.assign(C.book.lessons, {"hk3-l1": {"page": "—", "src": "发展汉语 · 高级口语（3）· 第1课", "kw": [{"h": "课文一 快乐也会传染", "lines": [["", "说到“传染”，很多人不禁会皱起眉头，因为“传染”通常是和“病毒”联系在一起的。我们知道很多事物都会近距离传染，比如感冒、水痘、打哈欠。那么幸福、快乐也会传染吗？", "Shuō dào “Chuánrǎn”, hěnduō rén bùjīn huì zhòuqǐ méitóu, yīnwèi “Chuánrǎn” tōngcháng shì hé “Bìngdú” liánxì zài yìqǐ de. Wǒmen zhīdao hěnduō shìwù dōu huì jìnjùlí chuánrǎn, bǐrú gǎnmào, shuǐdòu, dǎhāqiàn. Nàme xìngfú, kuàilè yě huì chuánrǎn ma?", "Nói đến \"lây lan\", rất nhiều người không khỏi cau mày, bởi vì \"lây lan\" thường được liên hệ với \"vi-rút\". Chúng ta biết rất nhiều sự vật đều có thể lây lan ở khoảng cách gần, ví dụ như cảm cúm, thủy đậu, ngáp. Vậy hạnh phúc, niềm vui cũng có thể lây lan ư?"], ["", "研究人员在《英国医学期刊》上发表的研究报告中称，与快乐的人在一起，你自己也会更快乐。你周围的人越快乐，你也会越快乐。专家说：“这是一个情绪感染的问题。”", "Yánjiū rényuán zài «Yīngguó yīxuéqīkān» shàng fābiǎo de yánjiū bàogào zhōngchēng, yǔ kuàilè de rén zài yìqǐ, nǐ zìjǐ yě huì gèng kuàilè. Nǐ zhōuwéi de rén yuè kuàilè, nǐ yě huì yuè kuàilè. Zhuānjiā shuō: “Zhèshì yíge qíngxù gǎnrǎn de wèntí.”", "Các nhà nghiên cứu cho biết trong báo cáo đăng trên Tạp chí Y học Anh rằng, ở cùng với người vui vẻ, bản thân bạn cũng sẽ vui vẻ hơn. Những người xung quanh bạn càng vui vẻ, bạn cũng sẽ càng vui vẻ. Chuyên gia nói: \"Đây là vấn đề cảm xúc bị lây nhiễm.\""], ["", "调查数据显示，社会关系最广泛的人同时也最快乐，这些人与朋友、配偶、邻居和亲戚的联系都较为密切。专家说：“你身边多一个快乐的人，你就多一份快乐。”", "Diàochá shùjù xiǎnshì, shèhuìguānxì zuì guǎngfàn de rén tóngshí yě zuì kuàilè, zhèxiē rén yǔ péngyou, pèiǒu, línjū hé qīnqi de liánxì dōu jiàowéi mìqiè. Zhuānjiā shuō: “Nǐ shēnbiān duō yíge kuàilè de rén, nǐ jiù duōyífèn kuàilè.”", "Số liệu điều tra cho thấy, những người có quan hệ xã hội rộng rãi nhất đồng thời cũng là những người vui vẻ nhất, họ có mối liên hệ khá mật thiết với bạn bè, vợ/chồng, hàng xóm và họ hàng. Chuyên gia nói: \"Bên cạnh bạn có thêm một người vui vẻ, bạn sẽ có thêm một phần niềm vui.\""], ["", "研究人员还发现，快乐比不快乐更易“传染”。如果你的直接社交对象很快乐，你快乐的几率会增加15%。如果你配偶或兄弟姐妹的朋友很快乐，你快乐的几率就会增加10%。如果你的第三层社交圈，如朋友的朋友很快乐，那么你快乐的几率会增加6%。但每多一个不快乐的朋友，你不快乐的几率会增加7%。", "Yánjiū rényuán hái fāxiàn, kuàilè bǐ bú kuàilè gèng yì “Chuánrǎn”. Rúguǒ nǐ de zhíjiē shèjiāo duìxiàng hěn kuàilè, nǐ kuàilè de jīlǜ huì zēngjiā15%. Rúguǒ nǐ pèiǒu huò xiōngdìjiěmèi de péngyou hěn kuàilè, nǐ kuàilè de jīlǜ jiù huì zēngjiā10%. Rúguǒ nǐ de dìsāncéng shèjiāoquān, rú péngyou de péngyou hěn kuàilè, nàme nǐ kuàilè de jīlǜ huì zēngjiā6%. Dàn měi duō yíge bú kuàilè de péngyou, nǐ bú kuàilè de jīlǜ huì zēngjiā7%.", "Các nhà nghiên cứu còn phát hiện, niềm vui dễ \"lây\" hơn sự không vui. Nếu đối tượng giao tiếp trực tiếp của bạn rất vui vẻ, khả năng bạn vui vẻ tăng 15%. Nếu bạn của vợ/chồng hoặc anh chị em bạn rất vui vẻ, khả năng ấy tăng 10%. Nếu vòng giao tiếp thứ ba, như bạn của bạn, rất vui vẻ, khả năng tăng 6%. Nhưng mỗi khi có thêm một người bạn không vui, khả năng bạn không vui tăng 7%."], ["", "这项新公布的研究结果显示，幸福可能会通过社交网络扩散，你交往的人越幸福，你也会感到越快乐。如果你的社交网络，比如朋友、家庭和配偶，他们中有人变得快乐，那也会增加你快乐的可能性。", "Zhèxiàng xīn gōngbù de yánjiū jiéguǒxiǎnshì, xìngfú kěnéng huì tōngguò shèjiāo wǎngluò kuòsàn, nǐ jiāowǎng de rén yuè xìngfú, nǐ yě huì gǎndào yuè kuàilè. Rúguǒ nǐ de shèjiāo wǎngluò, bǐrú péngyou, jiātíng hé pèiǒu, tāmen zhōng yǒurén biànde kuàilè, nà yě huì zēngjiā nǐ kuàilè de kěnéngxìng.", "Kết quả nghiên cứu mới công bố này cho thấy, hạnh phúc có thể lan tỏa qua mạng lưới xã hội; người bạn giao tiếp càng hạnh phúc, bạn càng cảm thấy vui vẻ. Nếu trong mạng lưới xã hội của bạn, như bạn bè, gia đình và vợ/chồng, có ai đó trở nên vui vẻ, điều đó cũng làm tăng khả năng bạn vui vẻ."]]}, {"h": "课文二 快乐需要分享", "lines": [["", "有一个故事，说一位犹太教的长老，酷爱打高尔夫球。在一个安息日，他觉得手痒，很想去挥挥杆，但犹太教规定，教徒在安息日必须休息，什么事都不能做。", "Yǒu yíge gùshi, shuō yíwèi yóutàijiào de zhǎnglǎo, kùài dǎ gāoěrfūqiú. Zài yíge ānxīrì, tā juéde shǒuyǎng, hěn xiǎng qù huī huīgān, dàn yóutàijiào guīdìng, jiàotú zài ānxīrì bìxū xiūxi, shénme shì dōu bùnéng zuò.", "Có một câu chuyện kể rằng, một vị trưởng lão Do Thái giáo rất mê đánh gôn. Vào một ngày Sabbath, ông thấy ngứa tay, rất muốn đi vung vài gậy, nhưng Do Thái giáo quy định tín đồ ngày Sabbath phải nghỉ ngơi, việc gì cũng không được làm."], ["", "这位长老却怎么也忍不住，决定偷偷去高尔夫球场，想着打九个洞就好了。", "Zhèwèi zhǎnglǎo què zěnme yě rěnbúzhù, juédìng tōutōu qù gāo ěr fū qiú chǎng, xiǎngzhe dǎ jiǔge dòng jiù hǎo le.", "Vị trưởng lão này lại không sao nhịn được, quyết định lén đến sân gôn, nghĩ bụng chỉ đánh chín lỗ là được."], ["", "由于安息日犹太教徒都不会出门，球场上一个人也没有，因此长老觉得不会有人知道他违反规定。", "Yóuyú ānxīrì yóutàijiàotú dōu búhuì chūmén, qiúchǎngshàng yíge rén yě méiyǒu, yīncǐ zhǎnglǎo juéde búhuì yǒurén zhīdao tā wéifǎnguīdìng.", "Vì ngày Sabbath tín đồ Do Thái đều không ra ngoài, trên sân không có một bóng người, nên trưởng lão nghĩ sẽ không ai biết ông vi phạm quy định."], ["", "然而，当长老在打第二洞时，却被天使发现了，天使生气地到上帝面前告状，说某某长老不守教义，居然在安息日出门打高尔夫球。", "Ránér, dāng zhǎnglǎo zài dǎ dìèr dòngshí, què bèi tiānshǐ fāxiàn le, tiānshǐ shēngqì dìdào shàngdì miànqián gàozhuàng, shuō mǒumǒu zhǎnglǎo bù shǒu jiàoyì, jūrán zài ānxīrì chūmén dǎ gāoěrfūqiú.", "Thế nhưng, khi trưởng lão đang đánh lỗ thứ hai thì bị thiên sứ phát hiện. Thiên sứ tức giận đến trước mặt Thượng đế mách tội, nói trưởng lão nọ không giữ giáo lý, dám ra ngoài đánh gôn vào ngày Sabbath."], ["", "上帝听了，就跟天使说，会好好惩罚这个长老。", "Shàngdì tīng le, jiù gēn tiānshǐ shuō, huì hǎohǎo chéngfá zhège zhǎnglǎo.", "Thượng đế nghe xong liền nói với thiên sứ rằng sẽ trừng phạt thật nặng vị trưởng lão này."], ["", "第三个洞开始，长老打出超完美的成绩，几乎都是一杆进洞。", "Dìsānge dòng kāishǐ, zhǎnglǎo dǎchū chāo wánměi de chéngjì, jīhū dōu shì yìgān jìndòng.", "Từ lỗ thứ ba, trưởng lão đánh ra thành tích siêu hoàn hảo, gần như toàn là một gậy vào lỗ."], ["", "长老兴奋坏了，到打第七个洞时，天使又跑去找上帝，\"上帝呀，您不是说要惩罚长老吗？为什么还不见有惩罚？\"", "Zhǎnglǎo xīngfèn huài le, dào dǎ dìqīge dòngshí, tiānshǐ yòu pǎo qù zhǎo shàngdì, \" shàngdì ya, nín búshì shuō yào chéngfá zhǎnglǎo ma? Wèishénme hái bújiàn yǒu chéngfá? \"", "Trưởng lão phấn khích vô cùng. Đến lỗ thứ bảy, thiên sứ lại chạy đi tìm Thượng đế: \"Thượng đế ơi, chẳng phải Ngài nói sẽ trừng phạt trưởng lão sao? Sao vẫn chưa thấy trừng phạt gì?\""], ["", "上帝说：\"我已经在惩罚他了。\"", "Shàngdì shuō: \" wǒ yǐjīng zài chéngfá tā le. \"", "Thượng đế nói: \"Ta đang trừng phạt ông ấy rồi.\""], ["", "直到打完第九个洞，长老都是一杆进洞。因为打得太神了，于是长老决定再打九个洞。", "Zhídào dǎ wán dìjiǔge dòng, zhǎnglǎo dōu shì yìgān jìndòng. Yīnwèi dǎ de tàishén le, yúshì zhǎnglǎo juédìng zài dǎ jiǔge dòng.", "Cho đến khi đánh xong lỗ thứ chín, trưởng lão vẫn toàn một gậy vào lỗ. Vì đánh hay như thần, trưởng lão quyết định đánh thêm chín lỗ nữa."], ["", "天使又去找上帝了，\"您说要惩罚他，惩罚到底在哪里？\"", "Tiānshǐ yòu qù zhǎo shàngdì le, \" nín shuō yào chéngfá tā, chéngfá dàodǐ zài nǎlǐ? \"", "Thiên sứ lại đi tìm Thượng đế: \"Ngài nói sẽ trừng phạt ông ấy, rốt cuộc trừng phạt ở đâu?\""], ["", "上帝只是笑而不答。", "Shàngdì zhǐshì xiàoérbùdá.", "Thượng đế chỉ cười mà không đáp."], ["", "打完十八洞，成绩比任何一位世界级的高尔夫球手都优秀，这可把长老乐坏了。", "Dǎ wán shíbā dòng, chéngjì bǐ rènhé yíwèi shìjièjí de gāoěrfūqiú shǒu dōu yōuxiù, zhè kě bǎ zhǎnglǎo lèhuàile.", "Đánh xong mười tám lỗ, thành tích còn xuất sắc hơn bất kỳ tay gôn đẳng cấp thế giới nào, điều này khiến trưởng lão sướng phát điên."], ["", "天使很生气地问上帝：\"这就是您对长老的惩罚吗？\"", "Tiānshǐ hěn shēngqì dìwèn shàngdì: \" zhè jiùshì nín duì zhǎnglǎo de chéngfá ma? \"", "Thiên sứ rất tức giận hỏi Thượng đế: \"Đây chính là hình phạt Ngài dành cho trưởng lão sao?\""], ["", "上帝说：\"正是，你想想，他有这么惊人的成绩以及兴奋的心情，却不能跟任何人说，这不是最好的惩罚吗？\"", "Shàngdì shuō: \" zhèngshì, nǐ xiǎngxiang, tā yǒu zhème jīngrén de chéngjì yǐjí xīngfèn de xīnqíng, què bùnéng gēn rènhérén shuō, zhè búshì zuìhǎo de chéngfá ma? \"", "Thượng đế nói: \"Đúng vậy. Ngươi thử nghĩ xem, ông ấy có thành tích kinh người và tâm trạng phấn khích như thế, lại không thể kể với bất kỳ ai, đó chẳng phải là hình phạt tốt nhất sao?\""], ["", "生活需要伴侣，快乐和痛苦都要有人分享。没有人分享的人生，无论面对的是快乐还是痛苦，都是一种惩罚。", "Shēnghuó xūyào bànlǚ, kuàilè hé tòngkǔ dōu yào yǒurén fēnxiǎng. Méiyǒu rén fēnxiǎng de rénshēng, wúlùn miànduì de shì kuàilè háishì tòngkǔ, dōu shì yìzhǒng chéngfá.", "Cuộc sống cần bạn đồng hành, niềm vui và nỗi đau đều cần có người chia sẻ. Một cuộc đời không có ai chia sẻ, dù đối mặt với niềm vui hay nỗi đau, đều là một sự trừng phạt."]]}], "fn": [["越……越……", "", "A 越 + tính từ, B 越 + tính từ: hai sự việc cùng tăng. Sau 越 không thêm 很.", "你周围的人越快乐，你也会越快乐。"], ["无论……还是……都……", "", "Bất kể A hay B đều…; vế sau dùng 都 (không dùng 就).", "无论面对的是快乐还是痛苦，都需要有人分享。"], ["居然", "", "Không ngờ lại… (điều trái với dự đoán). Là phó từ, đứng trước động từ.", "他居然在安息日出门打高尔夫球。"], ["不是……吗？(câu hỏi tu từ)", "", "Dùng để khẳng định mạnh: “chẳng phải… sao?”.", "这不是最好的惩罚吗？"], ["通过 + N", "", "Thông qua cái gì để đạt kết quả.", "幸福可能会通过社交网络扩散。"]], "adv": [["分享", "fēnxiǎng", "chia sẻ"], ["故事", "gùshi", "câu chuyện"], ["犹太教", "Yóutàijiào", "đạo Do Thái (Do Thái giáo)"], ["长老", "zhǎnglǎo", "trưởng lão"], ["酷爱", "kù'ài", "rất yêu thích, say mê"], ["高尔夫球", "gāo'ěrfūqiú", "bóng gôn"], ["安息日", "ānxīrì", "ngày Sabbath (ngày nghỉ trong Do Thái giáo)"], ["手痒", "shǒu yǎng", "ngứa tay (muốn làm gì đó)"], ["挥杆", "huī gān", "vung gậy (đánh gôn)"], ["规定", "guīdìng", "quy định"], ["教徒", "jiàotú", "tín đồ"], ["忍不住", "rěnbùzhù", "không nhịn được, không kìm được"], ["偷偷", "tōutōu", "lén lút"], ["球场", "qiúchǎng", "sân bóng, sân gôn"], ["洞", "dòng", "lỗ (gôn)"], ["违反", "wéifǎn", "vi phạm"], ["天使", "tiānshǐ", "thiên sứ"], ["上帝", "Shàngdì", "Thượng đế, Chúa"], ["告状", "gàozhuàng", "mách tội, tố cáo"], ["教义", "jiàoyì", "giáo nghĩa, giáo lý"], ["居然", "jūrán", "vậy mà, không ngờ lại"], ["惩罚", "chéngfá", "trừng phạt"], ["完美", "wánměi", "hoàn mỹ, hoàn hảo"], ["成绩", "chéngjī", "thành tích"], ["一杆进洞", "yī gān jìn dòng", "một gậy vào lỗ (hole in one)"], ["兴奋", "xīngfèn", "hưng phấn, phấn khích"], ["神", "shén", "thần kỳ, xuất sắc"], ["于是", "yúshì", "vì vậy, thế là"], ["笑而不答", "xiào ér bù dá", "cười mà không đáp"], ["优秀", "yōuxiù", "ưu tú, xuất sắc"], ["乐坏了", "lè huài le", "vui sướng phát điên"], ["惊人", "jīngrén", "kinh người, đáng kinh ngạc"], ["以及", "yǐjí", "cũng như, và"], ["心情", "xīnqíng", "tâm trạng, cảm xúc"], ["伴侣", "bànlǚ", "bạn đồng hành, người bạn đời"], ["痛苦", "tòngkǔ", "đau khổ"], ["人生", "rénshēng", "cuộc đời, nhân sinh"], ["无论", "wúlùn", "bất luận, bất kể"], ["面对", "miànduì", "đối mặt, đứng trước"]], "ex2": [["说到“传染”，人们为什么会皱起眉头？", "因为“传染”通常和“病毒”联系在一起。", ["因为快乐不会传染。", "因为打哈欠很不礼貌。"]], ["根据研究报告，怎样你会更快乐？", "和快乐的人在一起。", ["一个人安静地生活。", "多看医学期刊。"]], ["什么样的人最快乐？", "社会关系最广泛的人。", ["收入最高的人。", "朋友最少的人。"]], ["如果你的直接社交对象很快乐，你快乐的几率会增加多少？", "增加15%。", ["增加10%。", "增加6%。"]], ["研究结果显示，幸福可能会通过什么扩散？", "通过社交网络扩散。", ["通过病毒扩散。", "通过医学期刊扩散。"]], ["上帝对长老的惩罚是什么？", "让他打出惊人的成绩，却不能跟任何人说。", ["让他一个洞也打不进。", "不让他再打高尔夫球。"]]]}, "hk3-l2": {"page": "—", "src": "发展汉语 · 高级读写（3）· 第1课", "kw": [{"h": "课文 休闲与游戏", "lines": [["", "如今，“休闲”已成为我们每个人生活中的重要内容。从社会发展的规律看，社会文明程度越高，休闲时间就越多。休闲的价值不言而喻，没有休闲活动，人的自然成长都会出现问题。", "Rújīn, “Xiūxián” yǐ chéngwéi wǒmen měige rén shēnghuó zhōng de zhòngyào nèiróng. Cóng shèhuì fāzhǎn de guīlǜ kàn, shèhuì wénmíng chéngdù yuègāo, xiūxián shíjiān jiù yuè duō. Xiūxián de jiàzhí bùyánéryù, méiyǒu xiūxiánhuódòng, rén de zìrán chéngzhǎng dōu huì chūxiàn wèntí.", "Ngày nay, \"nghỉ ngơi giải trí\" đã trở thành nội dung quan trọng trong cuộc sống của mỗi chúng ta. Xét theo quy luật phát triển xã hội, trình độ văn minh càng cao thì thời gian nhàn rỗi càng nhiều. Giá trị của giải trí là điều không cần nói cũng rõ; không có hoạt động giải trí, ngay cả sự trưởng thành tự nhiên của con người cũng sẽ gặp vấn đề."], ["", "中国的文化传统是强调休闲的，人的心灵要保持清净，如果承担的工作太多，心灵就会疲惫。因为人一忙就容易乱，头脑不清醒；心情不能平和，不能冷静认真地思考；人一忙就容易目光短浅，不能高瞻远瞩。对现代人来讲，休闲尤其重要。", "Zhōngguó de wénhuà chuántǒng shì qiángdiào xiūxián de, rén de xīnlíng yào bǎochí qīngjìng, rúguǒ chéngdān de gōngzuò tài duō, xīnlíng jiù huì píbèi. Yīnwèi rényìmáng jiù róngyì luàn, tóunǎo bù qīngxǐng; xīnqíng bùnéng pínghé, bùnéng lěngjìng rènzhēn dì sīkǎo; rényìmáng jiù róngyì mùguāngduǎnqiǎn, bùnéng gāozhānyuǎnzhǔ. Duì xiàndàirén láijiǎng, xiūxián yóuqí zhòngyào.", "Truyền thống văn hóa Trung Quốc coi trọng sự thư nhàn: tâm hồn cần giữ thanh tịnh, nếu gánh vác quá nhiều việc, tâm hồn sẽ mệt mỏi. Vì người ta hễ bận là dễ rối, đầu óc không tỉnh táo; tâm trạng không bình hòa, không thể suy nghĩ bình tĩnh, nghiêm túc; hễ bận là dễ có tầm nhìn hạn hẹp, không thể nhìn xa trông rộng. Đối với người hiện đại, giải trí càng đặc biệt quan trọng."], ["", "游戏在人的成长过程中有着重要的作用：一是人的生活中不能没有游戏，二是游戏是创造的基础，三是游戏是人的学习课堂，四是游戏培养人的智慧，五是游戏可以锻炼人的勇气。可以说，玩是人生的根本需要之一。我这里的玩，指的是积极、健康、友好、多样性的游戏种类，包括静态的、动态的、益智的、健身的、简单的、复杂的，舒缓的、激烈的，户内的、户外的，等等。", "Yóuxì zài rén de chéngzhǎng guòchéng zhōng yǒuzhe zhòngyào de zuòyòng: Yíshì rén de shēnghuó zhōng bùnéng méiyǒu yóuxì, èrshì yóuxì shì chuàngzào de jīchǔ, sānshì yóuxì shì rén de xuéxí kètáng, sìshì yóuxì péiyǎng rén de zhìhuì, wǔshì yóuxì kěyǐ duànliàn rén de yǒngqì. Kěyǐ shuō, wán shì rénshēng de gēnběn xūyào zhīyī. Wǒ zhèlǐ de wán, zhǐ de shì jījí, jiànkāng, yǒuhǎo, duōyàngxìng de yóuxì zhǒnglèi, bāokuò jìngtài de, dòngtài de, yìzhì de, jiànshēn de, jiǎndān de, fùzá de, shūhuǎn de, jīliè de, hùnèi de, hùwài de, děngděng.", "Trò chơi có vai trò quan trọng trong quá trình trưởng thành: một là đời sống không thể thiếu trò chơi, hai là trò chơi là nền tảng của sáng tạo, ba là trò chơi là lớp học của con người, bốn là trò chơi bồi dưỡng trí tuệ, năm là trò chơi rèn luyện lòng dũng cảm. Có thể nói, chơi là một trong những nhu cầu căn bản của đời người. \"Chơi\" ở đây là các loại trò chơi tích cực, lành mạnh, thân thiện, đa dạng: tĩnh và động, rèn trí và rèn thân, đơn giản và phức tạp, nhẹ nhàng và sôi nổi, trong nhà và ngoài trời…"], ["", "鲁迅曾说过：游戏是儿童最正当的行为。因为玩能教人许多道理，能展开他们想象的翅膀，激发他们的兴趣，发现他们的爱好，培养他们的专长。当然，有人会玩物丧志，那不是游戏的错，而是游戏者没有掌握好“度”。如果玩过了头，那是家长或学校没有指导好。", "Lǔxùn céng shuō guò: Yóuxì shì értóng zuì zhèngdāng de xíngwéi. Yīnwèi wánnéng jiàorén xǔduō dàolǐ, néng zhǎnkāi tāmen xiǎngxiàng de chìbǎng, jīfā tāmen de xìngqù, fāxiàn tāmen de àihào, péiyǎng tāmen de zhuāncháng. Dāngrán, yǒurén huì wánwùsàngzhì, nà búshì yóuxì de cuò, érshì yóuxì zhě méiyǒu zhǎngwò hǎo “Dù”. Rúguǒ wánguò le tóu, nà shì jiāzhǎng huò xuéxiào méiyǒu zhǐdǎo hǎo.", "Lỗ Tấn từng nói: trò chơi là hành vi chính đáng nhất của trẻ em. Vì chơi dạy người ta nhiều đạo lý, chắp cánh trí tưởng tượng, khơi dậy hứng thú, giúp phát hiện sở thích và bồi dưỡng sở trường. Đương nhiên, có người ham chơi mà mất ý chí, nhưng đó không phải lỗi của trò chơi, mà là người chơi chưa nắm vững \"chừng mực\". Nếu chơi quá đà, đó là do phụ huynh hoặc nhà trường chưa hướng dẫn tốt."], ["", "休闲时间是人们用来放松、思考、欣赏、创造的。一些传统的游戏，比如麻将，在中国已流行了几百年，是人们喜闻乐见的游戏。但是，麻将在中国有“异化”的趋势，有些人把它变成了赌博工具。有人把赌博现象归罪于麻将，显然是人的智慧出了问题，是人在逃避责任。我们对这种文化产物，有责任爱护它，让它在人们休闲活动中健康地发挥效用。", "Xiūxián shíjiān shì rénmen yònglái fàngsōng, sīkǎo, xīnshǎng, chuàngzào de. Yìxiē chuántǒng de yóuxì, bǐrú májiāng, zài zhōngguó yǐ liúxíng le jǐbǎinián, shì rénmen xǐwénlèjiàn de yóuxì. Dànshì, májiāng zài zhōngguó yǒu “Yìhuà” de qūshì, yǒuxiē rén bǎ tā biànchéng le dǔbó gōngjù. Yǒurén bǎ dǔbó xiànxiàng guīzuìyú májiāng, xiǎnrán shì rén de zhìhuì chū le wèntí, shì rén zài táobìzérèn. Wǒmen duì zhèzhǒng wénhuà chǎnwù, yǒu zérèn àihù tā, ràng tā zài rénmen xiūxiánhuódòng zhōng jiànkāng dì fāhuī xiàoyòng.", "Thời gian nhàn rỗi là để con người thư giãn, suy ngẫm, thưởng thức và sáng tạo. Một số trò chơi truyền thống như mạt chược đã thịnh hành ở Trung Quốc mấy trăm năm, được mọi người ưa chuộng. Thế nhưng mạt chược có xu hướng bị \"biến chất\", có người biến nó thành công cụ cờ bạc. Có người đổ tội cờ bạc cho mạt chược – rõ ràng là trí tuệ con người có vấn đề, là con người đang trốn tránh trách nhiệm. Với sản phẩm văn hóa này, chúng ta có trách nhiệm gìn giữ, để nó phát huy tác dụng lành mạnh trong đời sống giải trí."], ["", "休闲，游戏使我们的生活丰富多彩。近些年来，人们越来越远离休闲和游戏，尤其是孩子们玩的时间太少，成年人和老年人可选择的玩种类也不多。我十几年前就关注这个问题，也多次谈到中国的大学应该有一门游戏理论课程。休闲时间越多，如何休闲的问题就越重要。从个人方面看，如何用好时间，使生活更愉快、更充实的问题；从社会方面看，如何帮助和引导人们支配好空闲时间的问题。", "Xiūxián, yóuxì shǐ wǒmen de shēnghuó fēngfùduōcǎi. Jìnxiēniánlái, rénmen yuèláiyuè yuǎnlí xiūxián hé yóuxì, yóuqí shì háizi men wán de shíjiān tài shǎo, chéngniánrén hé lǎoniánrén kě xuǎnzé de wán zhǒnglèi yě bù duō. Wǒ shíjǐnián qián jiù guānzhù zhège wèntí, yě duōcì tándào zhōngguó de dàxué yīnggāi yǒu yìmén yóuxì lǐlùn kèchéng. Xiūxián shíjiān yuè duō, rúhé xiūxián de wèntí jiù yuè zhòngyào. Cóng gerén fāngmiàn kàn, rúhé yòng hǎo shíjiān, shǐ shēnghuó gèng yúkuài, gèng chōngshí de wèntí; cóng shèhuì fāngmiàn kàn, rúhé bāngzhù hé yǐndǎo rénmen zhīpèi hǎo kòngxián shíjiān de wèntí.", "Giải trí và trò chơi làm cuộc sống phong phú, nhiều màu sắc. Những năm gần đây, con người ngày càng xa rời giải trí và trò chơi, nhất là trẻ em có quá ít thời gian chơi, người lớn và người già cũng ít loại hình vui chơi để chọn. Từ mười mấy năm trước tôi đã quan tâm vấn đề này, nhiều lần nói các trường đại học Trung Quốc nên có môn lý luận trò chơi. Thời gian nhàn rỗi càng nhiều, vấn đề giải trí thế nào càng quan trọng: về cá nhân, là làm sao dùng tốt thời gian để sống vui và đầy đặn hơn; về xã hội, là làm sao giúp và hướng dẫn mọi người sắp xếp tốt thời gian rảnh."]]}], "fn": [["一……就……", "", "Hễ… là…: điều kiện dẫn tới kết quả ngay.", "人一忙就容易乱。"], ["不是……而是……", "", "Phủ định A, khẳng định B.", "那不是游戏的错，而是游戏者没有掌握好“度”。"], ["对……来讲 / 来说", "", "Đối với… mà nói.", "对现代人来讲，休闲尤其重要。"], ["把 + A + 归罪于 + B", "", "Đổ tội A cho B (câu 把).", "有人把赌博现象归罪于麻将。"], ["从……方面看", "", "Xét từ phương diện….", "从个人方面看，如何用好时间很重要。"]], "adv": [["智慧", "zhìhuì", "trí tuệ"], ["锻炼", "duànliàn", "rèn luyện"], ["勇气", "yǒngqì", "dũng khí"], ["根本", "gēnběn", "căn bản"], ["需要", "xūyào", "nhu cầu"], ["积极", "jījí", "tích cực"], ["健康", "jiànkāng", "khỏe mạnh, lành mạnh"], ["友好", "yǒuhǎo", "thân thiện"], ["多样性", "duōyàngxìng", "tính đa dạng"], ["种类", "zhǒnglèi", "loại, chủng loại"], ["静态", "jìngtài", "trạng thái tĩnh"], ["动态", "dòngtài", "trạng thái động"], ["益智", "yìzhì", "ích trí, bổ ích cho trí não"], ["健身", "jiànshēn", "rèn luyện sức khỏe"], ["简单", "jiǎndān", "đơn giản"], ["复杂", "fùzá", "phức tạp"], ["舒缓", "shūhuǎn", "thư thái, nhẹ nhàng"], ["激烈", "jīliè", "kịch liệt, mãnh liệt"], ["户外", "hùwài", "ngoài trời"], ["正当", "zhèngdàng", "chính đáng"], ["行为", "xíngwéi", "hành vi"], ["道理", "dàolǐ", "đạo lý, lẽ phải"], ["展开", "zhǎnkāi", "mở ra, triển khai"], ["想象", "xiǎngxiàng", "tưởng tượng"], ["翅膀", "chìbǎng", "đôi cánh"], ["激发", "jīfā", "kích thích, khơi dậy"], ["兴趣", "xìngqù", "hứng thú"], ["爱好", "àihào", "sở thích"], ["专长", "zhuāncháng", "chuyên môn, sở trường"], ["玩物丧志", "wánwùsàngzhì", "chơi vật mất chí (mê chơi mất chí hướng)"], ["掌握", "zhǎngwò", "nắm vững, kiểm soát"], ["度", "dù", "mức độ"], ["家长", "jiāzhǎng", "phụ huynh"], ["指导", "zhǐdǎo", "chỉ đạo, hướng dẫn"], ["放松", "fàngsōng", "thư giãn"], ["欣赏", "xīnshǎng", "thưởng thức"], ["创造", "chuàngzào", "sáng tạo"], ["传统", "chuántǒng", "truyền thống"], ["流行", "liúxíng", "lưu hành, thịnh hành"], ["喜闻乐见", "xǐwénlèjiàn", "ưa thích, hoan nghênh"], ["异化", "yìhuà", "dị hóa"], ["趋势", "qūshì", "xu hướng"], ["赌博", "dǔbó", "cờ bạc"], ["工具", "gōngjù", "công cụ"], ["现象", "xiànxiàng", "hiện tượng"], ["归罪", "guīzuì", "quy tội, đổ tội"], ["显然", "xiǎnrán", "hiển nhiên, rõ ràng"], ["逃避", "táobì", "trốn tránh"], ["责任", "zérèn", "trách nhiệm"], ["产物", "chǎnwù", "sản phẩm"], ["爱护", "àihù", "yêu quý, bảo vệ"], ["效用", "xiàoyòng", "hiệu dụng, tác dụng"], ["丰富", "fēngfù", "phong phú"], ["多彩", "duōcǎi", "nhiều màu sắc, đa dạng"], ["远离", "yuǎnlí", "xa rời"], ["尤其", "yóuqí", "đặc biệt"], ["成年", "chéngnián", "trưởng thành"], ["老年", "lǎonián", "tuổi già"], ["选择", "xuǎnzé", "lựa chọn"], ["关注", "guānzhù", "quan tâm"]], "ex2": [["作者认为社会文明程度和休闲时间有什么关系？", "社会文明程度越高，休闲时间就越多。", ["社会越发达，人越没有时间休闲。", "两者没有关系。"]], ["为什么说人太忙不好？", "人一忙就容易乱，目光短浅。", ["人一忙就有更多休闲时间。", "人一忙就更有智慧。"]], ["作者说的“玩”指的是什么？", "积极、健康、友好、多样性的游戏。", ["只是户外运动。", "打麻将赌博。"]], ["有人玩物丧志，作者认为是谁的错？", "不是游戏的错，而是游戏者没掌握好“度”。", ["是游戏本身的错。", "是鲁迅的错。"]], ["作者怎么看把赌博归罪于麻将？", "那是人在逃避责任。", ["麻将应该被禁止。", "麻将本来就是赌博工具。"]], ["作者建议中国的大学应该怎么做？", "开一门游戏理论课程。", ["取消学生的休闲时间。", "让学生多打麻将。"]]]}, "hk3-l3": {"page": "—", "src": "发展汉语 · 高级读写（3）· 第2课", "kw": [{"h": "课文", "lines": [["", "我在一家车行找到一份汽车销售的工作。但几天下来，还没卖出一部车，而那个小个子的孙明却做成了好几笔业务。我开始观察他，看他是怎样接待顾客的。", "Wǒ zài yìjiā chēháng zhǎodào yífèn qìchē xiāoshòu de gōngzuò. Dàn jǐtiān xiàlái, hái méi màichū yíbù chē, ér nàge xiǎogezi de Sūn Míng què zuòchéng le hǎo jǐbǐ yèwù. Wǒ kāishǐ guānchá tā, kàn tā shì zěnyàng jiēdài gùkè de.", "Đoạn 1: Tôi tìm được công việc bán ô tô tại một cửa hàng xe. Mấy ngày trời trôi qua, vẫn chưa bán được chiếc nào, vậy mà anh Tôn Minh người nhỏ con lại làm được mấy vụ. Tôi bắt đầu quan sát anh ấy, xem anh ấy tiếp khách thế nào."], ["", "一天，有两个顾客推门进来了。走在前面的是一个50来岁的妇女，后面跟着一个矮胖男人，应该是她的丈夫吧。根据经验推断，这两个人像是随便看看的，不像是来买车的，推销员们就显得不太热心。", "Yìtiān, yǒu liǎngge gùkè tuī mén jìnlái le. Zǒu zài qiánmiàn de shì yíge50 lái suì de fùnǚ, hòumiàn gēnzhe yíge ǎipàng nánrén, yīnggāi shì tā de zhàngfu ba. Gēnjù jīngyàn tuīduàn, zhè liǎngge rén xiàngshì suíbiàn kànkan de, bú xiàngshì lái mǎichē de, tuīxiāoyuán men jiù xiǎnde bútài rèxīn.", "Đoạn 2: Một hôm, có hai khách hàng đẩy cửa bước vào. Người đi trước là một phụ nữ khoảng 50 tuổi, phía sau là một người đàn ông thấp béo, chắc là chồng bà. Theo kinh nghiệm suy đoán, hai người này có vẻ chỉ xem qua thôi, không có vẻ là mua xe, nên mấy nhân viên bán hàng tỏ ra không mấy nhiệt tình."], ["", "这时，孙明迎了上去，热情地问：“看车呀？”女顾客点点头。孙明对她说：“这车不适合您。”女顾客没想到会听到这样的话，就问为什么。孙明带着他们一边往车前走，一边解释：“您要是开车呀，最好是选择两厢车，操作更容易些，也更省油，经济实惠。”而这种车是为从事商务的人士设计的，为了跑远路平稳，就稍微重一点儿，比开两厢车累，也更费油。我们旁边的车行里新来了一种两厢车，挺适合您的，您不妨去看看。”", "Zhèshí, Sūn Míng yíng le shàngqù, rèqíng dìwèn: “Kànchē ya?” nǚ gùkè diǎndiǎntóu. Sūn Míng duì tā shuō: “Zhèchē bú shìhé nín.” nǚ gùkè méixiǎngdào huì tīngdào zhèyàngdehuà, jiù wèn wèishénme. Sūn Míng dài zhe tāmen yìbiān wǎngchē qián zǒu, yìbiān jiěshì: “Nín yàoshì kāichē ya, zuìhǎo shì xuǎnzé liǎngxiāngchē, cāozuò gèng róngyì xiē, yě gèng shěngyóu, jīngjì shíhuì.” ér zhèzhǒng chēshì wèi cóngshì shāngwù de rénshì shèjì de, wèile pǎo yuǎnlù píngwěn, jiù shāowēi zhòng yìdiǎnr, bǐkāi liǎngxiāngchē lèi, yě gèngfèiyóu. Wǒmen pángbiān de chēháng lǐ xīnlái le yìzhǒng liǎngxiāngchē, tǐng shìhé nín de, nín bùfáng qù kànkan.”", "Đoạn 3: Lúc đó, Tôn Minh đón lên, nhiệt tình hỏi: \"Xem xe ạ?\" Nữ khách gật đầu. Tôn Minh nói với bà: \"Xe này không hợp với bà đâu.\" Nữ khách không ngờ lại nghe câu nói như vậy, liền hỏi tại sao. Tôn Minh vừa dẫn họ đi về phía chiếc xe vừa giải thích: \"Bà lái xe thì tốt nhất nên chọn loại xe hai khoang, thao tác dễ hơn một chút, cũng đỡ tốn xăng hơn, kinh tế và thiết thực.\" Còn loại xe này được thiết kế cho người làm công việc thương vụ, để chạy đường dài cho vững nên hơi nặng hơn một chút, lái mệt hơn xe hai khoang và cũng tốn xăng hơn. Bên cạnh cửa hàng chúng tôi mới có loại xe hai khoang mới, rất hợp với bà, bà có thể sang xem thử.\""], ["", "那位女顾客却说：“我觉得这车挺好的。”孙明接着解释：“这车空间比较宽敞，比一般家用的车宽一点儿，长一点儿，您要是开吧，不一定会觉得舒服。”女顾客坐进去试了试，果然觉得操作起来不舒服。她点了点头，下了车，一边道谢，一边跟着她的丈夫走了。", "Nàwèi nǚ gùkè quèshuō: “Wǒ juéde zhèchē tǐng hǎo de.” Sūn Míng jiēzhe jiěshì: “Zhè chē kōngjiān bǐjiào kuānchǎng, bǐ yìbān jiāyòng de chē kuān yìdiǎnr, zhǎng yìdiǎnr, nín yàoshì kāi ba, bù yídìng huì juéde shūfu.” nǚ gùkè zuò jìnqù shìleshì, guǒrán juéde cāozuò qǐlái bù shūfu. Tā diǎn le diǎntóu, xià le chē, yìbiān dàoxiè, yìbiān gēnzhe tā de zhàngfu zǒu le.", "Đoạn 4: Nhưng nữ khách lại nói: \"Tôi thấy xe này rất đẹp mà.\" Tôn Minh tiếp tục giải thích: \"Xe này không gian khá rộng rãi, rộng hơn xe gia đình thông thường một chút, dài hơn một chút, nếu bà lái thì chưa chắc đã thấy thoải mái.\" Nữ khách ngồi thử, quả nhiên thấy thao tác không thoải mái. Bà gật đầu, xuống xe, vừa cảm ơn vừa đi theo chồng ra về."], ["", "我不解地看着孙明。那位女顾客明明喜欢这辆车，只要再劝说一番，她就会掏钱买下来了，可这个孙明，却把到手的生意推出去了。", "Wǒ bùjiě dì kànzhe Sūn Míng. Nàwèi nǚ gùkè míngmíng xǐhuan zhèliàng chē, zhǐyào zài quànshuō yìfān, tā jiù huì tāoqián mǎixiàlái le, kě zhège Sūn Míng, què bǎ dàoshǒu de shēngyi tuīchū qù le.", "Đoạn 5: Tôi nhìn Tôn Minh với vẻ khó hiểu. Nữ khách rõ ràng thích chiếc xe này, chỉ cần khuyên thêm một chút nữa là bà sẽ móc tiền mua ngay, vậy mà Tôn Minh lại đẩy mối làm ăn đã cầm chắc ra đi."], ["", "快下班的时候，那位女顾客又进了车行。这次她的身后不仅跟着她的丈夫，还跟着一个高高大大的小伙子。女顾客一进车行就招呼孙明，并对一起来的小伙子说：“这个小孙可实诚了，从他手里买车，准没错。”她又对孙明说，她儿子刚刚创办了一家公司，需要买几部商用车，给公司用来跑业务。她这次是特地陪儿子来选车的。", "Kuàixiàbān de shíhou, nàwèi nǚ gùkè yòu jìn le chēháng. Zhècì tā de shēnhòu bùjǐn gēnzhe tā de zhàngfu, háigēnzhe yíge gāogāodàdà de xiǎohuǒzi. Nǚ gùkè yíjìn chēháng jiù zhāohū Sūn Míng, bìng duì yì qǐlái de xiǎohuǒzi shuō: “Zhège xiǎosūn kě shíchéng le, cóng tā shǒulǐ mǎichē, zhǔn méicuò.” tā yòu duì Sūn Míng shuō, tā érzi gānggāng chuàngbàn le yìjiā gōngsī, xūyào mǎi jǐbù shāngyòngchē, gěi gōngsī yònglái pǎo yèwù. Tā zhècì shì tèdì péi érzi lái xuǎnchē de.", "Đoạn 6: Gần giờ tan ca, vị nữ khách lại bước vào cửa hàng. Lần này sau lưng bà không chỉ có chồng mà còn có một chàng trai cao lớn. Vừa vào cửa, bà đã gọi Tôn Minh và nói với chàng trai đi cùng: \"Anh Tôn này thật thà lắm, mua xe từ tay anh ấy thì chắc chắn không sai.\" Bà lại nói với Tôn Minh rằng con trai bà vừa thành lập một công ty, cần mua vài chiếc xe thương mại để công ty chạy việc. Lần này bà đặc biệt đi cùng con trai để chọn xe."], ["", "那个小伙子也对孙明说，他本来已经看好了其他车行的几种车，但听母亲讲了在这里的经历后，他也想请孙明给他推荐车。孙明给他介绍了几种车，小伙子毫不犹豫地跟孙明签了合同，一下子就订了五部车。", "Nàge xiǎohuǒzi yě duì Sūn Míng shuō, tā běnlái yǐjīng kànhǎo le qítā chēháng de jǐzhǒng chē, dàn tīng mǔqīn jiǎng le zài zhèlǐ de jīnglì hòu, tā yě xiǎng qǐng Sūn Míng gěi tā tuījiàn chē. Sūn Míng gěi tā jièshào le jǐzhǒng chē, xiǎohuǒzi háobùyóuyù dì gēn Sūn Míng qiānle hétóng, yíxiàzi jiùdìng le wǔbù chē.", "Đoạn 7: Anh chàng đó cũng nói với Tôn Minh rằng vốn anh đã xem mấy loại xe ở các cửa hàng khác, nhưng nghe mẹ kể trải nghiệm ở đây thì cũng muốn nhờ Tôn Minh tư vấn. Tôn Minh giới thiệu cho anh vài loại xe, anh chàng không do dự ký hợp đồng với Tôn Minh, đặt mua năm chiếc một lúc."], ["", "我这时才恍然大悟，明白了销售人员都应该懂得的道理：孙明的拒绝，其实是拒绝虚伪。做生意就是要讲诚信，真正为客户着想，才能赢得客户的信任。", "Wǒ zhèshí cái huǎngrándàwù, míngbái le xiāoshòu rényuán dōu yīnggāi dǒngde de dàolǐ: Sūn Míng de jùjué, qíshí shì jùjué xūwěi. Zuòshēngyì jiùshì yào jiǎng chéngxìn, zhēnzhèng wèi kèhù zhuóxiǎng, cáinéng yíngdé kèhù de xìnrèn.", "Đoạn 8: Lúc ấy tôi mới bỗng nhiên hiểu ra và thấu rõ cái đạo lý mà nhân viên bán hàng nào cũng nên hiểu: Sự từ chối của Tôn Minh kỳ thực là từ chối sự giả dối. Làm ăn là phải giữ chữ tín, thực sự nghĩ cho khách hàng thì mới giành được lòng tin của họ."]]}], "fn": [["却", "", "Nhưng, lại (trái với mong đợi). Phó từ đứng sau chủ ngữ, trước động từ.", "大家都没卖出车，孙明却做成了好几笔业务。"], ["只要……就……", "", "Chỉ cần… là…. Không trộn với 只有……才…….", "只要再劝说一番，她就会掏钱买下来。"], ["不仅……还……", "", "Không những… mà còn….", "她的身后不仅跟着她的丈夫，还跟着一个小伙子。"], ["本来……但……", "", "Vốn dĩ… nhưng… (dự định ban đầu thay đổi).", "他本来已经看好了其他车行的车，但听了母亲的话，也想请孙明推荐。"], ["一边……一边……", "", "Vừa… vừa… (hai hành động cùng lúc).", "孙明一边带他们往车前走，一边解释。"]], "adv": [], "ex2": [["“我”为什么开始观察孙明？", "因为“我”一部车也没卖出，孙明却做成了好几笔业务。", ["因为孙明是“我”的老板。", "因为孙明想辞职。"]], ["推销员们为什么不太热心？", "他们觉得这两个人不像是来买车的。", ["他们太累了。", "他们不认识这两个人。"]], ["孙明为什么说“这车不适合您”？", "这车是为商务人士设计的，比较重、费油，不适合她开。", ["这车太便宜了。", "这车已经卖完了。"]], ["“我”为什么不理解孙明？", "女顾客明明喜欢这辆车，孙明却把生意推出去了。", ["孙明骂了顾客。", "孙明下班太早了。"]], ["后来那个小伙子一次订了几辆车？", "五辆。", ["一辆。", "两辆。"]], ["孙明的拒绝，其实是拒绝什么？", "拒绝虚伪。", ["拒绝顾客。", "拒绝工作。"]]]}, "hk3-l4": {"page": "—", "src": "发展汉语 · 高级读写（3）· 第4课", "kw": [{"h": "课文", "lines": [["", "新婚后，夫妻关系确立了，妻子常常会陷入如何称呼丈夫的烦恼中，好像什么都别扭。丈夫称呼妻子似乎没问题，轻松一点儿的叫“家里的”，随便一点儿的叫“老婆”，庄重一点儿的叫“太太”，老家来了客人叫“媳妇儿”……可以选用的真不少，所以丈夫从不为称呼的事烦恼。", "Xīnhūn hòu, fūqīguānxì quèlì le, qīzǐ chángcháng huì xiànrù rúhé chēnghū zhàngfu de fánnǎo zhōng, hǎoxiàng shénme dōu bièniu. Zhàngfu chēnghū qīzǐ sìhū méi wèntí, qīngsōng yìdiǎnr de jiào “Jiālǐ de”, suíbiàn yìdiǎnr de jiào “Lǎopo”, zhuāngzhòng yìdiǎnr de jiào “Tàitài”, lǎojiā lái le kèren jiào “Xífur” …… kěyǐ xuǎnyòng de zhēnbùshǎo, suǒyǐ zhàngfu cóngbú wèi chēnghū de shì fánnǎo.", "Sau khi cưới, quan hệ vợ chồng đã xác lập, người vợ thường rơi vào nỗi phiền não không biết gọi chồng thế nào, dường như gọi gì cũng ngượng. Chồng gọi vợ thì có vẻ không vấn đề gì: thoải mái thì gọi \"家里的\", tùy tiện thì gọi \"老婆\", trang trọng thì gọi \"太太\", quê có khách lên thì gọi \"媳妇儿\"… có thể chọn dùng thật không ít, nên chồng chưa bao giờ phiền não chuyện xưng hô."], ["", "可妻子怎么叫丈夫呢？“丈夫”是最普通的。可是显得太文气了点儿，再说，它只能在向人介绍时使用，不能当面称呼。", "Kě qīzǐ zěnme jiào zhàngfu ne? “Zhàngfu” shì zuì pǔtōng de. Kěshì xiǎnde tài wénqì le diǎnr, zàishuō, tā zhǐnéng zài xiàng rén jièshào shí shǐyòng, bùnéng dāngmiàn chēnghū.", "Nhưng vợ gọi chồng thế nào đây? \"丈夫\" là phổ thông nhất, nhưng có vẻ hơi sách vở; hơn nữa nó chỉ dùng khi giới thiệu với người khác, không gọi trực tiếp được."], ["", "“爱人”曾经是通行的说法，字面的意思是“我所爱的人”，不管男女都可以用，本来挺有浪漫色彩的，可是在过去的年代使用久了，这层浪漫色彩早已磨损，变成了一种过时的称呼。跟丈夫一样，“爱人”也不适合当面称呼。", "“Àiren” céngjīng shì tōngxíng de shuōfǎ, zìmiàn de yìsi shì “Wǒ suǒ ài de rén”, bùguǎn nánnǚ dōu kěyǐ yòng, běnlái tǐng yǒu làngmàn sècǎi de, kěshì zài guòqù de niándài shǐyòng jiǔ le, zhècéng làngmàn sècǎi zǎoyǐ mósǔn, biànchéng le yìzhǒng guòshí de chēnghū. Gēn zhàngfu yíyàng, “Àiren” yě bú shìhé dāngmiàn chēnghū.", "\"爱人\" từng là cách nói thông dụng, nghĩa đen là \"người tôi yêu\", nam nữ đều dùng được, vốn rất lãng mạn, nhưng dùng lâu trong những năm tháng trước, lớp màu lãng mạn ấy đã mòn đi, thành cách gọi lỗi thời. Giống \"丈夫\", \"爱人\" cũng không hợp để gọi trực tiếp."], ["", "“先生”是从对成年男性的尊称发展来的，严肃有余，亲热不足。这个称呼在宴会厅、会议室等比较高雅的场所用才合适，而这位“先生”应具备一定的条件：西服革履，最好是一个文化人。我们很难想象，把穿着背心短裤的丈夫唤做“先生”。另外，“先生”也不适合用来当面称呼丈夫。", "“Xiānsheng” shìcóng duì chéngnián nánxìng de zūnchēng fāzhǎn lái de, yánsù yǒuyú, qīnrè bùzú. Zhège chēnghū zài yànhuìtīng, huìyìshì děng bǐjiào gāoyǎ de chǎngsuǒ yòng cái héshì, ér zhèwèi “Xiānsheng” yīng jùbèi yídìng de tiáojiàn: Xīfúgélǚ, zuìhǎo shì yíge wénhuà rén. Wǒmen hěnnán xiǎngxiàng, bǎ chuānzhe bèixīn duǎnkù de zhàngfu huàn zuò “Xiānsheng”. Lìngwài, “Xiānsheng” yě bú shìhé yònglái dāngmiàn chēnghū zhàngfu.", "\"先生\" phát triển từ cách gọi tôn kính nam giới trưởng thành, nghiêm túc thì thừa, thân mật thì thiếu. Nó chỉ hợp ở nơi trang nhã như phòng tiệc, phòng họp, và vị \"先生\" ấy phải có điều kiện: com-lê giày da, tốt nhất là người có học. Khó mà tưởng tượng gọi ông chồng mặc áo ba lỗ quần đùi là \"先生\". Ngoài ra, \"先生\" cũng không hợp để gọi chồng trực tiếp."], ["", "“男人”本来可以用来指所有的男性，不知怎么被用来专门称自己丈夫。它和“先生”正好处于两个极端，显得随便，甚至有些俗气。这个称呼不被文化人接受。还有一点，“男人”也和“丈夫”、“爱人”一样，不适合作为称呼。", "“Nánrén” běnlái kěyǐ yònglái zhǐ suǒyǒu de nánxìng, bùzhī zěnme bèi yònglái zhuānmén chēng zìjǐ zhàngfu. Tā hé “Xiānsheng” zhènghǎo chǔyú liǎngge jíduān, xiǎnde suíbiàn, shènzhì yǒuxiē súqì. Zhège chēnghū bú bèi wénhuà rén jiēshòu. Háiyǒu yìdiǎn, “Nánrén” yě hé “Zhàngfu”, “Àiren” yíyàng, bú shìhé zuòwéi chēnghū.", "\"男人\" vốn chỉ mọi nam giới, chẳng hiểu sao lại dùng riêng để gọi chồng mình. Nó và \"先生\" ở hai thái cực: có vẻ tùy tiện, thậm chí hơi thô tục, không được người có học chấp nhận. Thêm nữa, \"男人\" cũng như \"丈夫\", \"爱人\", không hợp làm lời gọi."], ["", "看来，要给丈夫找一个适合于各种场合，可以作为他称，又可以当面称呼，既有亲热感，又有时代感的称呼还真不容易。于是，“老公”这个词就开始兴起来了。", "Kànlái, yào gěi zhàngfu zhǎo yíge shìhé yú gèzhǒng chǎnghé, kěyǐ zuòwéi tāchēng, yòu kěyǐ dāngmiàn chēnghū, jìyǒu qīnrè gǎn, yòu yǒu shídàigǎn de chēnghū hái zhēnbùróngyì. Yúshì, “Lǎogōng” zhège cí jiù kāishǐ xīngqǐ lái le.", "Xem ra, muốn tìm cho chồng một cách gọi hợp mọi hoàn cảnh, vừa dùng để nhắc đến, vừa gọi trực tiếp được, vừa thân mật vừa hợp thời thì thật không dễ. Thế là từ \"老公\" bắt đầu thịnh hành."], ["", "“老公”本来是一个方言词。随着大量的港台电视剧的播放，这个称呼也逐渐流行起来了。“老公”这一词的结构应是和“老婆”相对的，应该也是口语化的称呼；但是港台电视剧的流行，消除了这个词语的俗气。在电视剧中，年轻小姐叫丈夫为“老公”，中老年女士也叫丈夫为“老公”；不管有没有文化的女性，都可以称丈夫为“老公”，“老公”逐渐成了一个家喻户晓、人人皆用的称呼。", "“Lǎogōng” běnlái shì yíge fāngyáncí. Suízhe dàliàng de gǎngtái diànshìjù de bōfàng, zhège chēnghū yě zhújiàn liúxíngqǐlái le. “Lǎogōng” zhèyìcí de jiégòu yīngshì hé “Lǎopo” xiāngduì de, yīnggāi yě shì kǒuyǔhuà de chēnghū; dànshì gǎngtái diànshìjù de liúxíng, xiāochú le zhège cíyǔ de súqì. Zài diànshìjù zhōng, niánqīng xiǎojiě jiào zhàngfu wèi “Lǎogōng”, zhōnglǎonián nǚshì yě jiào zhàngfu wèi “Lǎogōng” ; bùguǎn yǒuméiyǒu wénhuà de nǚxìng, dōu kěyǐ chēng zhàngfu wèi “Lǎogōng”, “Lǎogōng” zhújiàn chéng le yíge jiāyùhùxiǎo, rénrén jiē yòng de chēnghū.", "\"老公\" vốn là từ phương ngữ. Theo đà phát sóng nhiều phim Hồng Kông, Đài Loan, cách gọi này dần phổ biến. Về cấu trúc nó đối ứng với \"老婆\", lẽ ra cũng là cách gọi khẩu ngữ; nhưng phim Hồng Kông, Đài Loan đã xóa đi vẻ thô tục của nó. Trong phim, cô gái trẻ hay phụ nữ trung niên đều gọi chồng là \"老公\"; dù có học hay không, phụ nữ đều có thể gọi như vậy, \"老公\" dần thành cách gọi nhà nhà đều biết."], ["", "不过，还是有些人对“老公”这个称呼不以为然，原因之一是觉得“老公”来自南方，使人想起港台腔的普通话，不如京味普通话那么正宗。另一个原因，“老公”总是出现在港台电视剧中，使人想到某些表演做作的感情戏。看来，“老公”也不是一个人人满意的称呼。", "Búguò, háishì yǒuxiē rén duì “Lǎogōng” zhège chēnghū bùyǐwéirán, yuányīn zhīyí shì juéde “Lǎogōng” láizì nánfāng, shǐrén xiǎngqǐ gǎngtáiqiāng de pǔtōnghuà, bùrú jīngwèi pǔtōnghuà nàme zhèngzōng. Lìng yíge yuányīn, “Lǎogōng” zǒngshì chūxiàn zài gǎngtái diànshìjù zhōng, shǐrén xiǎngdào mǒuxiē biǎoyǎn zuòzuò de gǎnqíng xì. Kànlái, “Lǎogōng” yě búshì yíge rénrén mǎnyì de chēnghū.", "Tuy vậy, vẫn có người không đồng tình với \"老公\". Một lý do là họ thấy nó đến từ phương Nam, gợi nhớ tiếng phổ thông giọng Hồng Kông – Đài Loan, không chính gốc bằng giọng Bắc Kinh. Lý do khác là \"老公\" luôn xuất hiện trong phim Hồng Kông, Đài Loan, khiến người ta nghĩ tới những màn tình cảm diễn giả tạo. Xem ra, \"老公\" cũng không làm ai cũng hài lòng."], ["", "其实对此有不同的观点很自然。语言的魅力本来就在于它千变万化，重要的是，使用称呼和运用语言一样，要根据场合，根据不同的对象进行选择。", "Qíshí duìcǐ yǒu bùtóng de guāndiǎn hěn zìrán. Yǔyán de mèilì běnlái jiù zàiyú tā qiānbiànwànhuà, zhòngyào de shì, shǐyòng chēnghū hé yùnyòng yǔyán yíyàng, yào gēnjù chǎnghé, gēnjù bùtóng de duìxiàng jìnxíng xuǎnzé.", "Thật ra có quan điểm khác nhau về chuyện này là rất tự nhiên. Sức hấp dẫn của ngôn ngữ vốn nằm ở sự biến hóa khôn lường; điều quan trọng là dùng xưng hô cũng như dùng ngôn ngữ, phải lựa chọn theo hoàn cảnh và theo từng đối tượng."]]}], "fn": [["既……又……", "", "Vừa… vừa… (hai tính chất cùng có).", "这个称呼既有亲热感，又有时代感。"], ["随着……", "", "Cùng với sự…, theo đà… (không dùng 所以 ở vế sau).", "随着港台电视剧的播放，这个称呼逐渐流行起来了。"], ["不管……都……", "", "Bất kể… đều….", "不管有没有文化的女性，都可以称丈夫为“老公”。"], ["对……不以为然", "", "Không đồng tình với….", "有些人对“老公”这个称呼不以为然。"], ["……在于……", "", "… nằm ở…, cốt ở….", "语言的魅力本来就在于它千变万化。"]], "adv": [["老公", "lǎo gōng", "chồng (khẩu ngữ, thông dụng)"], ["方言", "fāng yán", "phương ngôn, tiếng địa phương"], ["港台", "Gǎng-Tái", "Hồng Kông và Đài Loan"], ["电视剧", "diàn shì jù", "phim truyền hình"], ["流行", "liú xíng", "thịnh hành, lưu hành"], ["结构", "jié gòu", "cấu trúc"], ["相对", "xiāng duì", "tương đối, đối ứng"], ["口语化", "kǒu yǔ huà", "mang tính khẩu ngữ"], ["俗气", "sú qì", "(như trên)"], ["家喻户晓", "jiā yù hù xiǎo", "ai cũng biết, khắp nhà đều hay"], ["不以为然", "bù yǐ wéi rán", "không cho là đúng, không tán thành"], ["正宗", "zhèng zōng", "chính thống, đúng chuẩn"], ["做作", "zuò zuo", "giả tạo, kịch tính"], ["魅力", "mèi lì", "sức hấp dẫn, mị lực"], ["千变万化", "qiān biàn wàn huà", "thiên biến vạn hóa, đa dạng"], ["场合", "chǎng hé", "trường hợp, dịp, hoàn cảnh"], ["对象", "duì xiàng", "đối tượng"]], "ex2": [["为什么丈夫从不为称呼的事烦恼？", "因为称呼妻子可以选用的词很多。", ["因为丈夫不需要称呼妻子。", "因为丈夫只叫妻子“太太”。"]], ["“丈夫”这个称呼有什么问题？", "太文气，只能在介绍时用，不能当面称呼。", ["太俗气了。", "只能当面称呼。"]], ["“先生”适合在什么场合用？", "宴会厅、会议室等比较高雅的场所。", ["在家里穿背心短裤的时候。", "在菜市场买菜的时候。"]], ["为什么文化人不接受“男人”这个称呼？", "它显得随便，甚至有些俗气。", ["它太严肃了。", "它太浪漫了。"]], ["“老公”是怎么流行起来的？", "随着港台电视剧的播放逐渐流行起来。", ["是政府规定的。", "是从京味普通话来的。"]], ["作者认为使用称呼最重要的是什么？", "要根据场合和不同的对象进行选择。", ["一定要用“老公”。", "只能用“丈夫”。"]]]}, "hk3-l5": {"page": "—", "src": "发展汉语 · 高级读写（3）", "kw": [{"h": "课文 说不尽的西安古城", "lines": [["", "在中国，我游览过许多地方。在我去过的地方中，有高楼林立、现代化程度很高的城市，比如上海；有美丽而不太发达的城镇，比如丽江。在这些城市中，最吸引我的是古城西安。", "Zài zhōngguó, wǒ yóulǎn guò xǔduō dìfāng. Zài wǒ qùguò de dìfāng zhōng, yǒu gāolóu línlì, xiàndàihuà chéngdù hěn gāo de chéngshì, bǐrú shànghǎi; yǒu měilì ér bú tài fādá de chéngzhèn, bǐrú lìjiāng. Zài zhèxiē chéngshì zhōng, zuì xīyǐn wǒ de shì gǔchéng xīān.", "Ở Trung Quốc, tôi đã tham quan nhiều nơi. Trong đó có thành phố nhà cao tầng san sát, hiện đại hóa rất cao như Thượng Hải; có thị trấn xinh đẹp nhưng chưa phát triển lắm như Lệ Giang. Trong những thành phố ấy, thu hút tôi nhất là thành cổ Tây An."], ["", "没到西安前，我想象中的西安是一个“白胡子老人”——他走过了千年历史，身上盖满了灰尘。可是，当我走进西安时，还是被打动了。与我去过的其他城市相比，西安的历史遗迹简直是太多了，这些古迹透过岁月的灰土，向游客们解释着历史，诉说着古代文明的辉煌。", "Méi dào xīān qián, wǒ xiǎngxiàng zhōng de xīān shì yíge “Báihúzi lǎorén” —— tā zǒuguò le qiānnián lìshǐ, shēnshàng gàimǎn le huīchén. Kěshì, dāng wǒ zǒujìn xīān shí, háishì bèi dǎdòng le. Yǔ wǒ qùguò de qítā chéngshì xiāngbǐ, xīān de lìshǐ yíjì jiǎnzhí shì tài duō le, zhèxiē gǔjì tòuguò suìyuè de huītǔ, xiàng yóukè men jiěshì zhe lìshǐ, sùshuōzhe gǔdàiwénmíng de huīhuáng.", "Trước khi đến, Tây An trong tưởng tượng của tôi là một \"ông già râu trắng\" – đã đi qua nghìn năm lịch sử, người phủ đầy bụi. Thế nhưng khi bước vào Tây An, tôi vẫn bị lay động. So với những thành phố khác tôi từng đến, di tích lịch sử ở Tây An thật quá nhiều; những cổ tích ấy xuyên qua lớp bụi năm tháng, giải thích lịch sử cho du khách, kể lại sự huy hoàng của văn minh cổ đại."], ["", "西安曾经是中国古代的政治、经济中心，历史上许多朝代都建都于此。去西安当然首先要看兵马俑。虽然对兵马俑我早有耳闻，但来到它跟前时，我还是被它宏大的规模惊呆了：一千多个与真人大小相同的兵马俑排列成阵，好像一支整装待发的军队。我一下子明白了，为什么当年是秦始皇，而不是别人统一了中国——因为秦始皇有这样一支军队。", "Xīān céngjīng shì zhōngguó gǔdài de zhèngzhì, jīngjì zhōngxīn, lìshǐ shàng xǔduō cháodài dōu jiàndūyú cǐ. Qù xīān dāngrán shǒuxiān yào kàn bīngmǎyǒng. Suīrán duì bīngmǎyǒng wǒ zǎo yǒu ěrwén, dàn láidào tā gēnqián shí, wǒ háishì bèi tā hóngdà de guīmó jīngdāi le: Yìqiānduōge yǔ zhēnrén dàxiǎo xiāngtóng de bīngmǎyǒng páilièchéng zhèn, hǎoxiàng yìzhī zhěngzhuāngdàifā de jūnduì. Wǒ yíxiàzi míngbái le, wèishénme dāngnián shì qínshǐhuáng, ér búshì biérén tǒngyī le zhōngguó—— yīnwèi qínshǐhuáng yǒu zhèyàng yìzhī jūnduì.", "Tây An từng là trung tâm chính trị, kinh tế của Trung Quốc cổ đại, nhiều triều đại đóng đô ở đây. Đến Tây An đương nhiên trước hết phải xem tượng Binh Mã. Tuy đã nghe danh từ lâu, nhưng khi đến trước mặt, tôi vẫn sững sờ trước quy mô hùng vĩ: hơn một nghìn tượng binh mã to bằng người thật xếp thành trận, như một đội quân chỉnh tề chờ xuất phát. Tôi bỗng hiểu vì sao năm xưa là Tần Thủy Hoàng chứ không phải ai khác thống nhất Trung Quốc – vì ông có một đội quân như thế."]]}], "fn": [["与……相比", "", "So với….", "与我去过的其他城市相比，西安的历史遗迹太多了。"], ["虽然……但……还是……", "", "Tuy… nhưng vẫn….", "虽然对兵马俑我早有耳闻，但来到它跟前时，我还是被惊呆了。"], ["被 + (tác nhân) + V + bổ ngữ", "", "Câu bị động: chủ ngữ chịu tác động.", "我还是被它宏大的规模惊呆了。"], ["是 A，而不是 B", "", "Là A chứ không phải B (nhấn mạnh).", "当年是秦始皇，而不是别人统一了中国。"]], "adv": [], "ex2": [["作者去过的地方中，最吸引他的是哪儿？", "古城西安。", ["上海。", "丽江。"]], ["没到西安前，作者想象中的西安是什么样的？", "一个身上盖满灰尘的“白胡子老人”。", ["一个高楼林立的现代化城市。", "一个美丽而不太发达的小镇。"]], ["与其他城市相比，西安有什么特点？", "历史遗迹特别多。", ["高楼特别多。", "游客特别少。"]], ["作者认为秦始皇为什么能统一中国？", "因为秦始皇有像兵马俑这样的军队。", ["因为秦始皇建了很多高楼。", "因为西安离上海很近。"]]]}, "hk3-l6": {"page": "—", "src": "发展汉语 · 高级读写（3）· 童年的回忆（仓光孝次）", "kw": [{"h": "课文 童年的回忆", "lines": [["", "人们都说，孩子眼睛里的东西总是美好的。回想我童年的一些往事，我觉得的确是这样。", "Rénmen dōu shuō, háizi yǎnjīng lǐ de dōngxi zǒngshì měihǎo de. Huíxiǎng wǒ tóngnián de yìxiē wǎngshì, wǒ juéde díquè shì zhèyàng.", "Người ta đều nói, những gì trong mắt trẻ con luôn đẹp đẽ. Nhớ lại vài chuyện cũ thời thơ ấu, tôi thấy quả đúng như vậy."], ["", "还记得，我六岁那一年的春天，有一天我跟母亲去买东西，回家的路上，我坐在公共汽车上出神地看着农村的景色。外边下着细细的雨，路的左边是一条河，因为那两天下雨，河水浩荡，平常清亮透明的河水也变黄了。河的对岸是一片绿油油的山野，河的右边是农村住宅，一条柏油路从中间穿过，路边成百上千只奶牛好奇地看着我坐的“大铁箱”。我就住在这个地区，虽然很熟悉这里的东南西北，可是从公共汽车里看到的村子仿佛和平时看到的完全不一样了，觉得很新鲜。绿树、小河、奶牛，我睁着眼睛看也看不够……", "Hái jìde, wǒ liùsuì nà yìnián de chūntiān, yǒu yìtiān wǒ gēn mǔqīn qù mǎi dōngxi, huíjiā de lùshàng, wǒ zuòzài gōnggòngqìchē shàng chūshén dì kànzhe nóngcūn de jǐngsè. Wàibiān xià zhe xìxìde yǔ, lù de zuǒbian shì yìtiáo hé, yīnwèi nà liǎngtiān xiàyǔ, héshuǐ hàodàng, píngcháng qīngliàng tòumíng de héshuǐ yě biàn huáng le. Hé de duìàn shì yípiàn lǜyóuyóu de shānyě, hé de yòubian shì nóngcūn zhùzhái, yìtiáo bǎiyóulù cóng zhōngjiān chuānguò, lùbiān chéngbǎishàngqiān zhǐ nǎiniú hàoqí dì kànzhe wǒ zuò de “Dà tiěxiāng”. Wǒ jiù zhù zài zhège dìqū, suīrán hěn shúxī zhèlǐ de dōngnánxīběi, kěshì cóng gōnggòngqìchē lǐ kàndào de cūnzi fǎngfú hé píngshí kàndào de wánquán bù yíyàng le, juéde hěn xīnxiān. Lǜshù, xiǎohé, nǎiniú, wǒ zhēng zhe yǎnjīng kàn yě kàn búgòu……", "Tôi vẫn nhớ, mùa xuân năm sáu tuổi, một hôm tôi theo mẹ đi mua đồ; trên đường về, tôi ngồi trên xe buýt ngẩn người ngắm cảnh nông thôn. Ngoài trời mưa lất phất, bên trái đường là con sông; vì mưa mấy hôm nên nước cuồn cuộn, dòng nước vốn trong vắt cũng ngả vàng. Bờ bên kia là đồi núi xanh mướt, bên phải là nhà cửa nông thôn, con đường nhựa chạy xuyên qua giữa, bên đường hàng trăm hàng nghìn con bò sữa tò mò nhìn chiếc \"hộp sắt lớn\" tôi ngồi. Tôi sống ngay ở vùng này, rất quen đông tây nam bắc, nhưng ngôi làng nhìn từ trong xe buýt dường như khác hẳn ngày thường, rất mới mẻ. Cây xanh, sông nhỏ, bò sữa – tôi mở to mắt nhìn mãi không chán…"], ["", "于是，我迷上了坐公共汽车，成了个坐车迷。在日本，6岁以下的儿童坐公共汽车都免费，作为一个坐车迷怎么能错过这个机会？因此，我每天从幼儿园回来后，马上就去汽车站坐公共汽车。", "Yúshì, wǒmí shàng le zuò gōnggòngqìchē, chéng le ge zuòchē mí. Zài rìběn, 6 suì yǐxià de értóng zuò gōnggòngqìchē dōu miǎnfèi, zuòwéi yíge zuòchē mí zěnme néng cuòguò zhège jīhuì? Yīncǐ, wǒ měitiān cóng yòuéryuán huílái hòu, mǎshàng jiù qù qìchēzhàn zuò gōnggòngqìchē.", "Thế là tôi mê đi xe buýt, thành một \"fan\" đi xe. Ở Nhật, trẻ dưới 6 tuổi đi xe buýt miễn phí, là fan đi xe sao có thể bỏ lỡ cơ hội này? Vì vậy ngày nào từ nhà trẻ về, tôi cũng lập tức ra bến đi xe buýt."], ["", "我乘坐的公共汽车是3点45分出发，开这班车的司机是佐藤先生。他穿着整齐的制服，裤线熨得笔直，像用裁纸刀裁出来的一样；他戴着的黑亮的司机帽显示着他对自己工作的骄傲。他是这班车的唯一的工作人员，乘客从后门上车，在前门给他交车费下车，秩序井井有条。在这辆车里，他是国王，大家都服从他，按他的要求去做。我觉得他比任何人都强。小男孩儿一般都崇拜强壮的英雄。除了父亲以外，佐藤是我遇见的第一个英雄。", "Wǒ chéngzuò de gōnggòngqìchē shì3 diǎn45 fēn chūfā, kāi zhè bānchē de sījī shì Zuǒténg xiānsheng. Tā chuānzhe zhěngqí de zhìfú, kùxiàn yùndé bǐzhí, xiàng yòng cáizhǐdāo cái chūlái de yíyàng; tā dài zhe de hēiliàng de sījī mào xiǎnshì zhe tā duì zìjǐ gōngzuò de jiāoào. Tā shì zhè bānchē de wéiyī de gōngzuòrényuán, chéngkè cóng hòumén shàngchē, zài qiánmén gěi tā jiāo chēfèi xiàchē, zhìxù jǐngjǐngyǒutiáo. Zài zhèliàng chēlǐ, tā shì guówáng, dàjiā dōu fúcóng tā, àn tā de yāoqiú qù zuò. Wǒ juéde tā bǐ rènhérén dōu qiáng. Xiǎo nánháir yìbān dōu chóngbài qiángzhuàng de yīngxióng. Chúle fùqīn yǐwài, Zuǒténg shì wǒ yùjiàn de dìyīge yīngxióng.", "Chuyến xe tôi đi khởi hành lúc 3 giờ 45, tài xế là ông Sato. Ông mặc đồng phục chỉnh tề, nếp quần là thẳng tắp như cắt bằng dao rọc giấy; chiếc mũ tài xế đen bóng cho thấy ông tự hào về công việc của mình. Ông là nhân viên duy nhất trên xe; hành khách lên cửa sau, xuống cửa trước và trả tiền cho ông, trật tự đâu ra đấy. Trong chiếc xe này ông là vua, mọi người đều nghe theo ông. Tôi thấy ông giỏi hơn bất cứ ai. Con trai nhỏ thường sùng bái người hùng mạnh mẽ. Ngoài bố ra, ông Sato là người hùng đầu tiên tôi gặp."], ["", "那时候，大人看见小孩儿一个人坐车，就会觉得奇怪。于是常有人诧异地问我：“到哪儿去啊？”“你妈妈呢？”我每次遇到这种情况都老老实实地回答：“我喜欢坐车。”其实，要详细回答这个问题，必须是这样：“我只是喜欢坐车，我可以免费乘坐，而且这班车的乘客不多，不影响别人；我只坐一站就下车回家，不用担心。”可是我当时的脑子不够用，没有能力说这样的话。我以为简单地说我喜欢坐车就解释得很清楚了，可是大人们却觉得很奇怪，他们的盘问越来越厉害了。我心里想：大人真喜欢管闲事，他们想把事情弄复杂。正在这时候，佐藤先生大声说话了：“不用担心，”他一直注视着前面的路，没有回头，“我认识他的父母，终点站那儿有他母亲的单位，家长在那儿接他。”这句话当然是真的，可是听起来，连我也觉得我的母亲会在终点站等着我。佐藤先生跟平时一样，像什么事都没发生过一样，头也没回，认认真真地驾驶着这个“大铁箱”。我们只能看到他高大的背影，他那严肃的背影仍然显示着他对工作的自豪。", "Nà shíhou, dàrén kànjiàn xiǎoháir yíge rén zuòchē, jiù huì juéde qíguài. Yúshì chángyǒu rén chàyì dìwèn wǒ: “Dào nǎr qù a?” “Nǐ māma ne?” wǒ měicì yùdào zhèzhǒng qíngkuàng dōu lǎolǎoshíshí dì huídá: “Wǒ xǐhuan zuòchē.” qíshí, yào xiángxì huídá zhège wèntí, bìxū shì zhèyàng: “Wǒ zhǐshì xǐhuan zuòchē, wǒ kěyǐ miǎnfèi chéngzuò, érqiě zhè bānchē de chéngkè bù duō, bù yǐngxiǎng biérén; wǒ zhǐ zuò yízhàn jiù xiàchē huíjiā, búyòng dānxīn.” kěshì wǒ dāngshí de nǎozi búgòu yòng, méiyǒu nénglì shuō zhèyàngdehuà. Wǒ yǐwéi jiǎndān dì shuō wǒ xǐhuan zuòchē jiù jiěshì de hěn qīngchǔ le, kěshì dà rénmen què juéde hěn qíguài, tāmen de pánwèn yuèláiyuè lìhài le. Wǒ xīnlǐ xiǎng: Dàrén zhēn xǐhuan guǎnxiánshì, tāmen xiǎng bǎ shìqing nòng fùzá. Zhèngzài zhèshíhòu, Zuǒténg xiānsheng dàshēng shuōhuà le: “Búyòng dānxīn,” tā yìzhí zhùshì zhe qiánmiàn de lù, méiyǒu huítóu, “Wǒ rènshi tā de fùmǔ, zhōngdiǎnzhàn nàr yǒu tā mǔqīn de dānwèi, jiāzhǎng zài nàr jiē tā.” zhèjù huà dāngrán shì zhēnde, kěshì tīng qǐlái, lián wǒ yě juéde wǒ de mǔqīn huì zài zhōngdiǎnzhàn děng zhe wǒ. Zuǒténg xiānsheng gēn píngshí yíyàng, xiàng shénme shì dōu méi fāshēng guò yíyàng, tóu yě méihuí, rènrènzhēnzhēn dì jiàshǐ zhe zhège “Dà tiěxiāng”. Wǒmen zhǐnéng kàndào tā gāodà de bèiyǐng, tā nà yánsù de bèiyǐng réngrán xiǎnshì zhe tā duì gōngzuò de zìháo.", "Hồi ấy, người lớn thấy trẻ con đi xe một mình thì thấy lạ, nên thường có người ngạc nhiên hỏi: \"Đi đâu đấy?\" \"Mẹ cháu đâu?\" Lần nào tôi cũng thật thà đáp: \"Cháu thích đi xe.\" Thật ra muốn trả lời đầy đủ phải nói: \"Cháu chỉ thích đi xe, cháu được đi miễn phí, chuyến này ít khách, không ảnh hưởng ai; cháu chỉ đi một bến rồi xuống về nhà, không cần lo.\" Nhưng khi đó đầu óc tôi chưa đủ để nói như thế. Tôi tưởng nói thích đi xe là đã rõ, nhưng người lớn lại thấy lạ, tra hỏi ngày càng gắt. Tôi nghĩ: người lớn thật thích lo chuyện bao đồng. Đúng lúc ấy ông Sato lên tiếng: \"Không cần lo,\" mắt vẫn nhìn đường, không quay lại, \"tôi quen bố mẹ cháu, ở bến cuối có cơ quan của mẹ cháu, phụ huynh đón cháu ở đó.\" Nghe xong, đến tôi cũng thấy như mẹ đang đợi ở bến cuối. Ông Sato vẫn như thường, như chưa có chuyện gì, chăm chú lái chiếc \"hộp sắt lớn\". Chúng tôi chỉ thấy bóng lưng cao lớn, nghiêm nghị của ông, vẫn toát lên niềm tự hào với công việc."], ["", "就这样，佐藤先生这时成了我心中的英雄。他就像能干的律师一样为我巧妙地辩护，使我摆脱了人们的好奇，我更喜欢他了。可是我从来没有跟他聊过天儿，我很想跟他说话，可是我怕他因为认真工作而不理我，所以只能坐在他的后面，看着他高大的背影。后来，我由于崇拜佐藤先生，想当宇航员的梦想竟然变成了当公共汽车司机！", "Jiù zhèyàng, Zuǒténg xiānsheng zhèshí chéng le wǒ xīnzhōng de yīngxióng. Tā jiù xiàng nénggàn de lǜshī yíyàng wèi wǒ qiǎomiào dì biànhù, shǐ wǒ bǎituō le rénmen de hàoqí, wǒ gèng xǐhuan tā le. Kěshì wǒ cónglái méiyǒu gēn tā liáoguò tiānr, wǒ hěn xiǎng gēn tā shuōhuà, kěshì wǒpà tā yīnwèi rènzhēn gōngzuò ér bùlǐ wǒ, suǒyǐ zhǐnéng zuòzài tā de hòumiàn, kànzhe tā gāodà de bèiyǐng. Hòulái, wǒ yóuyú chóngbài Zuǒténg xiānsheng, xiǎngdāng yǔhángyuán de mèngxiǎng jìngrán biànchéng le dāng gōnggòngqìchē sījī!", "Cứ thế, ông Sato trở thành người hùng trong lòng tôi. Ông như một luật sư giỏi khéo léo bào chữa cho tôi, giúp tôi thoát khỏi sự tò mò của mọi người, tôi càng quý ông. Nhưng tôi chưa từng trò chuyện với ông; tôi rất muốn, nhưng sợ ông vì chăm chú làm việc mà không để ý tới tôi, nên chỉ ngồi phía sau nhìn bóng lưng ấy. Về sau, vì sùng bái ông Sato, ước mơ làm phi hành gia của tôi lại biến thành làm tài xế xe buýt!"], ["", "现在，作为一个开始走向社会的青年，我回忆起佐藤先生，仍然很佩服他对工作认真的态度。虽然他只是一个普普通通的司机，可是他是我童年时眼中的英雄。", "Xiànzài, zuòwéi yíge kāishǐ zǒuxiàng shèhuì de qīngnián, wǒ huíyìqǐ Zuǒténg xiānsheng, réngrán hěn pèifú tā duì gōngzuò rènzhēn de tàidù. Suīrán tā zhǐshì yíge pǔpǔtōngtōng de sījī, kěshì tā shì wǒ tóngnián shí yǎnzhōng de yīngxióng.", "Giờ đây, là một thanh niên bắt đầu bước vào xã hội, nhớ lại ông Sato, tôi vẫn rất khâm phục thái độ làm việc nghiêm túc của ông. Tuy chỉ là một tài xế bình thường, ông là người hùng trong mắt tôi thời thơ ấu."]]}], "fn": [["除了……以外", "", "Ngoài… ra.", "除了父亲以外，佐藤是我遇见的第一个英雄。"], ["由于", "", "Do, vì (văn viết), đứng đầu vế nguyên nhân.", "由于崇拜佐藤先生，我想当公共汽车司机。"], ["连……也……", "", "Ngay cả… cũng….", "连我也觉得我的母亲会在终点站等着我。"], ["越来越", "", "Ngày càng…; không thêm 很 phía sau.", "他们的盘问越来越厉害了。"], ["V + 着", "", "Trạng thái đang tiếp diễn.", "外边下着细细的雨。"]], "adv": [], "ex2": [["六岁那年，作者在公共汽车上看到了什么？", "河、绿油油的山野和成百上千只奶牛。", ["高楼和地铁。", "大海和沙滩。"]], ["作者为什么每天去坐公共汽车？", "他迷上了坐车，而且6岁以下坐车免费。", ["他要去幼儿园上课。", "妈妈让他去买东西。"]], ["佐藤先生是一个什么样的司机？", "穿着整齐，对自己的工作很骄傲。", ["很爱跟乘客聊天。", "常常迟到。"]], ["大人们盘问作者时，佐藤先生怎么做？", "他说认识作者的父母，母亲在终点站接他。", ["他让作者马上下车。", "他给作者的妈妈打电话。"]], ["作者后来的梦想变成了什么？", "当公共汽车司机。", ["当宇航员。", "当律师。"]], ["现在作者最佩服佐藤先生什么？", "他对工作认真的态度。", ["他的司机帽。", "他开车开得很快。"]]]}});
})(window.CONTENT);
